-- Derpy Resource Overhaul: stores flows. Raids, sacks and razes carry stock out of a settlement's
-- stores into the taker's; trade agreements carry it between partners; a ledger and a 20-turn
-- history feed the Stores panel's chart.
-- Spec: docs/superpowers/specs/2026-10-02-resource-overhaul-stores-flows-design.md
--
-- THE SHIPPED FILE IS GENERATED. tools/gen_mr_ui.py puts DERPY_MR_FLOWS_DEFAULTS (the rates),
-- DERPY_MR_FLOWS_KIND (the factor each move books to) and DERPY_MR_FLOWS_GOODS (the 54 goods) in
-- front of this source. Edit this file, then run py tools/gen_mr_ui.py.
--
-- MULTIPLAYER: every change here happens inside a model event (turn start, occupation decision,
-- an army walking into a shipment's marker) or comes from a click through F.request, a UITrigger
-- every machine runs alike.

DERPY_MR_FLOWS = DERPY_MR_FLOWS or {}
local F = DERPY_MR_FLOWS
local KIND = DERPY_MR_FLOWS_KIND

F.PREFIX = "derpy_mr_store_"
F.MCT = "derpy_more_resources"
F.RAIDING = "MILITARY_FORCE_ACTIVE_STANCE_TYPE_LAND_RAID"   -- CA's own test, wh2_twa03_rakarth.lua
F.DECISION = { occupation_decision_sack = "sack", occupation_decision_raze_without_occupy = "raze" }
F.state = F.state or { factions = {} }
F.cost = { raid = 0, turn = 0 }       -- seconds this round, for the in-game measurement only
F.SAVE = "derpy_mr_flows"
F.HISTORY = 20
function F.say(msg)
    pcall(out, "[derpy_mr_flows] " .. tostring(msg))
end

-- AT LEAST 1 WHEN ANY IS HELD: floored alone, a store under 100/pct never loses anything.
function F.share(held, pct)
    if held <= 0 or pct <= 0 then return 0 end
    return math.max(1, math.floor(held * pct / 100))
end

function F.pool(region, stem)
    local ok, p = pcall(function()
        return region:pooled_resource_manager():resource(F.PREFIX .. stem)
    end)
    if ok and p and not p:is_null_interface() then return p end
    return nil
end

function F.held(region, stem)
    local p = F.pool(region, stem)
    if not p then return 0 end
    return p:value()
end

function F.free(region, stem)
    local p = F.pool(region, stem)
    if not p then return 0 end
    return math.max(0, p:maximum_value() - p:value())
end

-- ---- rates --------------------------------------------------------------------------------
-- FROZEN INTO THE SAVE the first time they are read, which is the first turn start. MCT's own
-- campaign gating is dead code (the Zharr Exchange's finding), so the save is the lock.
function F.mct(key)
    if not get_mct then return nil end
    local ok, v = pcall(function()
        local m = get_mct():get_mod_by_key(F.MCT)
        if not m then return nil end
        local o = m:get_option_by_key(key)
        if not o then return nil end
        return o:get_finalized_setting()
    end)
    if ok then return v end
    return nil
end

-- MULTIPLAYER TAKES THE DEFAULTS: two machines' MCT settings can differ and a move must not.
function F.read_rates()
    local mp = false
    pcall(function() mp = cm:is_multiplayer() end)
    local r = {}
    for k, d in pairs(DERPY_MR_FLOWS_DEFAULTS) do
        local v = nil
        if not mp then v = F.mct(k) end   -- NOT `not mp and F.mct(k) or nil`: an unticked box is false
        if type(v) ~= type(d) then v = d end
        if type(v) == "number" then v = math.floor(v + 0.5) end
        r[k] = v
    end
    return r
end

-- A SAVE FROM BEFORE A SWITCH EXISTED has no key for it, and nil read as "off": phases 4 and 7
-- never ran in such a save (measured live 2026-10-02). A missing key takes its value now and
-- is frozen with the rest; the keys already frozen do not move.
-- A READ, never a write: the panel calls it, and opening the panel before the first turn start
-- froze the settings there (single player: the MCT then did nothing). F.freeze_rates writes.
function F.rates()
    local r = F.state.rates
    if not r then return F.read_rates() end
    for k in pairs(DERPY_MR_FLOWS_DEFAULTS) do
        if r[k] == nil then
            local out = F.read_rates()
            for k2, v in pairs(r) do out[k2] = v end
            -- Older saved settings predate army provisions, whose original default was off.
            if r.army_provisions == nil then out.army_provisions = false end
            return out
        end
    end
    return r
end

-- THE ONE WRITER, at every faction's turn start: the same point on every machine.
function F.freeze_rates()
    F.state.rates = F.rates()
    return F.state.rates
end

-- "TURN OFF RANDOM DILEMMAS" (MCT, default off): the campaign director's generation is one global
-- switch. CA sets it only on a new game's first tick (wh3_tol_helpers.lua:6), which suggests the
-- save keeps it; set at every load anyway, which costs nothing if so. Never turned back ON: the
-- setting is frozen for the campaign, and a Tides of Lore start turns generation off itself.
-- Scripted dilemmas still fire with it off: CA's prologue turns it off, then triggers its story
-- dilemmas (wh3_prologue_kislev_expedition_story_panels.lua:165-208).
function F.quiet_dilemmas()
    if F.rates().random_off then cm:toggle_dilemma_generation(false) end
end

function F.is_human(fkey)
    if not fkey or fkey == "" then return false end
    local ok, h = pcall(function() return cm:get_faction(fkey):is_human() end)
    return ok and h == true
end

-- With "goods move between other factions" off, a move runs only with a player on one side.
function F.allowed(a, b)
    if F.rates().ai then return true end
    return F.is_human(a) or F.is_human(b)
end

-- ---- the ledger: human factions only, since only they see the panel ------------------------
function F.book(fkey)
    local b = F.state.factions[fkey]
    if not b then
        b = { turns = {}, total = {}, last = {}, now = {} }
        F.state.factions[fkey] = b
    end
    return b
end

function F.log(fkey, stem, field, n)
    if n <= 0 or not F.is_human(fkey) then return end
    local now = F.book(fkey).now
    now[stem] = now[stem] or {}
    now[stem][field] = (now[stem][field] or 0) + n
end

-- ---- moving stock ---------------------------------------------------------------------------
-- TWO TRANSACTIONS, NOT entity_transfer_pooled_resource: the receiver's share is clamped to its
-- free space here, so what does not fit is lost by rule (spec section 2) rather than by whatever
-- the engine does at the brim. The junction is two-way (gen_resource_overhaul.py FLOW_FACTORS),
-- so one id books both ends. `to` nil (a taker with no settlements) destroys the stock.
-- `from` nil is a source whose pools are already gone (a raze): nothing to book against it.
function F.move(from, to, stem, n, kind, from_key, to_key)
    if from then n = math.min(n, F.held(from, stem)) end
    if n <= 0 then return 0 end
    local j = F.PREFIX .. stem .. "_" .. kind
    if from then F.pool_add(from, j, -n) end
    local got = 0
    if to then
        got = math.min(n, F.free(to, stem))
        if got > 0 then F.pool_add(to, j, got) end
    end
    F.log(from_key, stem, kind .. "_out", n)
    F.log(to_key, stem, kind .. "_in", got)
    return got
end

-- The faction's settlement nearest (x, y); nil when it holds none.
function F.nearest(faction, x, y)
    local best, bd = nil, nil
    local rl = faction:region_list()
    for i = 0, rl:num_items() - 1 do
        local r = rl:item_at(i)
        local st = r:settlement()
        if not st:is_null_interface() then
            local dx, dy = st:logical_position_x() - x, st:logical_position_y() - y
            local d = dx * dx + dy * dy
            if bd == nil or d < bd then best, bd = r, d end
        end
    end
    return best
end

-- Every good in `region` with stock: pct of it to the taker's settlement nearest (x, y), the
-- taking army's position (plan deviation 3: the settlement may already be null at a raze).
-- `held` (stem -> n) is the battle's reading when the region's pools are gone.
function F.take(region, victim_key, taker, pct, kind, x, y, held)
    if pct <= 0 then return 0 end
    local to = F.nearest(taker, x, y)
    local from = not held and region or nil
    local taken = 0
    for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
        local n = F.share(held and held[g.stem] or F.held(region, g.stem), pct)
        if n > 0 then
            F.move(from, to, g.stem, n, kind, victim_key, taker:name())
            taken = taken + n
        end
    end
    return taken
end

-- The owner stock may be taken from, or nil: no region, no owner, a rebel, or the taker itself.
function F.victim(region, taker)
    if not region or region:is_null_interface() or region:is_abandoned() then return nil end
    local v = region:owning_faction()
    if v:is_null_interface() or v:is_rebel() or v:name() == taker:name() then return nil end
    return v
end

-- The raid this character makes: region, victim, taker; nil when it takes from nobody.
function F.raid_target(character)
    if not character:has_military_force() then return nil end
    if character:military_force():active_stance() ~= F.RAIDING then return nil end
    local taker = character:faction()
    local region = character:region()
    local v = F.victim(region, taker)
    if not v then return nil end      -- NO WAR TEST: CA pays raid gold from any owner's land
    if not F.allowed(taker:name(), v:name()) then return nil end
    return region, v, taker
end

function F.on_character_turn_start(character)
    local region, v, taker = F.raid_target(character)
    if not region then return end
    F.take(region, v:name(), taker, F.rates().raid, KIND.raid,
           character:logical_position_x(), character:logical_position_y())
end

-- WHAT F.take WOULD TAKE from `region` at `pct`: {total, parts = {{stem, n}}}, most first, or nil
-- when nothing. Read only - the plates' number, by the same F.share the move uses.
function F.preview(region, pct)
    local parts, total = {}, 0
    for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
        local n = F.share(F.held(region, g.stem), pct)
        if n > 0 then
            parts[#parts + 1] = { stem = g.stem, n = n }
            total = total + n
        end
    end
    if total == 0 then return nil end
    table.sort(parts, function(a, b)
        if a.n ~= b.n then return a.n > b.n end
        return a.stem < b.stem
    end)
    return { total = total, parts = parts }
end

-- WHAT THE RAID TAKES NEXT TURN, for the army's plate: F.preview plus `to`, the region key it
-- lands in (nil for a horde). Nothing before the rates are frozen: a UI read must not freeze
-- them on one machine ahead of the turn start that does it everywhere.
function F.raid_preview(character)
    local rates = F.state.rates
    if not rates or (rates.raid or 0) <= 0 then return nil end
    local region, _, taker = F.raid_target(character)
    if not region then return nil end
    local pv = F.preview(region, rates.raid)
    if not pv then return nil end
    local to = F.nearest(taker, character:logical_position_x(), character:logical_position_y())
    pv.to = to and to:name() or nil
    return pv
end

-- WHAT A CAPTURE CHOICE DOES TO `region`'s STORES, for the capture panel: F.preview plus `lost`,
-- true when the taker holds no settlement to carry it to. "sack" and "raze" take their share
-- (nil for the cases F.on_occupation skips: rebels, its own settlement); "occupy" keeps the
-- whole store, which stays with the settlement, rebels' included. nil for any other kind.
function F.capture_preview(region, taker, kind)
    local rates = F.state.rates
    if not rates then return nil end
    local pct
    if kind == "occupy" then
        if region:is_abandoned() or region:owning_faction():name() == taker:name() then return nil end
        local pv = F.preview(region, 100)
        if pv then pv.lost = false end
        return pv
    elseif kind == "sack" or kind == "raze" then
        pct = rates[kind] or 0
    end
    if not pct or pct <= 0 then return nil end
    if not F.victim(region, taker) then return nil end
    local pv = F.preview(region, pct)
    if pv then pv.lost = taker:region_list():num_items() == 0 end
    return pv
end

function F.on_occupation(context)
    -- THE BATTLE'S READING IS SPENT BY ANY DECISION, first: left by an occupy or a skipped case,
    -- it fed a later raze of the same settlement stock that was no longer there
    local region = context:garrison_residence():region()
    local at_battle = F.at_battle[region:name()]
    if F.at_battle_turn[region:name()] ~= cm:model():turn_number() then at_battle = nil end   -- a failed siege's
    F.at_battle[region:name()], F.at_battle_turn[region:name()] = nil, nil
    local what = F.DECISION[context:occupation_decision_type()]
    if not what then return end
    local character = context:character()
    local taker = character:faction()
    local victim = context:previous_owner()        -- empty for rebels
    if victim == nil or victim == "" or victim == taker:name() then return end
    if not F.allowed(taker:name(), victim) then return end
    if F.pool(region, DERPY_MR_FLOWS_GOODS[1].stem) then
        at_battle = nil                            -- live stores win over the battle's reading
    elseif not at_battle then
        F.say("the stores of " .. region:name() .. " could not be read at the " .. what
              .. " - nothing taken")
        return
    end
    F.take(region, victim, taker, F.rates()[what], KIND[what],
           character:logical_position_x(), character:logical_position_y(), at_battle)
end

-- THE STORES AS THEY WERE AT THE BATTLE: the engine drops a razed region's pools before the
-- occupation decision fires (measured 2026-10-02, Venom Glade). CA's Bloodgrounds caches the
-- settlement the same way, on the same event. Not saved: the decision follows in the same session.
F.at_battle, F.at_battle_turn = {}, {}
function F.on_battle(context)
    local pb = context:pending_battle()
    if not pb:has_contested_garrison() then return end
    local region = pb:contested_garrison():region()
    local t = {}
    for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
        local h = F.held(region, g.stem)
        if h > 0 then t[g.stem] = h end
    end
    F.at_battle[region:name()], F.at_battle_turn[region:name()] = t, cm:model():turn_number()
end

-- ---- trade --------------------------------------------------------------------------------
function F.capital(faction)
    if faction:has_home_region() then return faction:home_region() end
    local rl = faction:region_list()
    if rl:num_items() > 0 then return rl:item_at(0) end
    return nil
end

-- TRADE REACH (author, 2026-10-22): an agreement moves resources and duty only while a road joins the two
-- settlements that is no longer than the reach and stays off land at war with, or very unfriendly to, either
-- side (terrain_routes.lua R.reach). One answer per pair per turn, worked out by the economy at a turn start,
-- the same on every machine. mode nil: the economy, recomputed each turn. 'peek': any answer already known,
-- or nil. 'show': as peek, else worked out now - single player only, where nothing has to stay in step.
F.ROAD_PER_TURN = 40   -- hexes a turn, F.route_turns' pace
F.REACH_WHY = { far = "Too far for trade", enemy = "Cut off by enemy lands" }
F.reach_known = F.reach_known or {}
function F.invalidate_reach()
    F.reach_known = {}
    local R = DERPY_MR_TERRAIN_ROUTES
    if R then
        -- the map checks its roads again (R.path gives back those whose land still judges the same) and keeps
        -- the old lines up meanwhile; searches under way start again on today's verdicts
        R.queue, R.queued = {}, {}
        R.epoch = (R.epoch or 0) + 1
        R.dirty = true
    end
end
function F.reach(a, b, mode)
    local R = DERPY_MR_TERRAIN_ROUTES
    if not (R and R.reach) or not a or not b then return true end
    if b:name() < a:name() then a, b = b, a end
    local key, turn = a:name() .. ">" .. b:name(), cm:model():turn_number()
    local hit = F.reach_known[key]
    if hit and (mode or hit.turn == turn) then return hit.ok, hit.why, hit.path end
    if mode == "peek" or (mode == "show" and cm:is_multiplayer()) then return nil end
    local ok, why, path = R.reach(a, b, F.rates().reach * F.ROAD_PER_TURN)
    F.reach_known[key] = { turn = turn, ok = ok, why = why, path = path }
    return ok, why, path
end

function F.trade_reach(a, b, mode)
    return F.reach(F.capital(a), F.capital(b), mode)
end

-- The panel's list: this faction's agreement partners whose trade is cut off, with why, or blockaded, by whom
-- (Part C). Known answers only. A pair both cut off and blockaded is listed once, with the reach reason.
function F.cut_off(faction)
    local out, partners = {}, faction:factions_trading_with()
    if type(partners) == "boolean" then return out end
    for i = 0, partners:num_items() - 1 do
        local p = partners:item_at(i)
        local ok, why = F.trade_reach(faction, p, "peek")
        local by = ok ~= false and F.blockaded(faction:name(), p:name())
        if ok == false then out[#out + 1] = { key = p:name(), why = F.REACH_WHY[why] }
        elseif by then out[#out + 1] = { key = p:name(), by = by } end
    end
    table.sort(out, function(x, y) return x.key < y.key end)
    return out
end

-- Snapshots live only for this allocation; recipient views include cargo already on the road.
function F.stock_views(faction)
    local views, provinces = {}, F.provinces(faction)
    local rl = faction:region_list()
    for i = 0, rl:num_items() - 1 do
        local r = rl:item_at(i)
        if not r:is_null_interface() then views[#views + 1] = F.stock_view(faction, r, provinces) end
    end
    table.sort(views, function(a, b) return a.region:name() < b.region:name() end)
    return views
end

function F.stock_adjust(v, stem, n)
    v.held[stem] = (v.held[stem] or 0) + n
    local g = F.GOOD[stem]
    if not g.rare then v.totals[g.use] = (v.totals[g.use] or 0) + n end
end

function F.fullest(views, stem)
    local best, amount = nil, 0
    for _, v in ipairs(views) do
        local n = F.available_stock(v, stem)
        if n > amount or (n == amount and n > 0 and v.region:name() < best.region:name()) then
            best, amount = v, n
        end
    end
    return best, amount
end

-- The exporter's cheapest store with stock (one base, so the lowest multiplier is the lowest price); F.cheapest is the recruitment draw's.
function F.cheapest_store(views, stem)
    local best, amount, low = nil, 0, nil
    for _, v in ipairs(views) do
        local n, mult = F.available_stock(v, stem), F.price_mult(v, stem)
        -- views arrive sorted by region key, so a full tie keeps the first
        if n > 0 and mult and (not best or mult < low or (mult == low and n > amount)) then
            best, amount, low = v, n, mult
        end
    end
    return best, amount
end

-- Preview only adjusts disposable stock views, in the same partner/good order as a real turn.
function F.trade(exporter, preview)
    local goods = {}
    if F.rates().trade <= 0 then return goods end
    local partners = exporter:factions_trading_with()
    if type(partners) == "boolean" then return goods end
    local ordered, sources = {}, nil
    for i = 0, partners:num_items() - 1 do ordered[#ordered + 1] = partners:item_at(i) end
    table.sort(ordered, function(a, b) return a:name() < b:name() end)
    for _, partner in ipairs(ordered) do
        local stems
        stems, sources = F.trade_pair(exporter, partner, sources, preview)
        if preview and stems then goods[partner:name()] = stems end
    end
    return goods
end

-- What a basket is worth in whole gold at each good's local sell price (hundredths in `prices`).
function F.cargo_value(basket, prices)
    local v = 0
    for stem, n in pairs(basket) do v = v + F.gold(n, F.sell_price(prices[stem])) end
    return v
end

-- ONE PARTNER'S TURN OF TRADE: the road, the plan, the toll, then the goods. `sources` are the exporter's
-- stock views, shared by every partner of the round (made here when nil) and handed back. In preview the
-- planned stems come back and only the views change; nil when nothing is planned. opts.blockade_ok skips
-- the blockade test (Part E's Blockade runner).
function F.trade_pair(exporter, partner, sources, preview, opts)
    local pct = F.rates().trade
    if pct <= 0 then return nil, sources end
    if F.edict(exporter:name(), "workshops") == "merchant" then pct = pct * F.EDICT.merchant_trade end
    local to = F.capital(partner)
    if not (to and F.allowed(exporter:name(), partner:name())) then return nil, sources end
    -- the road F.reach just worked out for this pair, kept for the convoy
    local open, _, path = F.trade_reach(exporter, partner, preview and "peek" or nil)
    if not open then return nil, sources end
    -- A BLOCKADE stops this pair's trade for the turn; the real trade records it for the panel, the map and the duty
    if not (opts and opts.blockade_ok) then
        local by = F.blockade(exporter, partner, path)
        if not preview then F.record_blockade(exporter:name(), partner:name(), by) end
        if by then return nil, sources end
    end
    sources = sources or F.stock_views(exporter)
    local dest, takers, plan = F.stock_view(partner, to), F.toll_takers(exporter, partner, path), {}
    for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
        if not F.stopped(exporter:name(), "export", g.stem)
            and not F.stopped(partner:name(), "import", g.stem) then
            local source, removable = F.cheapest_store(sources, g.stem)
            -- at least 1 (author, 2026-10-30): floored, 226 of 441 computer goods on open roads moved nothing
            local n = math.min(F.share(removable, pct), F.import_need(dest, g.stem))
            if source and n > 0 then
                -- uphill only: the destination's price must clear the source's price plus the spread and the toll
                local ps, pd = F.local_price(source, g.stem, exporter:name()), F.local_price(dest, g.stem, partner:name())
                if pd ~= nil and ps ~= nil and pd >= F.buy_price(ps) + F.toll_unit(ps, #takers) then
                    plan[#plan + 1] = { stem = g.stem, source = source, n = n, ps = ps }
                    -- the views keep a good planned this round from being sent again to the next partner
                    F.stock_adjust(source, g.stem, -n)
                    F.stock_adjust(dest, g.stem, n)
                end
            end
        end
    end
    if #plan == 0 then return nil, sources end
    local function unplan(p)
        F.stock_adjust(p.source, p.stem, p.n)
        F.stock_adjust(dest, p.stem, -p.n)
    end
    local basket, prices = {}, {}
    for _, p in ipairs(plan) do basket[p.stem], prices[p.stem] = p.n, p.ps end
    -- AN EXPORTER THAT CANNOT PAY THE TOLLS sends this partner nothing, and its plan goes back into the views
    local _, sum = F.tolls(F.cargo_value(basket, prices), takers)
    -- a preview pays nothing, so it counts what this round's earlier partners would have paid: tolls and guards
    local spent = preview and sources.toll_spent or 0
    -- nothing due is never refused: a faction in debt still trades where no toll is taken
    if sum > 0 and sum > exporter:treasury() - spent then
        for _, p in ipairs(plan) do unplan(p) end
        return nil, sources
    end
    if preview then
        -- the guards' fee comes after the toll, from the same treasury, and only when it is there (F.guard_fee)
        local fee = F.guards_on(exporter:name())
            and math.floor(F.cargo_value_base({ f = exporter:name(), basket = basket }) * F.ROAD.guard_pct / 100) or 0
        sources.toll_spent = spent + sum + (fee <= exporter:treasury() - spent - sum and fee or 0)
        local stems = {}
        for _, p in ipairs(plan) do stems[#stems + 1] = p.stem end
        return stems, sources
    end
    local convoy = nil
    for _, p in ipairs(plan) do
        if F.route_goods(p.source.region, p.stem, -p.n, KIND.trade) then
            -- AGREEMENT CARGO (spec 2026-10-23, 5.1): debited here, landed when the convoy arrives.
            -- The convoy is made at the FIRST good taken and each later good joins it at once, so a
            -- throw at a later good leaves what was already taken on the road, not lost.
            convoy = convoy or F.convoy_new(exporter, partner, {}, path)
            convoy.basket[p.stem] = (convoy.basket[p.stem] or 0) + p.n
            F.log(exporter:name(), p.stem, KIND.trade .. "_out", p.n)
        else
            unplan(p)   -- the engine refused the debit: nothing left, nothing to count
        end
    end
    -- THE TOLL ON WHAT LEFT, not on the plan: less can leave than was planned, never more
    if convoy then
        local due = F.tolls(F.cargo_value(convoy.basket, prices), takers)
        if next(due) and F.pay_tolls(exporter:name(), due) then convoy.tolls = due end
        F.guard_fee(exporter, convoy)
    end
    return nil, sources
end

-- ---- import duty (docs/superpowers/specs/2026-10-08-resource-overhaul-import-duty-design.md) --
-- At its turn start a faction pays each trade partner a share of what that partner made this
-- turn, at what CA's trade pays a unit (g.value, gen_mr_ui.CA_UNIT_VALUE), and the gold goes to
-- the partner. NEVER the Exchange's market price: on it one turn's output cost a partner its
-- whole treasury (seen in game 2026-10-08, 6,128 gold for 44 units).
F.MADE = "derpy_mr_stocked"   -- the production twin rows' factor: this turn's output (measured 2026-10-08)

-- What a faction's settlements made this turn, priced. One walk of its stores, kept for the turn:
-- every partner of the faction asks the same question.
function F.made_value(faction)
    local fkey, turn = faction:name(), cm:model():turn_number()
    if not (F.made_cache and F.made_cache.turn == turn) then F.made_cache = { turn = turn, of = {} } end
    if F.made_cache.of[fkey] then return F.made_cache.of[fkey] end
    local total, rl = 0, faction:region_list()
    for i = 0, rl:num_items() - 1 do
        local list = rl:item_at(i):pooled_resource_manager():resources()
        for j = 0, list:num_items() - 1 do
            local p = list:item_at(j)
            local k = not p:is_null_interface() and p:key() or ""
            local g = string.sub(k, 1, #F.PREFIX) == F.PREFIX and F.GOOD[string.sub(k, #F.PREFIX + 1)]
            -- a good the exporter holds back leaves no trade agreement, so it carries no duty
            if g and not F.stopped(fkey, "export", g.stem) then
                local fl = p:factors()
                for n = 0, fl:num_items() - 1 do
                    local fc = fl:item_at(n)
                    if fc:key() == F.MADE and fc:value() > 0 then total = total + fc:value() * g.value end
                end
            end
        end
    end
    F.made_cache.of[fkey] = total
    return total
end

-- Never more than the payer holds: a faction with an empty treasury pays nothing and runs no debt.
function F.duty(faction)
    local pct = F.rates().duty or 0
    -- pct 0 would charge 0 anyway (a mutant proved it); returning here only skips the walk
    if pct <= 0 or not F.uses_stores(faction) then return end
    local partners = faction:factions_trading_with()
    if type(partners) == "boolean" then return end   -- as F.trade: measured for some faction
    local fkey = faction:name()
    for i = 0, partners:num_items() - 1 do
        local partner = partners:item_at(i)
        -- BOTH WAYS WHEREVER A PLAYER IS ONE SIDE (author, 2026-10-08), as trade itself runs
        -- (F.allowed): with other factions' stores off a computer partner paid the player nothing
        -- while the player paid it, against the row's own "each partner pays you the same"
        -- no trade, no duty: a partner out of reach (F.reach) pays and is paid nothing
        -- nor a blockaded one (Part C)
        local due = (not F.allowed(fkey, partner:name()) or not F.trade_reach(faction, partner) or F.blockaded(fkey, partner:name())) and 0 or math.min(math.floor(F.made_value(partner) * pct / 100), math.max(0, faction:treasury()))
        if due > 0 then
            cm:treasury_mod(fkey, -due)   -- negative: CA's own scripts do (spec section 2)
            cm:treasury_mod(partner:name(), due)
            F.book_duty(fkey, partner:name(), "paid", due)
            F.book_duty(partner:name(), fkey, "got", due)
        end
    end
end

-- Booked for humans only, by game turn; the panel shows the turn before, which every faction in
-- the round has finished paying into. `field` is the book's "duty" or "tolls" (Part C): one shape.
function F.book_gold(field, fkey, other, way, n)
    if not F.is_human(fkey) then return end
    local b, turn = F.book(fkey), cm:model():turn_number()
    b[field] = b[field] or {}
    local book = b[field]
    for t in pairs(book) do
        if t < turn - 1 then book[t] = nil end
    end
    local d = book[turn] or { paid = 0, got = 0, by = {} }
    book[turn] = d
    d[way] = d[way] + n
    d.by[other] = d.by[other] or { paid = 0, got = 0 }
    d.by[other][way] = d.by[other][way] + n
end

function F.gold_last(field, fkey)
    local b = F.state.factions[fkey]
    return b and b[field] and b[field][cm:model():turn_number() - 1] or nil
end

function F.book_duty(fkey, other, way, n) return F.book_gold("duty", fkey, other, way, n) end
function F.duty_last(fkey) return F.gold_last("duty", fkey) end

-- ---- the player's trade switches (the Stores panel's Trade tab) ---------------------------
-- Saved in the faction's book as stop[dir][stem] = true; everything allowed by default.
-- Humans only: a computer-run faction has no panel to set them from.
F.DIRS = { export = true, import = true }
F.TAG = "dmr1"
-- in place of a resource's key: every resource one way at once (the panel's four buttons)
F.ALL_STOP, F.ALL_ALLOW = "all_stop", "all_allow"

function F.stopped(fkey, dir, stem)
    local b = F.state.factions[fkey]
    return b ~= nil and b.stop ~= nil and b.stop[dir] ~= nil and b.stop[dir][stem] == true
end

function F.toggle(fkey, dir, stem)
    if not F.DIRS[dir] or not F.is_human(fkey) then return end
    local known = false
    for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
        if g.stem == stem then known = true end
    end
    if not known then return end
    local b = F.book(fkey)
    b.stop = b.stop or {}
    b.stop[dir] = b.stop[dir] or {}
    if F.stopped(fkey, dir, stem) then b.stop[dir][stem] = nil else b.stop[dir][stem] = true end
end

-- `what` is a resource's key (toggle it) or ALL_STOP / ALL_ALLOW (set every one, not a toggle)
function F.apply(fkey, dir, what)
    if what ~= F.ALL_STOP and what ~= F.ALL_ALLOW then
        F.toggle(fkey, dir, what)
    elseif F.DIRS[dir] and F.is_human(fkey) then
        local b = F.book(fkey)
        b.stop = b.stop or {}
        b.stop[dir] = {}
        if what == F.ALL_STOP then
            for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do b.stop[dir][g.stem] = true end
        end
    end
    if dir == "export" and F.is_human(fkey) then F.hold_exports(fkey) end
end

-- A STOPPED EXPORT LEAVES CA'S TRADE TOO (TRADE_RESOURCES.md 28): every production row, ours and
-- CA's, has a negated twin gated on its owner holding the hidden faction bundle derpy_mr_hold_<stem>,
-- so a held good's production is cancelled exactly - same lore gates, same damage, never below
-- zero - and it leaves the trade agreements with exactly its income, from the next turn. A flat
-- -1000 was measured to make phantom exports of goods the faction never made. The stores fill from
-- their own rows and are untouched. Imports have no such lever: they are the partner's exports.
F.HOLD_BUNDLE, F.HOLD_PREFIX = "derpy_mr_exports_held", "derpy_mr_hold_"
function F.hold_exports(fkey)
    local f = cm:get_faction(fkey)
    if not f or f:is_null_interface() then return end
    local any = false
    for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
        local key, held = F.HOLD_PREFIX .. g.stem, F.stopped(fkey, "export", g.stem)
        any = any or held
        if held and not f:has_effect_bundle(key) then cm:apply_effect_bundle(key, fkey, 0)
        elseif not held and f:has_effect_bundle(key) then cm:remove_effect_bundle(key, fkey) end
    end
    -- the visible record; removed first because a save from before 2026-10-08 carries a custom
    -- bundle under this key holding -1000 on every good
    cm:remove_effect_bundle(F.HOLD_BUNDLE, fkey)
    if any then cm:apply_effect_bundle(F.HOLD_BUNDLE, fkey, 0) end
end

-- A trade switch: one resource's key, or ALL_STOP / ALL_ALLOW (F.request, below).
function F.send(fkey, dir, stem) return F.request(fkey, dir, stem) end

function F.on_ui_trigger(context)
    local parts = F.parse(context:trigger())
    if not parts then return end
    local cqi = context:faction_cqi()
    for _, k in ipairs(cm:get_human_factions()) do
        local f = cm:get_faction(k)
        if f and not f:is_null_interface() and f:command_queue_index() == cqi then
            F.dispatch(k, parts)
            local S = DERPY_MR_STORES
            if S and S.refresh then pcall(S.refresh) end
            return
        end
    end
end

-- ---- using the stores (spending spec section 2, phase 4) ----------------------------------
-- Every settlement eats provisions at its owner's turn start, and well-stocked stores give a
-- region bundle each: Well fed, Garrison stocked, Comforts (gen_resource_overhaul.USE_BUNDLES).
F.NEED = 2               -- provisions a turn per settlement level
F.FED_TURNS = 5          -- Well fed: this many turns' need still held after eating
F.STOCKED_PCT = 25       -- Garrison stocked and Comforts: this share of one store's space
-- RENEWED EACH TURN, REMOVED THE TURN ITS CONDITION FAILS: 2, not 1, so a bundle cannot lapse
-- before growth is counted, and one the pass no longer reaches (the mod removed) still lapses.
F.BUNDLE_TURNS = 2

-- Daemons, the undead and Beastmen: their buildings make nothing, so they keep nothing to use.
function F.uses_stores(faction)
    local sc = faction:subculture()
    for _, t in ipairs(DERPY_MR_FLOWS_NO_STORES) do
        -- no plain flag: it corrupts the game's string library; the tokens are letters only
        if string.find(sc, "_" .. t .. "_") then return false end
    end
    return true
end

function F.eats(faction)
    if not F.uses_stores(faction) then return false end
    local sc = faction:subculture()
    return not string.find(sc, "_vmp_") and not string.find(sc, "_cst_")
end

-- One read of a settlement's stores: {stem = held}, and one store's space.
-- ONE READ A TURN START (2026-11-03: 7,500 whole reads in one computer round, 2.35 s): inside F.on_faction_turn_start
-- each settlement is read whole once and kept in F.stock_cache until F.pool_add writes to it. A reader gets copies,
-- as a stock view is changed in place.
local function copy(t)
    local c = {}
    for k, v in pairs(t) do c[k] = v end
    return c
end
function F.stock(region)
    local kept = F.stock_cache
    local rk = kept and region:name()
    local hit = kept and kept[rk]
    if hit then return copy(hit[1]), hit[2], copy(hit[3]) end
    local held, cap, capacity, n = {}, 0, {}, #F.PREFIX
    local list = region:pooled_resource_manager():resources()
    for i = 0, list:num_items() - 1 do
        local p = list:item_at(i)
        if not p:is_null_interface() then
            local k = p:key()
            if string.sub(k, 1, n) == F.PREFIX then
                local stem, max = string.sub(k, n + 1), p:maximum_value()
                held[stem], capacity[stem] = p:value(), max
                if max > cap then cap = max end
            end
        end
    end
    if kept then kept[rk] = { copy(held), cap, copy(capacity) } end
    return held, cap, capacity
end

-- Every write to a settlement's stores goes through here, which drops the turn start's kept copy first.
function F.pool_add(region, key, n)
    if F.stock_cache then F.stock_cache[region:name()] = nil end
    cm:entity_add_pooled_resource_transaction(region, key, n)
end

-- A RARE GOOD IS NEVER BULK (author, 2026-10-08): gromril is a war material but pays only for the
-- Workshop's own works, never an order, a supply, an event, upkeep or a holding bonus. Every
-- use-wide count and draw goes through F.bulk.
function F.bulk(use) return function(g) return g.use == use and not g.rare end end

function F.use_total(held, use)
    local n, pick = 0, F.bulk(use)
    for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
        if pick(g) then n = n + (held[g.stem] or 0) end
    end
    return n
end

-- THE DRAWING RULE (spec section 1): take n from the stores `pick(good)` names, the fullest
-- store first, then the next, until n is taken or they are empty. stocks = {{region, held}};
-- each `held` is updated as it goes. A tie goes by region key, then by resource key, so every
-- machine takes alike. Returns what was taken.
function F.draw_realm(stocks, pick, n, kind, fkey)
    local cands = {}
    for _, s in ipairs(stocks) do
        local rk = s.region:name()
        for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
            if pick(g) and (s.held[g.stem] or 0) > 0 then cands[#cands + 1] = { s = s, stem = g.stem, rk = rk } end
        end
    end
    table.sort(cands, function(a, b)
        local ha, hb = a.s.held[a.stem], b.s.held[b.stem]
        if ha ~= hb then return ha > hb end
        if a.rk ~= b.rk then return a.rk < b.rk end
        return a.stem < b.stem
    end)
    local taken = 0
    for _, c in ipairs(cands) do
        if taken >= n then break end
        local k = math.min(n - taken, c.s.held[c.stem])
        F.move(c.s.region, nil, c.stem, k, kind, fkey, nil)
        c.s.held[c.stem] = c.s.held[c.stem] - k
        taken = taken + k
    end
    return taken
end

-- One settlement's stores of one use.
function F.draw(region, held, use, n, kind, fkey)
    return F.draw_realm({ { region = region, held = held } }, F.bulk(use), n, kind, fkey)
end

-- A RACE'S OWN BUNDLE for a use (2026-11-01: growth does nothing for Chaos Dwarfs), and never two:
-- a captured settlement's former owner's goes
function F.bundle(rkey, region, use, on)
    local base = DERPY_MR_FLOWS_BUNDLES[use]
    local race, want, family = F.race(region:owning_faction()), base, { base }
    for _, v in ipairs(DERPY_MR_FLOWS_RACE_BUNDLES[base] or {}) do
        family[#family + 1] = v.key
        if v.race == race then want = v.key end
    end
    for _, b in ipairs(family) do
        if on and b == want then
            cm:apply_effect_bundle_to_region(b, rkey, F.BUNDLE_TURNS)
        elseif region:has_effect_bundle(b) then
            cm:remove_effect_bundle_from_region(b, rkey)
        end
    end
end

function F.upkeep_region(region, fkey, uses)
    local fed, war, lux = false, false, false
    if uses then
        local held, cap = F.stock(region)
        local level = 0
        pcall(function() level = region:settlement():primary_slot():building():building_level() end)
        local need = F.need(fkey) * level
        if need > 0 and F.eats(region:owning_faction()) then
            F.draw(region, held, "provisions", need, KIND.eat, fkey)
            -- five turns of NORMAL meals, whatever the Rations edict: on Rationing's own meals it took half the food
            fed = F.use_total(held, "provisions") >= F.FED_TURNS * F.NEED * level
        end
        local quarter = cap * F.STOCKED_PCT / 100
        war = cap > 0 and F.use_total(held, "war") >= quarter
        lux = cap > 0 and F.use_total(held, "luxuries") >= quarter
    end
    local rkey = region:name()
    F.bundle(rkey, region, "provisions", fed)
    F.bundle(rkey, region, "war", war)
    F.bundle(rkey, region, "luxuries", lux)
end

function F.upkeep(faction)
    local r = F.rates()
    if not r.upkeep or not (r.ai or faction:is_human()) then return end
    local fkey, uses = faction:name(), F.uses_stores(faction)
    local rl = faction:region_list()
    for i = 0, rl:num_items() - 1 do
        local region = rl:item_at(i)
        if not region:is_null_interface() then F.upkeep_region(region, fkey, uses) end
    end
end

-- ---- spoilage (design 2026-11-01, Part A) ----------------------------------------------------
-- Grain rots and Beer and Kvas sour, at the owner's turn start, on what a store holds above a safe
-- share of that good's space; the Great Granary raises Grain's. After the meals, before processing.
F.SPOIL = DERPY_MR_FLOWS_SPOIL

-- The safe share, in 100 of a store's space. A READ, never F.works_book: the panel asks it, and a
-- book made here would be a save entry for every faction a tooltip looked at.
function F.spoil_safe(fkey, stem)
    local b = F.state.factions[fkey]
    local lasting = b and b.works and b.works.lasting
    if stem == F.SPOIL.granary_good and lasting then
        for _, k in ipairs(F.SPOIL.granary_works) do
            if lasting[k] then return F.SPOIL.granary end
        end
    end
    return F.SPOIL.safe
end

function F.spoil_loss(held, capacity, rate, safe)
    local exposed = (held or 0) - math.floor((capacity or 0) * safe / 100)
    if exposed <= 0 then return 0 end
    return math.floor(exposed * rate / 100)
end

-- Whose stock spoils: the turn start and the forecast ask the same question.
function F.spoils(faction)
    local r = F.rates()
    return r.spoilage and (r.ai or faction:is_human()) and F.uses_stores(faction)
end

-- The loss rule without the gates: F.spoil asks them once a faction, F.spoil_due once a good.
local function spoil_due(v, stem)
    local rate = F.SPOIL.rates[stem]
    if not (rate and v.held[stem]) then return 0 end
    return F.spoil_loss(v.held[stem], v.capacity[stem], rate, F.spoil_safe(v.faction:name(), stem))
end

-- What `stem` will lose at the next turn start, in a stock view (or any {faction, held, capacity}).
function F.spoil_due(v, stem)
    if not (F.SPOIL.rates[stem] and F.spoils(v.faction)) then return 0 end
    return spoil_due(v, stem)
end

-- The tooltip's figures for one store: {rate, keep, due}; nil for a good that keeps here.
function F.spoil_info(faction, region, stem)
    local rate = F.SPOIL.rates[stem]
    if not (rate and F.spoils(faction)) then return nil end
    local held, _, capacity = F.stock(region)
    if not capacity[stem] then return nil end
    return { rate = rate, keep = math.floor(capacity[stem] * F.spoil_safe(faction:name(), stem) / 100),
             due = F.spoil_due({ faction = faction, held = held, capacity = capacity }, stem) }
end

function F.spoil(faction)
    if not F.spoils(faction) then return end
    local fkey = faction:name()
    local rl = faction:region_list()
    for i = 0, rl:num_items() - 1 do
        local region = rl:item_at(i)
        if not region:is_null_interface() then
            -- the spoiling pools alone: F.stock reads all ~60, in every settlement of every faction
            local v = { faction = faction, held = {}, capacity = {} }
            for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
                local p = F.SPOIL.rates[g.stem] and F.pool(region, g.stem)
                if p then
                    v.held[g.stem], v.capacity[g.stem] = p:value(), p:maximum_value()
                    local n = spoil_due(v, g.stem)
                    if n > 0 then F.move(region, nil, g.stem, n, KIND.spoil, fkey) end
                end
            end
        end
    end
end

-- ---- trade edicts (design 2026-11-01, Part B) ------------------------------------------------
-- Three realm policies, one option each in force: Rations, Workshops, Roads. Saved as
-- F.state.edicts[fkey][edict] = {o = option, at = turn of the change}; no entry is the default. A change
-- waits F.EDICT.cooldown turns. Growth, control and trade income are a faction bundle per option that is
-- not the default (F.edict_bundles); the rest is read by the rules themselves through F.edict.
F.EDICT = DERPY_MR_FLOWS_EDICTS

function F.edicts_on() return F.rates().edicts == true end

local function edict_known(which, option)
    local e = F.EDICT[which]
    if type(e) ~= "table" or type(e.options) ~= "table" then return false end
    for _, o in ipairs(e.options) do
        if o == option then return true end
    end
    return false
end

-- A READ, never a write: the panel and every rule ask it, for factions that never chose anything.
function F.edict(fkey, which)
    local e = F.EDICT[which]
    if not e then return nil end
    local b = F.edicts_on() and F.state.edicts and F.state.edicts[fkey]
    local x = b and b[which]
    if x and edict_known(which, x.o) then return x.o end
    return e.default
end

function F.edict_wait(fkey, which)
    local b = F.state.edicts and F.state.edicts[fkey]
    local x = b and b[which]
    if not (x and type(x.at) == "number") then return 0 end
    return math.max(0, x.at + F.EDICT.cooldown - cm:model():turn_number())
end

-- The race's own bundle for an option, or the base one; nil for an option with none (the defaults).
function F.edict_bundle(faction, option)
    local own = F.EDICT.race_bundles[option]
    return (own and own[F.race(faction)]) or F.EDICT.bundles[option]
end

-- RATIONS: provisions a turn per settlement level (F.NEED, 2, while the edict reads Normal).
function F.need(fkey) return F.EDICT.need[F.edict(fkey, "rations")] or F.NEED end

-- WAR ECONOMY: a processing batch whose output is a war material makes half as much again, rounded down.
function F.output_n(faction, d)
    if not d.output then return 0 end
    local n = d.output[2]
    if F.EDICT.war_outputs[d.output[1]] and F.edict(faction:name(), "workshops") == "war" then
        n = math.floor(n * F.EDICT.war_pct / 100)
    end
    return n
end

-- Every edict bundle there is, in a fixed order.
local function edict_family()
    local out = {}
    for _, which in ipairs(F.EDICT.order) do
        for _, o in ipairs(F.EDICT[which].options) do
            if F.EDICT.bundles[o] then out[#out + 1] = F.EDICT.bundles[o] end
            local races, keys = F.EDICT.race_bundles[o] or {}, {}
            for race in pairs(races) do keys[#keys + 1] = race end
            table.sort(keys)
            for _, race in ipairs(keys) do out[#out + 1] = races[race] end
        end
    end
    return out
end

-- The bundles of the options in force on, every other edict bundle off; all off with the switch off.
function F.edict_bundles(faction)
    local fkey, want = faction:name(), {}
    if F.edicts_on() and F.uses_stores(faction) then
        for _, which in ipairs(F.EDICT.order) do
            local b = F.edict_bundle(faction, F.edict(fkey, which))
            if b then want[b] = true end
        end
    end
    for _, b in ipairs(edict_family()) do
        if want[b] and not faction:has_effect_bundle(b) then cm:apply_effect_bundle(b, fkey, 0)
        elseif not want[b] and faction:has_effect_bundle(b) then cm:remove_effect_bundle(b, fkey) end
    end
end

-- `force` skips the wait (a store event's choice); nothing else does.
function F.edict_set(faction, which, option, force)
    if not edict_known(which, option) or not F.edicts_on() or not F.uses_stores(faction) then return false end
    -- NO MEALS, NO RATIONS: a faction that does not eat from the stores would get Plenty's growth for nothing
    if which == "rations" and not F.eats(faction) then return false end
    local fkey = faction:name()
    if F.edict(fkey, which) == option then return false end
    if not force and F.edict_wait(fkey, which) > 0 then return false end
    F.state.edicts = F.state.edicts or {}
    F.state.edicts[fkey] = F.state.edicts[fkey] or {}
    F.state.edicts[fkey][which] = { o = option, at = cm:model():turn_number() }
    F.edict_bundles(faction)
    -- CLOSED ROADS CHANGE EVERY VERDICT ON THIS FACTION'S LAND (terrain_routes.lua R.hostile): kept answers go
    if which == "roads" then F.invalidate_reach() end
    return true
end

-- Run from the load callback: a known edict, a known option and a turn number, or nothing.
function F.sanitize_edicts()
    local all = F.state.edicts
    if type(all) ~= "table" then F.state.edicts = nil return end
    local clean = {}
    for fkey, b in pairs(all) do
        if type(fkey) == "string" and type(b) == "table" then
            local keep = {}
            for which, x in pairs(b) do
                if type(x) == "table" and edict_known(which, x.o) and F.stock_number(x.at) then keep[which] = x end
            end
            if next(keep) then clean[fkey] = keep end
        end
    end
    F.state.edicts = next(clean) and clean or nil
end

-- COMPUTER EDICTS (spec 5.4): checked at their turn start, each change through F.edict_set, so the
-- cooldown binds them too. Rebels never count as a war or a neighbour.

-- Realm provisions held over the realm's meals at Normal: how many turns the food lasts. nil with no meals.
function F.food_cover(faction)
    local held, meals = 0, 0
    for _, s in ipairs(F.stocks(faction)) do
        local level = 0
        pcall(function() level = s.region:settlement():primary_slot():building():building_level() end)
        meals = meals + F.EDICT.need.normal * level
        held = held + F.use_total(s.held, "provisions")
    end
    if meals <= 0 then return nil end
    return held / meals
end

-- How many owners of a region next to ours are at war with us. A count, so the walk order cannot matter.
local function wars_next_door(faction)
    local fkey, seen, n = faction:name(), {}, 0
    local rl = faction:region_list()
    for i = 0, rl:num_items() - 1 do
        local adj = rl:item_at(i):adjacent_region_list()
        for j = 0, adj:num_items() - 1 do
            local o = adj:item_at(j):owning_faction()
            if not o:is_null_interface() and not o:is_rebel() and o:name() ~= fkey and not seen[o:name()] then
                seen[o:name()] = true
                if faction:at_war_with(o) then n = n + 1 end
            end
        end
    end
    return n
end

local function at_war(faction)
    local wars = faction:factions_at_war_with()
    if type(wars) == "boolean" then return false end
    for i = 0, wars:num_items() - 1 do
        if not wars:item_at(i):is_rebel() then return true end
    end
    return false
end

function F.edict_ai(faction)
    local a = F.EDICT.ai
    local cover = F.food_cover(faction)
    if cover then
        F.edict_set(faction, "rations", (cover < a.ration_low and "rationing") or (cover > a.ration_high and "plenty") or "normal")
    end
    local near = wars_next_door(faction)
    -- false, not a list, for the rebel faction (seen in game 2026-11-02)
    local partners = faction:factions_trading_with()
    local merchant = type(partners) ~= "boolean" and partners:num_items() >= a.merchant_partners and not at_war(faction)
    F.edict_set(faction, "workshops", (near > 0 and "war") or (merchant and "merchant") or "balanced")
    F.edict_set(faction, "roads", near >= a.closed_wars and "closed" or "tolled")
end

-- A player's edicts get their bundles (an older save catches up); a computer's run the rules.
function F.edict_turn(faction)
    if faction:is_human() then return F.edict_bundles(faction) end
    local r = F.rates()
    if r.edicts and r.ai and F.uses_stores(faction) then F.edict_ai(faction) end
end

-- ---- tolls and blockades (design 2026-11-01, Part C) ------------------------------------------
-- An agreement convoy or a partner cart pays each faction whose land its road crosses F.rates().toll% of
-- the cargo's value, at dispatch: all of them together at most F.TOLL.max%, each rounded down. Never the
-- two sides, their allies, vassals and masters, or rebels. Only a Tolled realm charges: Open charges nothing, and
-- Closed keeps foreign cargo out rather than charging it (spec 5.1), though a contract cart's road can still cross.
F.TOLL = DERPY_MR_FLOWS_TOLL

-- The land regions under a road's points, in road order, each once. Kept by the road's own table: a
-- road is a new table whenever it is worked out again.
F.road_known = setmetatable({}, { __mode = "k" })
function F.road_regions(path)
    if type(path) ~= "table" then return {} end
    local hit = F.road_known[path]
    if hit then return hit end
    local out, seen, model = {}, {}, cm:model()
    for _, p in ipairs(path) do
        local r = model:get_region_at_logical_position(p[1], p[2])
        if r and not r:is_null_interface() and not seen[r:name()] then
            seen[r:name()] = true
            out[#out + 1] = r:name()
        end
    end
    F.road_known[path] = out
    return out
end

local function friends(x, y) return x:is_ally_vassal_or_client_state_of(y) or y:is_ally_vassal_or_client_state_of(x) end

-- Who charges a and b's cargo on this road, in the order the road first reaches their land.
function F.toll_takers(a, b, path)
    local r = F.rates()
    if not r.tolls or (r.toll or 0) <= 0 then return {} end
    local out, seen = {}, { [a:name()] = true, [b:name()] = true }
    for _, rk in ipairs(F.road_regions(path)) do
        local region = cm:get_region(rk)
        local o = region and not region:is_null_interface() and region:owning_faction()
        if o and not o:is_null_interface() and not seen[o:name()] then
            seen[o:name()] = true
            if not o:is_rebel() and F.edict(o:name(), "roads") == "tolled" and not friends(o, a) and not friends(o, b) then
                out[#out + 1] = o:name()
            end
        end
    end
    return out
end

function F.toll_pct(n) return math.min(F.rates().toll * n, F.TOLL.max) end

-- Each taker's toll on a cargo worth `value` gold, and their sum. A taker due nothing is left out.
function F.tolls(value, takers)
    local due, n = {}, #takers
    if n == 0 then return due, 0 end
    local each = math.floor(value * F.toll_pct(n) / (n * 100))
    if each <= 0 then return due, 0 end
    for _, k in ipairs(takers) do due[k] = each end
    return due, each * n
end

-- The toll on one unit sold at price_c (hundredths of gold), in hundredths: the uphill rule adds it.
function F.toll_unit(price_c, n)
    if n <= 0 then return 0 end
    return math.floor(F.sell_price(price_c) * F.toll_pct(n) / 100)
end

-- All of it or none of it: a payer short of the sum pays nothing. In taker order, so every machine alike.
function F.pay_tolls(payer, due)
    local keys, sum = {}, 0
    for k, n in pairs(due) do keys[#keys + 1] = k; sum = sum + n end
    if sum <= 0 then return true end
    local f = cm:get_faction(payer)
    if not f or f:treasury() < sum then return false end
    table.sort(keys)
    for _, k in ipairs(keys) do
        cm:treasury_mod(payer, -due[k])
        cm:treasury_mod(k, due[k])
        F.book_toll(payer, k, "paid", due[k])
        F.book_toll(k, payer, "got", due[k])
    end
    return true
end

function F.book_toll(fkey, other, way, n) return F.book_gold("tolls", fkey, other, way, n) end
function F.tolls_last(fkey) return F.gold_last("tolls", fkey) end

-- A saved record's tolls: absent, or whole gold above 0 by faction key.
function F.tolls_sound(t)
    if t == nil then return true end
    if type(t) ~= "table" then return false end
    for k, n in pairs(t) do
        if type(k) ~= "string" or not (F.stock_number(n) and n > 0) then return false end
    end
    return true
end

-- A BLOCKADE (spec 6.2): an army at war with either side standing within F.SHIP.near hexes of any point of
-- their road stops that pair's trade, duty and contract carts for the turn; cargo already on the road goes on.
-- Never a reroute, and the reach answers never see armies. The blocker's faction key, or nil.
function F.blockade(a, b, path)
    if not F.rates().tolls or type(path) ~= "table" or #path == 0 then return nil end
    local near = F.SHIP.near
    local x0, y0, x1, y1 = path[1][1], path[1][2], path[1][1], path[1][2]
    for _, p in ipairs(path) do
        x0, y0, x1, y1 = math.min(x0, p[1]), math.min(y0, p[2]), math.max(x1, p[1]), math.max(y1, p[2])
    end
    for _, side in ipairs({ a, b }) do
        for _, e in ipairs(F.enemy_armies(side)) do
            -- the box widened by `near` first: most armies are nowhere near the road
            if e.x >= x0 - near and e.x <= x1 + near and e.y >= y0 - near and e.y <= y1 + near then
                for _, p in ipairs(path) do
                    local dx, dy = e.x - p[1], e.y - p[2]
                    if dx * dx + dy * dy <= near * near then return e.fkey end
                end
            end
        end
    end
    return nil
end

-- This turn's or last turn's blocker of a pair, as F.trade_pair recorded it at a real trade: what the panel, the
-- map and the duty read. Saved with those two turns (F.blockades_kept), so a reload shows and charges the same.
F.blockade_known = {}
local function pair_key(a_key, b_key)
    if b_key < a_key then a_key, b_key = b_key, a_key end
    return a_key .. ">" .. b_key
end
function F.blockaded(a_key, b_key)
    local hit = F.blockade_known[pair_key(a_key, b_key)]
    if hit and hit.turn >= cm:model():turn_number() - 1 then return hit.by end
    return nil
end
function F.record_blockade(a_key, b_key, by)
    F.blockade_known[pair_key(a_key, b_key)] = by and { by = by, turn = cm:model():turn_number() } or nil
end

function F.blockades_kept()
    local keep, turn = {}, cm:model():turn_number()
    for k, v in pairs(F.blockade_known) do
        if v.turn >= turn - 1 then keep[k] = { by = v.by, turn = v.turn } end
    end
    return next(keep) and keep or nil
end

-- On load: pair key -> { by = faction key, turn = number }, anything else dropped.
function F.sanitize_blockades()
    local clean = {}
    for k, v in pairs(type(F.state.blockades) == "table" and F.state.blockades or {}) do
        if type(k) == "string" and type(v) == "table" and type(v.by) == "string" and type(v.turn) == "number" then
            clean[k] = { by = v.by, turn = v.turn }
        end
    end
    F.blockade_known, F.state.blockades = clean, nil
end

-- ---- bandits on the roads (design 2026-11-01, Part D) ---------------------------------------
-- Cargo still on the road can meet trouble on the stretch it covered this turn, more often on dangerous land:
-- CA's caravan banditry where it reads above 0, else the wild-land rule. Three encounters, each a choice.
F.ROAD = DERPY_MR_FLOWS_ROAD
F.ROAD_BATTLES = true   -- false: every battle encounter is settled as its other choice (the live probe's fallback)

-- The region keys under the road's points from `from_xy` to `to_xy`, inclusive, each once; with no road, or a start
-- that is not on it, the region at `to_xy` alone.
-- ponytail: every point of the stretch is read each turn; cache by road if the 50 ms round budget is missed
function F.stretch(road, from_xy, to_xy)
    local model, out, seen = cm:model(), {}, {}
    local function add(x, y)
        local r = model:get_region_at_logical_position(x, y)
        if r and not r:is_null_interface() and not seen[r:name()] then
            seen[r:name()] = true
            out[#out + 1] = r:name()
        end
    end
    local i, j
    for k, p in ipairs(road or {}) do
        if not i and p[1] == from_xy[1] and p[2] == from_xy[2] then i = k end
        if not j and p[1] == to_xy[1] and p[2] == to_xy[2] then j = k end
    end
    if not (i and j) then
        add(to_xy[1], to_xy[2])
        return out
    end
    for k = i, j, (i <= j and 1 or -1) do add(road[k][1], road[k][2]) end
    return out
end

-- THE WILD-LAND RULE for one region: 100 for abandoned or rebel land, else its corruption or its unrest, whichever
-- is larger, 0 to 100.
function F.wild(region)
    local o = region:owning_faction()
    if region:is_abandoned() or o:is_null_interface() or o:is_rebel() then return 100 end
    local c = math.floor(cm:get_total_corruption_value_in_region(region) or 0)
    return math.max(0, math.min(100, math.max(c, -region:public_order())))
end

-- A stretch's threat: CA's caravan banditry over its regions, averaged and rounded down, as CA's caravans read it,
-- when that is above 0; else the wild land's average. 0 for no regions.
function F.threat(keys)
    if #keys == 0 then return 0 end
    local ok, v = pcall(function()
        return cm:model():world():caravans_system():total_banditry_for_regions_by_key(keys)
    end)
    if ok and type(v) == "number" and v > 0 then return math.min(100, math.floor(v / #keys)) end
    local sum = 0
    for _, k in ipairs(keys) do
        local r = cm:get_region(k)
        if r and not r:is_null_interface() then sum = sum + F.wild(r) end
    end
    return math.floor(sum / #keys)
end

-- AN ARMY ON PATROL (not a garrison) of the owner or the buyer within F.SHIP.near of the cargo keeps trouble away.
function F.patrol(owner, buyer, x, y)
    local r2 = F.SHIP.near * F.SHIP.near
    for _, f in ipairs({ owner, buyer }) do
        local mfl = f:military_force_list()
        for i = 0, mfl:num_items() - 1 do
            local mf = mfl:item_at(i)
            if not mf:is_armed_citizenry() and mf:has_general() then
                local ch = mf:general_character()
                local dx, dy = ch:logical_position_x() - x, ch:logical_position_y() - y
                if dx * dx + dy * dy <= r2 then return true end
            end
        end
    end
    return false
end

-- THE ROLL: trouble when cm:random_number(10000, 1) is at most threat x danger, half that with guards. Then one of
-- the encounters this cargo can meet, each as likely, that its faction has not met in F.ROAD.cooldown turns; that
-- turn is kept. The encounter's key, or nil.
function F.road_roll(fkey, threat, guarded, land)
    local danger = F.rates().road_danger or 0
    if threat <= 0 or danger <= 0 then return nil end
    if cm:random_number(10000, 1) > threat * danger * (guarded and 50 or 100) / 100 then return nil end
    local turn = cm:model():turn_number()
    F.state.road_cool = F.state.road_cool or {}
    local cool, open = F.state.road_cool[fkey] or {}, {}
    for _, e in ipairs(F.ROAD.encounters) do
        local fits = (e ~= "ambush" or threat >= F.ROAD.ambush_min) and (e ~= "washout" or land)
        if fits and turn - (cool[e] or -1000000) > F.ROAD.cooldown then open[#open + 1] = e end
    end
    if #open == 0 then return nil end
    local e = open[cm:random_number(#open, 1)]
    cool[e] = turn
    F.state.road_cool[fkey] = cool
    return e
end

-- A cargo's value at its owner's base prices: a convoy's whole basket, a shipment's units.
function F.cargo_value_base(rec)
    local v = 0
    for stem, n in pairs(rec.basket or { [rec.stem] = rec.n }) do
        v = v + F.gold(n, math.floor(F.price(F.GOOD[stem], rec.f) * F.PCT))
    end
    return v
end

-- Each good loses pct of its count, rounded down, so the smallest lots lose nothing to a half; a record left
-- empty leaves the road (F.drop refunds a contract's escrow). The units lost.
function F.cargo_lose(kind, rec, pct)
    local lost = 0
    if kind == "convoy" then
        for stem, n in pairs(rec.basket) do
            local cut = math.floor(n * pct / 100)
            lost = lost + cut
            -- a 0 never stays in a basket: a saved one fails F.convoy_sound
            rec.basket[stem] = n - cut > 0 and n - cut or nil
        end
        if next(rec.basket) == nil then F.convoy_drop(rec) end
    else
        local cut = math.floor(rec.n * pct / 100)
        lost, rec.n = cut, rec.n - cut
        if rec.n <= 0 then F.drop(rec) end
    end
    return lost
end

function F.cargo_wait(kind, rec)
    if kind == "convoy" then rec.due = rec.due + 1 else rec.due = F.ship_due(rec) + 1 end
end

-- THE OTHER CHOICE, which every encounter takes that no dilemma or battle settles: bandits take half, highwaymen
-- a fifth of the value in gold (never more than the treasury), a washed-out road a turn. A computer's convoy
-- bound for a player that loses goods tells that player.
function F.road_settle(faction, kind, rec, key)
    if key == "washout" then return F.cargo_wait(kind, rec) end
    if key == "highwaymen" then
        local pay = math.min(math.floor(F.cargo_value_base(rec) * F.ROAD.toll_pct / 100), math.max(0, faction:treasury()))
        if pay > 0 then cm:treasury_mod(faction:name(), -pay) end
        return
    end
    local lost = F.cargo_lose(kind, rec, F.ROAD.half_pct)
    local buyer = kind == "convoy" and F.live(rec.buyer)
    if lost > 0 and buyer and buyer:is_human() and not faction:is_human() then
        cm:show_message_event(buyer:name(), "event_feed_strings_text_derpy_mr_road_loss_title",
            "event_feed_strings_text_derpy_mr_road_loss_primary", "event_feed_strings_text_derpy_mr_road_loss_secondary",
            false, 1014)
    end
end

-- AT ITS OWNER'S TURN START, for cargo still on the road after its step: the stretch it covered, its threat
-- (kept on it, and a turn of danger for the owner's guards), then the roll. Nothing with the switch off, a
-- patrol near, or a safe road bought for the turn (Part E's caravan master).
function F.road_event(faction, kind, rec, from_xy)
    local r = F.rates()
    if not r.bandits or (r.road_danger or 0) <= 0 or not (rec.x and rec.y) then return end
    local fkey, turn, to_xy = faction:name(), cm:model():turn_number(), { rec.x, rec.y }
    local road = kind == "convoy" and F.unpack_road(rec.road) or rec.road
    local keys = F.stretch(road, from_xy or to_xy, to_xy)
    rec.threat = F.threat(keys)
    if rec.threat >= F.ROAD.ai_guard then
        F.state.road_seen = F.state.road_seen or {}
        F.state.road_seen[fkey] = turn
    end
    if F.patrol(faction, kind == "convoy" and F.live(rec.buyer) or nil, rec.x, rec.y) then return end
    if ((F.state.road_safe or {})[fkey] or -1) >= turn then return end
    -- all three encounters are land ones: cargo standing at sea meets none, whatever land its stretch crossed
    local here = cm:model():get_region_at_logical_position(rec.x, rec.y)
    if not here or here:is_null_interface() then return end
    local key = F.road_roll(fkey, rec.threat, rec.guarded == true, true)
    if not key then return end
    -- a player in single player is asked, as CA's caravans ask; everyone else takes the other choice
    if faction:is_human() and not cm:is_multiplayer() and (F.ROAD_BATTLES or not F.ROAD_FIGHT[key])
        and F.road_offer(faction, kind, rec, key, F.road_region(faction, keys)) then return end
    F.road_settle(faction, kind, rec, key)
end

-- GUARDS (spec 7.4): a player's switch; a computer's while any of its cargo crossed land of threat 30 or more
-- last turn. Off with the bandits.
function F.guards_on(fkey)
    if not F.rates().bandits then return false end
    if F.is_human(fkey) then return (F.state.guards or {})[fkey] == true end
    return ((F.state.road_seen or {})[fkey] or -1000000) >= cm:model():turn_number() - 1
end

-- "on" or "off", the state the panel wants: asking twice gives the same answer, as a toggle would not
function F.set_guards(faction, want)
    if want ~= "on" and want ~= "off" then return end
    F.state.guards = F.state.guards or {}
    F.state.guards[faction:name()] = want == "on" or nil
end

-- 5% of the cargo's value when it leaves, paid only when the payer can; then the cargo is guarded.
function F.guard_fee(payer, rec)
    if not F.guards_on(payer:name()) then return end
    local fee = math.floor(F.cargo_value_base(rec) * F.ROAD.guard_pct / 100)
    if fee > payer:treasury() then return end
    if fee > 0 then cm:treasury_mod(payer:name(), -fee) end
    rec.guarded = true
end

-- On load: the cooldowns, the guards and the turns of danger, each by faction in the shapes above, or nothing.
function F.sanitize_road()
    local known = {}
    for _, e in ipairs(F.ROAD.encounters) do known[e] = true end
    local function by_faction(t, keep)
        if type(t) ~= "table" then return nil end
        local clean = {}
        for k, v in pairs(t) do
            if type(k) == "string" then clean[k] = keep(v) end
        end
        return next(clean) and clean or nil
    end
    F.state.road_cool = by_faction(F.state.road_cool, function(b)
        if type(b) ~= "table" then return nil end
        local out = {}
        for e, t in pairs(b) do
            if known[e] and F.stock_number(t) then out[e] = t end
        end
        return next(out) and out or nil
    end)
    F.state.guards = by_faction(F.state.guards, function(v) return v == true or nil end)
    F.state.road_seen = by_faction(F.state.road_seen, function(v) return F.stock_number(v) and v or nil end)
    F.state.road_safe = by_faction(F.state.road_safe, function(v) return F.stock_number(v) and v or nil end)
end

-- ---- the Stores panel's actions (spending spec section 5, phase 7) -------------------------
-- Player only, and only through F.request: in multiplayer every action is a UITrigger.
F.GOOD = {}
for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do F.GOOD[g.stem] = g end
F.SEND_LOSS_PCT = 10
F.ORDER_COST, F.ORDER_TURNS, F.ORDER_COOLDOWN = DERPY_MR_FLOWS_ORDER[1], DERPY_MR_FLOWS_ORDER[2], DERPY_MR_FLOWS_ORDER[3]

F.STOCK_MAX = 1000000

-- Local paid batches and province services share orders, admission checks and accounting.
function F.economy_book(rkey, make, fkey)
    local all = F.state.economy
    if not all and make then all = {}; F.state.economy = all end
    local b = all and all[rkey]
    if b and fkey and b.f ~= fkey then return nil end
    if not b and make then
        b = { f = fkey, orders = {}, paid = {} }
        all[rkey] = b
    end
    return b
end

function F.economy_open(faction, region, d)
    if not F.uses_stores(faction) or not F.owned(faction, region:name()) then return false, "Not your stores" end
    local race, match = F.race(faction), false
    for _, r in ipairs(d.races) do if race == r then match = true end end
    if not match then return false, "Not available to this culture" end
    if d.kind == "services" then
        local cap = region:province():capital_region()
        if cap:is_null_interface() or cap:name() ~= region:name() then return false, "Province capital only" end
    else
        local slots = region:slot_list()
        for i = 0, slots:num_items() - 1 do
            local slot = slots:item_at(i)
            if slot:has_building() then
                local b = slot:building()
                if d.levels[b:name()] and b:percent_health() == 100 then return true end
            end
        end
        return false, "Needs an undamaged workshop"
    end
    return true
end

function F.economy_state(faction, region, key)
    local d = DERPY_MR_FLOWS_ECONOMY[key]
    if not d then return nil end
    local b = F.economy_book(region:name(), false, faction:name())
    local on = b and b.orders[key] == true or false
    local open, reason = F.economy_open(faction, region, d)
    if not F.rates()[d.kind] then open, reason = false, "Disabled for this campaign" end
    local ready, short = false, nil
    if open then ready, short = F.economy_admit(faction, region, d) end
    return { key = key, definition = d, on = on, open = open, reason = reason,
        ready = ready, short = short, made = d.output and F.output_n(faction, d) or nil,
        paid = b and b.paid[key] == cm:model():turn_number() or false }
end

function F.economy_rows(faction, region)
    local out, keys = {}, {}
    for key in pairs(DERPY_MR_FLOWS_ECONOMY) do keys[#keys + 1] = key end
    table.sort(keys)
    for _, key in ipairs(keys) do
        local d, match = DERPY_MR_FLOWS_ECONOMY[key], false
        for _, race in ipairs(d.races) do if F.race(faction) == race then match = true end end
        if match then out[#out + 1] = F.economy_state(faction, region, key) end
    end
    return out
end

function F.economy_toggle(faction, rkey, key)
    local region = F.owned(faction, rkey)
    if not region then return end
    local st = F.economy_state(faction, region, key)
    if not st or (not st.open and not st.on) then return end
    local b = F.economy_book(rkey, true, faction:name())
    if not b then return end
    b.orders[key] = not st.on or nil
    if st.definition.bundle and region:has_effect_bundle(st.definition.bundle) then
        cm:remove_effect_bundle_from_region(st.definition.bundle, rkey)
    end
    b.paid[key] = nil
end

function F.economy_named(faction, region)
    local named = {}
    local b = F.economy_book(region:name(), false, faction:name())
    if not b then return named end
    for key, on in pairs(b.orders) do
        local d = DERPY_MR_FLOWS_ECONOMY[key]
        if on and d and F.rates()[d.kind] and F.economy_open(faction, region, d) then
            for stem, n in pairs(d.cost) do named[stem] = (named[stem] or 0) + n end
        end
    end
    return named
end

-- Services spend their own basket reserve; processing spends only removable stock.
function F.economy_view(faction, region, d)
    local v = F.stock_view(faction, region)
    if d.kind == "services" then
        v.named = {}
        for stem in pairs(v.policy) do v.policy[stem] = {} end
        for _, use in ipairs({ "provisions", "building", "war", "mounts", "luxuries" }) do
            local base = v.recurring[use] or 0
            for stem, n in pairs(v.recurring.named or {}) do
                if F.GOOD[stem].use == use then base = base - n end
            end
            v.auto_keep[use] = math.max(0, base * F.FED_TURNS)
        end
    end
    return v
end

function F.economy_stems(d)
    local stems = {}
    for stem in pairs(d.cost) do stems[#stems + 1] = stem end
    table.sort(stems)
    return stems
end

function F.economy_admit(faction, region, d, batches)
    local v = F.economy_view(faction, region, d)
    for _, stem in ipairs(F.economy_stems(d)) do
        local n = d.cost[stem] * (batches or 1)
        if F.available_stock(v, stem) < n then return false, "Short of " .. stem end
        F.stock_adjust(v, stem, -n)
    end
    if d.output and F.free(region, d.output[1]) < F.output_n(faction, d) then return false, "Output store full" end
    return true
end

-- Verify each engine write. A failed batch restores the values read before admission.
function F.economy_pay(faction, region, d)
    local changes, before = {}, {}
    for stem, n in pairs(d.cost) do changes[#changes + 1] = { stem, -n, KIND.spend } end
    table.sort(changes, function(a, b) return a[1] < b[1] end)
    if d.output then changes[#changes + 1] = { d.output[1], F.output_n(faction, d), KIND.process } end
    for _, c in ipairs(changes) do before[c[1]] = F.held(region, c[1]) end
    local ok, err = pcall(function()
        for _, c in ipairs(changes) do
            F.pool_add(region, F.PREFIX .. c[1] .. "_" .. c[3], c[2])
            assert(F.held(region, c[1]) == before[c[1]] + c[2], "processing transaction did not match")
        end
        if d.bundle then
            cm:apply_effect_bundle_to_region(d.bundle, region:name(), F.BUNDLE_TURNS)
            assert(region:has_effect_bundle(d.bundle), "service benefit did not apply")
        end
    end)
    if not ok then
        for _, c in ipairs(changes) do
            local restored, why = pcall(function()
                local delta = before[c[1]] - F.held(region, c[1])
                if delta ~= 0 then
                    F.pool_add(region, F.PREFIX .. c[1] .. "_" .. c[3], delta)
                end
                assert(F.held(region, c[1]) == before[c[1]], "rollback did not match")
            end)
            if not restored then F.say("economy rollback failed: " .. tostring(why)) end
        end
        if d.bundle and region:has_effect_bundle(d.bundle) then cm:remove_effect_bundle_from_region(d.bundle, region:name()) end
        F.say("economy payment failed: " .. tostring(err))
        return false
    end
    for _, c in ipairs(changes) do
        F.log(faction:name(), c[1], c[3] .. (c[2] < 0 and "_out" or "_in"), math.abs(c[2]))
    end
    return true
end

function F.economy_clear(region)
    if F.state.economy then F.state.economy[region:name()] = nil end
    for _, d in pairs(DERPY_MR_FLOWS_ECONOMY) do
        if d.bundle and region:has_effect_bundle(d.bundle) then cm:remove_effect_bundle_from_region(d.bundle, region:name()) end
    end
end

-- A computer runs a batch only while the output is under its Target, else two batches or its use's auto target.
function F.economy_wanted(v, d)
    if not d.output then return true end
    local stem = d.output[1]
    local target = v.policy[stem].target
    if target == nil then target = math.max(d.output[2] * 2, v.auto_target[F.GOOD[stem].use] or 0) end
    return (v.held[stem] or 0) + (v.incoming[stem] or 0) < target
end

function F.economy_turn(faction)
    local keys = {}
    for key in pairs(DERPY_MR_FLOWS_ECONOMY) do keys[#keys + 1] = key end
    table.sort(keys)
    local regions = {}
    local rl = faction:region_list()
    for i = 0, rl:num_items() - 1 do regions[#regions + 1] = rl:item_at(i) end
    table.sort(regions, function(a, b) return a:name() < b:name() end)
    for _, region in ipairs(regions) do
        local b = F.economy_book(region:name(), false)
        if b and b.f ~= faction:name() then F.economy_clear(region); b = nil end
        local turn = cm:model():turn_number()
        if (b or not faction:is_human()) and (not b or b.done ~= turn) then
            -- Stamp before payment: a repeated callback must never charge again, including a failed batch.
            if b then b.done = turn end
            for _, kind in ipairs({ "processing", "services" }) do
                for _, key in ipairs(keys) do
                    local d = DERPY_MR_FLOWS_ECONOMY[key]
                    if d.kind == kind then
                        local open = F.uses_stores(faction) and (faction:is_human() or F.rates().ai)
                            and F.rates()[kind] and F.economy_open(faction, region, d)
                        local on = b and b.orders[key] == true
                        if not faction:is_human() and open then
                            on = F.economy_admit(faction, region, d, 2) and F.economy_wanted(F.stock_view(faction, region), d)
                            if on then
                                b = F.economy_book(region:name(), true, faction:name())
                                b.done, b.orders[key] = turn, true
                            end
                        end
                        if d.bundle and region:has_effect_bundle(d.bundle) then cm:remove_effect_bundle_from_region(d.bundle, region:name()) end
                        if open and on and F.economy_admit(faction, region, d) and F.economy_pay(faction, region, d) then
                            b.paid[key] = turn
                        end
                    end
                end
            end
        end
    end
end

-- WORKSHOP INPUTS (author, 2026-10-30): a computer's open workshop or service that cannot pay two batches
-- gets a cart from its fullest other store, filled to SHIP.ai_on batches, as army relief ships food. Every
-- short input must have a store that can close its gap, or fill a cart, or no cart goes: half a recipe
-- would sit there unused. A full cart is allowed short because a running order also reserves FED_TURNS
-- batches, which can need more than one cart. It runs after relief and the province supplies, whose
-- one-cart cap it shares.
function F.economy_supply(faction)
    local rates = F.rates()
    if faction:is_human() or not rates.ai or not F.uses_stores(faction) then return end
    if F.ship_count(faction:name()) >= F.ship_cap(faction) then return end
    local keys, regions, views = {}, {}, nil
    for key in pairs(DERPY_MR_FLOWS_ECONOMY) do keys[#keys + 1] = key end
    table.sort(keys)
    local rl = faction:region_list()
    for i = 0, rl:num_items() - 1 do regions[#regions + 1] = rl:item_at(i) end
    table.sort(regions, function(a, b) return a:name() < b:name() end)
    for _, region in ipairs(regions) do
        for _, kind in ipairs({ "processing", "services" }) do
            for _, key in ipairs(keys) do
                local d = DERPY_MR_FLOWS_ECONOMY[key]
                if d.kind == kind and rates[kind] and F.economy_open(faction, region, d) then
                    local v = F.economy_view(faction, region, d)
                    local plan = F.economy_wanted(v, d) and {} or nil
                    for _, stem in ipairs(plan and F.economy_stems(d) or {}) do
                        local have = F.room(v, stem) + (v.incoming[stem] or 0)
                        local short = d.cost[stem] * 2 - have
                        if short > 0 then
                            views = views or F.stock_views(faction)
                            local sources = {}
                            for _, s in ipairs(views) do
                                if s.region:name() ~= region:name() then sources[#sources + 1] = s end
                            end
                            local source, removable = F.fullest(sources, stem)
                            local free = (v.capacity[stem] or 0) - (v.held[stem] or 0) - (v.incoming[stem] or 0)
                            local fit = source and F.fit_delivery(math.min(removable, F.CART_MAX),
                                math.min(F.SHIP.ai_on * d.cost[stem] - have, free))
                            if not fit or fit.got < math.min(short, F.CART_MAX - F.lost(F.CART_MAX)) then plan = nil; break end
                            plan[#plan + 1] = { source = source, stem = stem, n = fit.n }
                        end
                    end
                    for _, p in ipairs(plan or {}) do
                        local ship = F.ship(faction, p.source.region, region, p.stem, p.n)
                        if ship then F.stock_adjust(p.source, p.stem, -ship.gross) end
                        if F.ship_count(faction:name()) >= F.ship_cap(faction) then return end
                    end
                end
            end
        end
    end
end

function F.stock_number(n)
    return type(n) == "number" and n == n and n >= 0 and n <= F.STOCK_MAX and n == math.floor(n)
end

function F.stock_policy(fkey, stem)
    local b = F.state.factions[fkey]
    local p = b and b.stock and b.stock[stem] or {}
    return { keep = p.keep, target = p.target }
end

function F.set_stock_policy(fkey, stem, field, value)
    if not F.is_human(fkey) or not F.GOOD[stem] or (field ~= "keep" and field ~= "target") then return false end
    local n = tonumber(value)
    if value ~= "auto" and not F.stock_number(n) then return false end
    local b = F.state.factions[fkey]
    if value == "auto" then
        local stock = b and b.stock
        local p = stock and stock[stem]
        if p then
            p[field] = nil
            if next(p) == nil then stock[stem] = nil end
            if next(stock) == nil then b.stock = nil end
        end
    else
        b = F.book(fkey)
        b.stock = b.stock or {}
        b.stock[stem] = b.stock[stem] or {}
        b.stock[stem][field] = n
    end
    return true
end

function F.sanitize_stock()
    for _, b in pairs(F.state.factions) do
        if type(b) == "table" and b.stock ~= nil then
            local clean = {}
            if type(b.stock) == "table" then
                for stem, p in pairs(b.stock) do
                    if F.GOOD[stem] and type(p) == "table" then
                        local v = {}
                        for _, field in ipairs({ "keep", "target" }) do
                            if F.stock_number(p[field]) then v[field] = p[field] end
                        end
                        if next(v) then clean[stem] = v end
                    end
                end
            end
            b.stock = next(clean) and clean or nil
        end
    end
end

function F.recurring_use(faction, region, provinces)
    local out, rates = {}, F.rates()
    if not F.uses_stores(faction) or not (rates.ai or faction:is_human()) then return out end
    if rates.upkeep and F.eats(faction) then
        local level = 0
        pcall(function() level = region:settlement():primary_slot():building():building_level() end)
        out.provisions = F.need(faction:name()) * level
    end
    local army_need, army_short = F.provision_need(faction, region)
    if army_need > 0 then
        out.army_need, out.army_short = army_need, army_short
        out.provisions = (out.provisions or 0) + army_need
    end
    if rates.supply then
        local pk = region:province_name()
        local p = (provinces or F.provinces(faction))[pk]
        local b = F.supply_book(faction:name(), pk, false)
        if p and p.capital and p.capital:name() == region:name() and b then
            for _, k in ipairs(DERPY_MR_FLOWS_SUPPLY_ORDER) do
                local use = DERPY_MR_FLOWS_SUPPLY[k].use
                if b[k] then out[use] = (out[use] or 0) + F.SHIP.per * #p.regions end
            end
        end
    end
    local named = F.economy_named(faction, region)
    if next(named) then out.named = named end
    for stem, n in pairs(named) do
        local use = F.GOOD[stem].use
        out[use] = (out[use] or 0) + n
    end
    return out
end

function F.stock_view(faction, region, provinces)
    local held, cap, capacity = F.stock(region)
    local v = { faction = faction, region = region, held = held, capacity = capacity,
        totals = {}, incoming = {}, incoming_use = {}, recurring = F.recurring_use(faction, region, provinces),
        auto_keep = {}, auto_target = {}, work_target = {}, policy = {}, due = {} }
    for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
        v.policy[g.stem] = F.stock_policy(faction:name(), g.stem)
        if not g.rare then v.totals[g.use] = (v.totals[g.use] or 0) + (held[g.stem] or 0) end
    end
    for _, ship in ipairs(F.ships_to(faction:name(), region:name())) do
        local g = F.GOOD[ship.stem]
        if g then
            v.incoming[g.stem] = (v.incoming[g.stem] or 0) + ship.n
            v.due[#v.due + 1] = { stem = g.stem, n = ship.n, due = F.ship_due(ship) }
            if not g.rare then v.incoming_use[g.use] = (v.incoming_use[g.use] or 0) + ship.n end
        end
    end
    local rates = F.rates()
    for _, use in ipairs({ "provisions", "building", "war", "mounts", "luxuries" }) do
        local has_pool = false
        for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
            if F.bulk(use)(g) and capacity[g.stem] then has_pool = true; break end
        end
        if not has_pool then v.recurring[use] = nil end
        local floor = 0
        if has_pool and (use == "war" or use == "luxuries") and rates.upkeep and F.uses_stores(faction)
            and (rates.ai or faction:is_human()) then floor = math.ceil(cap * F.STOCKED_PCT / 100) end
        local cost = v.recurring[use] or 0
        v.auto_keep[use] = math.max(F.FED_TURNS * cost, floor)
        v.auto_target[use] = math.max(F.SHIP.ai_on * cost, floor)
    end
    if F.uses_stores(faction) and (rates.ai or faction:is_human()) then
        for _, w in ipairs(DERPY_MR_FLOWS_WORKS) do
            if F.work_open(faction, w) then
                v.work_target[w.rare] = math.max(v.work_target[w.rare] or 0, w.rare_n)
            end
        end
    end
    return v
end

-- What `v` holds of `stem` past its Keep and reserves: negative while they are not covered.
function F.room(v, stem)
    local g, held = F.GOOD[stem], v.held[stem] or 0
    if not g then return 0 end
    local keep = (v.policy[stem] or {}).keep
    if keep ~= nil then return held - keep end
    if g.rare then return held end
    local named = (v.named or v.recurring.named or {})[stem] or 0
    return math.min(held - F.FED_TURNS * named, (v.totals[g.use] or 0) - (v.auto_keep[g.use] or 0))
end

function F.available_stock(v, stem) return math.max(0, F.room(v, stem)) end

function F.import_need(v, stem)
    local g = F.GOOD[stem]
    if not g then return 0 end
    local p = v.policy[stem] or {}
    local held, incoming = v.held[stem] or 0, v.incoming[stem] or 0
    local free = math.max(0, (v.capacity[stem] or 0) - held - incoming)
    local need
    if p.target ~= nil then need = math.min(p.target, v.capacity[stem] or 0) - held - incoming
    else
        if g.rare then need = (v.work_target[stem] or 0) - held - incoming
        else need = (v.auto_target[g.use] or 0) - (v.totals[g.use] or 0) - (v.incoming_use[g.use] or 0) end
        local named = (v.recurring.named or {})[stem] or 0
        need = math.max(need, F.SHIP.ai_on * named - held - incoming, (p.keep or 0) - held - incoming)
    end
    return math.max(0, math.min(free, need))
end

function F.stock_forecast(v, made)
    local out = {}
    for _, use in ipairs({ "provisions", "building", "war", "mounts", "luxuries" }) do
        local h, s = v.totals[use] or 0, 0
        for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
            if g.use == use then s = s + F.spoil_due(v, g.stem) end
        end
        local p = made and (made[use] or 0)
        local fc = { held = h, use_per_turn = v.recurring[use] or 0, spoil = s, production = p,
            incoming = v.incoming_use[use] or 0, due = v.due, mode = "none" }
        local d = fc.use_per_turn
        if p ~= nil then fc.net = p - d - s end
        -- spoiling counts against the net, never the cover: it stops at the safe share, so it
        -- cannot empty a store, and counted as a use it showed a countdown on every full granary
        if d > 0 then
            if p == nil then fc.mode, fc.cover = "stored", math.floor(h / d)
            elseif p >= d then fc.mode = "stable"
            else fc.mode, fc.cover = "declining", math.floor(h / (d - p)) end
        end
        out[use] = fc
    end
    return out
end

function F.fit_delivery(max_gross, max_arrival)
    local n = math.min(math.floor(max_gross), math.floor(max_arrival) + math.ceil(max_arrival / 9) + 2)
    while n > 0 and n - F.lost(n) > max_arrival do n = n - 1 end
    local got = n - F.lost(n)
    if got <= 0 then return nil end
    while n > 1 and n - 1 - F.lost(n - 1) == got do n = n - 1 end
    return { n = n, got = got }
end

function F.stocks(faction)
    local out = {}
    local rl = faction:region_list()
    for i = 0, rl:num_items() - 1 do
        local r = rl:item_at(i)
        if not r:is_null_interface() then
            local held, _cap, capacity = F.stock(r)
            out[#out + 1] = { region = r, held = held, capacity = capacity }
        end
    end
    return out
end

function F.owned(faction, rkey)
    local rl = faction:region_list()
    for i = 0, rl:num_items() - 1 do
        local r = rl:item_at(i)
        if not r:is_null_interface() and r:name() == rkey then return r end
    end
    return nil
end

function F.lost(n) return math.ceil(n * F.SEND_LOSS_PCT / 100) end

-- SEND HERE: the fullest OTHER store of the resource sends the most whose arrival, after the
-- loss on the road, still fits here beside what is already on the road to it. nil when nothing
-- would arrive; busy = true when the faction has its full number of shipments on the road.
function F.send_plan(faction, rkey, stem)
    if not F.GOOD[stem] then return nil end
    local to = F.owned(faction, rkey)
    if not to then return nil end
    local free = F.free(to, stem) - F.incoming(faction:name(), rkey, stem)
    if free <= 0 then return nil end
    local sources = {}
    for _, v in ipairs(F.stock_views(faction)) do
        if v.region:name() ~= rkey then sources[#sources + 1] = v end
    end
    local from, available = F.fullest(sources, stem)
    local fit = F.fit_delivery(math.min(available, F.CART_MAX), free)
    if not from or not fit then return nil end
    return { from = from.region, to = to, n = fit.n, got = fit.got, turns = F.route_turns(from.region, to),
             busy = F.ship_count(faction:name()) >= F.ship_cap(faction) or nil }
end

-- Leaves now; the saved dispatch duration governs arrival if nobody seizes it.
function F.send_here(faction, stem, rkey)
    local p = F.send_plan(faction, rkey, stem)
    if not p then return end
    F.ship(faction, p.from, p.to, stem, p.n)       -- F.ship refuses past the number on the road
end

-- ORDERS: a faction bundle bought with ORDER_COST of one use, drawn realm-wide; then a wait,
-- kept in the faction's book (and so in the save) as the turn it was bought.
function F.order_state(faction, key)
    local o = DERPY_MR_FLOWS_ORDERS[key]
    if not o then return nil end
    local have = 0
    for _, s in ipairs(F.stocks(faction)) do have = have + F.use_total(s.held, o.use) end
    local st = { have = have, cost = F.ORDER_COST, use = o.use }
    local b = F.state.factions[faction:name()]
    local last = b and b.orders and b.orders[key]
    local turn = cm:model():turn_number()
    if last and turn - last < F.ORDER_COOLDOWN then st.wait = last + F.ORDER_COOLDOWN - turn end
    -- RUNNING: its bundle lasts ORDER_TURNS from the turn it was bought; the panel makes it glow
    if last and turn - last < F.ORDER_TURNS then st.active = last + F.ORDER_TURNS - turn end
    st.ok = st.wait == nil and have >= F.ORDER_COST
    return st
end

function F.order(faction, key)
    local st = F.order_state(faction, key)
    if not (st and st.ok) then return end
    local o, fkey = DERPY_MR_FLOWS_ORDERS[key], faction:name()
    F.draw_realm(F.stocks(faction), F.bulk(o.use), F.ORDER_COST, KIND.spend, fkey)
    cm:apply_effect_bundle(o.bundle, fkey, F.ORDER_TURNS)
    local b = F.book(fkey)
    b.orders = b.orders or {}
    b.orders[key] = cm:model():turn_number()
end

-- THE WORKSHOP (spec 2026-10-07): a rare good plus a bulk of its use buys something that lasts.
-- Mirrors the orders: a state the panel greys with, a buy that checks both parts before taking.
F.WORK = {}
for _, w in ipairs(DERPY_MR_FLOWS_WORKS) do F.WORK[w.key] = w end
F.WORK_CFG = DERPY_MR_FLOWS_WORK
F.WORK_FACTOR = "derpy_mr_workshop"   -- gen_resource_overhaul.WORK_FACTOR: a conversion's gain-only factor

-- the race token of a subculture key: wh_main_sc_dwf_dwarfs -> dwf; "" for one with none
function F.race(faction)
    return string.match(faction:subculture(), "_sc_(%a+)_") or ""
end

-- A work or an event is open to its races ("all" for every one), less its not_races: a race gets its
-- own where the general one would do nothing for it (2026-11-01)
function F.work_open(faction, w)
    local race = F.race(faction)
    for _, r in ipairs(w.not_races or {}) do
        if r == race then return false end
    end
    for _, r in ipairs(w.races) do
        if r == "all" or r == race then return true end
    end
    return false
end

-- THE BULK IS ORDINARY GOODS ONLY: gromril is a war material, and must never pay as one
local bulk_pick = F.bulk
local function rare_pick(stem) return function(g) return g.stem == stem end end

function F.work_have(stocks, pick)
    local n = 0
    for _, s in ipairs(stocks) do
        for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
            if pick(g) then n = n + (s.held[g.stem] or 0) end
        end
    end
    return n
end

function F.works_book(fkey)
    local b = F.book(fkey)
    b.works = b.works or { items = {} }
    return b.works
end

-- Did this faction build this upgrade here? A read: it never adds an entry to the save.
function F.built_by(region_key, key, fkey)
    local ups = F.state.upgrades and F.state.upgrades[region_key]
    return ups ~= nil and ups[key] == fkey
end

-- region key -> {work key = buyer's faction key}, in the save. One buyer a settlement: a new owner
-- who builds it again becomes its buyer.
function F.upgrades_of(region_key)
    F.state.upgrades = F.state.upgrades or {}
    F.state.upgrades[region_key] = F.state.upgrades[region_key] or {}
    return F.state.upgrades[region_key]
end

-- How many of a unit the faction's pool holds, or nil where the engine will not say: the faction's
-- mercenary pool, read through unit_record():key() and unit_count() (measured 2026-10-07). Where it
-- cannot be read, F.work_state falls back on the Workshop's own count of what it put there, so a
-- purchase past the cap is refused rather than paid for and lost.
function F.pool_count(faction, unit)
    local ok, n = pcall(function()
        local units, total = faction:mercenary_pool():mercenary_pool_units(), 0
        for i = 0, units:num_items() - 1 do
            local u = units:item_at(i)
            if u:unit_record():key() == unit then total = total + u:unit_count() end
        end
        return total
    end)
    if ok and type(n) == "number" then return n end
    return nil
end

-- WHERE A UNIT GOES: its race's pool when the faction owns it (it lists in that pool's panel), else
-- straight into the faction's largest army with room - a minor faction has no renown pool.
function F.work_route(faction, w)
    local has = DERPY_MR_FLOWS_POOL_HAS[w.pool]
    if has and has[faction:name()] then return "pool" end
    return "army"
end

-- Is any part of a price more than the stores hold?
function F.work_short(st)
    if st.rare and st.rare.have < st.rare.cost then return true end
    if st.bulk and st.bulk.have < st.bulk.cost then return true end
    for _, g in ipairs(st.goods or {}) do
        if g.have < g.cost then return true end
    end
    return false
end

-- A computer keeps a reserve: the bulk, or every named good, held twice over
function F.work_reserve(st)
    for _, g in ipairs(st.goods or {}) do
        if g.have < g.cost + g.cost then return false end
    end
    return not st.bulk or st.bulk.have >= st.bulk.cost + st.bulk.cost
end

-- THE TARGET of an army or character work (spec section 4b, 4c): the character the player had
-- selected, read again here, because the click and its dispatch are apart (a UITrigger in
-- multiplayer). nil and why when it is gone, another faction's, or an army work's lord has none.
function F.work_target(faction, w, cqi)
    if type(cqi) ~= "number" or cqi <= 0 then return nil, "aim" end
    local c = cm:get_character_by_cqi(cqi)
    if not c or c:is_null_interface() then return nil, "aim" end
    if c:faction():name() ~= faction:name() then return nil, "not_yours" end
    -- a general_to_force_own trait does nothing on a hero (stage 2 final review)
    if w.lord and not c:character_type("general") then return nil, "not_lord" end
    if w.kind == "army" then
        if not c:has_military_force() then return nil, "no_army" end
        local mf = c:military_force()
        if mf:is_null_interface() or mf:is_armed_citizenry() then return nil, "no_army" end
    end
    return c
end

function F.work_state(faction, key, region_key, cqi)
    local w = F.WORK[key]
    if not w or not F.work_open(faction, w) then return nil end
    local stocks = F.stocks(faction)
    local st = {}
    if w.goods then
        -- A NAMED RECIPE (workshop expansion spec section 4): each good by its own stem
        st.goods = {}
        for _, p in ipairs(w.goods) do
            st.goods[#st.goods + 1] = { stem = p[1], have = F.work_have(stocks, rare_pick(p[1])), cost = p[2] }
        end
    else
        st.bulk = { have = F.work_have(stocks, bulk_pick(w.use)), cost = w.use_n }
    end
    if w.rare ~= "" then st.rare = { have = F.work_have(stocks, rare_pick(w.rare)), cost = w.rare_n } end
    -- READ, NEVER WRITE: a faction that has bought nothing keeps no book (a computer has no ledger)
    local book = F.state.factions[faction:name()]
    local wb, turn = book and book.works or { items = {} }, cm:model():turn_number()
    if w.kind == "item" and wb.items[key] then
        st.why = "done"
    elseif w.kind == "convert" and wb.convert and wb.convert[key] and turn - wb.convert[key] < w.wait then
        st.why, st.wait = "wait", wb.convert[key] + w.wait - turn
    elseif w.kind == "convert" then
        -- NOTHING PAID FOR NOTHING (stage 2 final review): the engine clamps a grant to the pool's
        -- maximum (Food stops at 100), and a faction without the pool gets nothing at all
        local p = faction:pooled_resource_manager():resource(w.pool)
        if not p or p:is_null_interface() then
            st.why = "no_pool"
        elseif p:value() + w.amount > p:maximum_value() then
            st.why = "full"
        end
    elseif w.kind == "lasting" and wb.lasting and wb.lasting[key] then
        st.why = "done"
    elseif w.kind == "army" or w.kind == "trait" then
        local c, why = F.work_target(faction, w, cqi)
        if not c then
            st.why = why
        elseif w.kind == "trait" then
            if c:has_trait(w.trait) then st.why = "done" end
        else
            -- A WAIT PER ARMY, PER WORK: another army can take it the same turn
            local at = wb.army and wb.army[key] and wb.army[key][c:military_force():command_queue_index()]
            if at and turn - at < w.wait then st.why, st.wait = "wait", at + w.wait - turn end
        end
    elseif w.kind == "research" and wb.research and turn - wb.research < F.WORK_CFG.research_wait then
        st.why, st.wait = "wait", wb.research + F.WORK_CFG.research_wait - turn
    elseif w.kind == "upgrade" then
        if not region_key then
            st.why = "where"
        else
            local r = cm:get_region(region_key)
            local owner = r and not r:is_null_interface() and r:owning_faction()
            if not owner or owner:is_null_interface() or owner:name() ~= faction:name() then
                st.why = "not_yours"
            elseif F.built_by(region_key, key, faction:name()) then
                st.why = "built"
            end
        end
    elseif w.kind == "unit" then
        st.route = F.work_route(faction, w)
        if st.route == "pool" then
            local n = F.pool_count(faction, w.grant) or (wb.units and wb.units[key]) or 0
            if n >= F.WORK_CFG.unit_max then st.why = "full" end
        elseif not F.work_army(faction) then
            st.why = "no_army"
        end
    end
    if not st.why and F.work_short(st) then st.why = "short" end
    st.ok = st.why == nil
    return st
end

function F.work_grant(faction, w, region_key, cqi)
    local fkey = faction:name()
    local wb, turn = F.works_book(fkey), cm:model():turn_number()
    if w.kind == "item" then
        cm:add_ancillary_to_faction(faction, w.grant, false)
        wb.items[w.key] = turn
    elseif w.kind == "unit" and F.work_route(faction, w) == "pool" then
        -- ONE FREE RECRUIT per purchase (spec section 3): the unit is recruited from the pool later,
        -- and that UnitTrained must not charge it again. The army route books none: measured
        -- 2026-10-11, grant_unit_to_character fires no UnitTrained, so a booking there was never
        -- spent and made the faction's next ordinary recruit of the unit free.
        wb.free = wb.free or {}
        wb.free[w.grant] = (wb.free[w.grant] or 0) + 1
        -- THE COUNT IS SET, NOT ADDED (measured 2026-10-07: count 1 on a pool of 1 left 1; a second
        -- purchase was paid for and lost). So: what the pool holds now, plus one.
        local now = F.pool_count(faction, w.grant) or (wb.units and wb.units[w.key]) or 0
        cm:add_unit_to_faction_mercenary_pool(faction, w.grant, w.pool, now + 1, 0,
                                              F.WORK_CFG.unit_max, 0, "", "", "", false, w.group)
        wb.units = wb.units or {}
        wb.units[w.key] = (wb.units[w.key] or 0) + 1
    elseif w.kind == "unit" then
        cm:grant_unit_to_character("character_cqi:" .. F.work_army(faction):general_character():command_queue_index(),
                                   w.grant)
    elseif w.kind == "upgrade" then
        cm:apply_effect_bundle_to_region(w.grant, region_key, 0)
        F.upgrades_of(region_key)[w.key] = fkey
    elseif w.kind == "convert" then
        cm:faction_add_pooled_resource(fkey, w.pool, F.WORK_FACTOR, w.amount)
        wb.convert = wb.convert or {}
        wb.convert[w.key] = turn
    elseif w.kind == "army" then
        local fc = cm:get_character_by_cqi(cqi):military_force():command_queue_index()
        if w.rank then
            cm:add_experience_to_units_commanded_by_character("character_cqi:" .. cqi, w.rank)
        else
            cm:apply_effect_bundle_to_force(w.bundle, fc, w.turns)
        end
        wb.army = wb.army or {}
        wb.army[w.key] = wb.army[w.key] or {}
        -- clearing a field during pairs is allowed in Lua 5.1; the new one goes in after
        for k, t in pairs(wb.army[w.key]) do
            if turn - t >= w.wait then wb.army[w.key][k] = nil end
        end
        wb.army[w.key][fc] = turn
    elseif w.kind == "trait" then
        cm:force_add_trait("character_cqi:" .. cqi, w.trait, true, 1)
    elseif w.kind == "lasting" then
        cm:apply_effect_bundle(w.bundle, fkey, 0)
        wb.lasting = wb.lasting or {}
        wb.lasting[w.key] = turn
    else
        cm:grant_research_points(fkey, F.WORK_CFG.research_points)
        wb.research = turn
    end
end

-- Pay both parts, the rare good first, from the fullest stores realm-wide.
function F.work_pay(faction, w, st)
    local fkey, stocks = faction:name(), F.stocks(faction)
    if st.rare then F.draw_realm(stocks, rare_pick(w.rare), w.rare_n, KIND.spend, fkey) end
    if st.goods then
        for _, g in ipairs(st.goods) do F.draw_realm(stocks, rare_pick(g.stem), g.cost, KIND.spend, fkey) end
    else
        F.draw_realm(stocks, bulk_pick(w.use), w.use_n, KIND.spend, fkey)
    end
end

-- A purchase: an upgrade only with a settlement, an army or character work only with a target
-- (a character's cqi), anything else with neither.
function F.work(faction, key, region_key, cqi)
    local w = F.WORK[key]
    if not w or (w.kind == "upgrade") ~= (region_key ~= nil) then return false end
    if (w.kind == "army" or w.kind == "trait") ~= (cqi ~= nil) then return false end
    local st = F.work_state(faction, key, region_key, cqi)
    if not (st and st.ok) then return false end
    F.work_pay(faction, w, st)
    F.work_grant(faction, w, region_key, cqi)
    -- A SOUND, on the buyer's own machine only: sound changes nothing in the model, so it is
    -- multiplayer-safe there (docs/SOUNDS.md)
    if faction:name() == cm:get_local_faction_name(true) then
        common.trigger_soundevent(DERPY_MR_FLOWS_WORK_SOUND[w.kind])
    end
    return true
end

-- ---- THE RECRUITMENT DRAW (workshop expansion spec 2026-10-08, section 3) ------------------
-- A recruit takes goods by its caste and gold worth, read off the unit itself, so any mod's unit
-- is priced alike. Charged after the recruit (a script cannot block it). What the stores lack is
-- paid in the race's CA currency, then in gold at gold_x times CA's trade value, never below 0.
F.RECRUIT = DERPY_MR_FLOWS_RECRUIT

-- CA's trade value of the cheapest good a pick takes: what one missing good costs in gold
function F.cheapest(pick)
    local w
    for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
        if pick(g) and (not w or g.value < w) then w = g.value end
    end
    return w or 0
end

function F.recruit_bill(faction, caste, value)
    local out, per = {}, F.rates().recruit_per or 0
    local parts = caste and DERPY_MR_FLOWS_CASTE[caste]
    if not parts or type(value) ~= "number" or value <= 0 or per <= 0 then return out end
    local draw = F.edict(faction:name(), "workshops") == "merchant" and F.EDICT.merchant_draw or 100
    local base = math.ceil(value / F.RECRUIT.per * per * draw / 100)
    -- the RUNNING total is rounded, not each part: a 7 split in halves is 4 and 3, never 4 and 4
    local share, done = 0, 0
    for _, p in ipairs(parts) do
        local pick = F.bulk(p[1])
        share = share + p[2]
        local upto = math.ceil(base * share)
        if upto > done then out[#out + 1] = { pick = pick, n = upto - done, worth = F.cheapest(pick) } end
        done = upto
    end
    local race = F.race(faction)
    local rare = (DERPY_MR_FLOWS_INFANTRY[caste] and DERPY_MR_FLOWS_RACE_RARE_INF[race]) or DERPY_MR_FLOWS_RACE_RARE[race]
    if rare and value >= F.RECRUIT.elite then
        local pick = rare_pick(rare)
        out[#out + 1] = { pick = pick, n = math.ceil(value / F.RECRUIT.elite_per), worth = F.cheapest(pick) }
    end
    return out
end

-- The shortfall, in bill order: the race's currency first (one per `per` goods, rounded up), then gold.
function F.recruit_short(faction, short)
    local fkey, paid, missing = faction:name(), {}, 0
    for _, s in ipairs(short) do missing = missing + s.n end
    local c, cover = DERPY_MR_FLOWS_CURRENCY[F.race(faction)], 0
    if c and missing > 0 then
        local pool = faction:pooled_resource_manager():resource(c.pool)
        local have = (not pool:is_null_interface()) and pool:value() or 0
        local take = math.min(math.ceil(missing / c.per), math.max(0, have))
        if take > 0 then
            cm:faction_add_pooled_resource(fkey, c.pool, F.RECRUIT.factor, -take)
            paid[c.word], cover = take, take * c.per
        end
    end
    local due = 0
    for _, s in ipairs(short) do
        local covered = math.min(cover, s.n)
        cover = cover - covered
        due = due + (s.n - covered) * s.worth * F.RECRUIT.gold_x
    end
    local gold = math.min(math.ceil(due), math.max(0, faction:treasury()))
    if gold > 0 then cm:treasury_mod(fkey, -gold) end
    return paid, gold, c and c.line or nil
end

-- A UNIT PAID FOR IN THE WORKSHOP is not charged again when it is recruited (spec section 3):
-- the next UnitTrained of that key for that faction is skipped, one per purchase. A read first:
-- F.works_book would add a book to the save for every computer faction that recruits.
function F.recruit_skip(fkey, unit_key)
    local b = F.state.factions[fkey]
    local free = b and b.works and b.works.free
    if not (free and (free[unit_key] or 0) > 0) then return false end
    free[unit_key] = free[unit_key] - 1
    if free[unit_key] == 0 then free[unit_key] = nil end
    return true
end

function F.on_unit_trained(context)
    local unit = context:unit()
    local faction = unit:faction()
    if not faction or faction:is_null_interface() then return end
    if F.recruit_paused(faction:name()) then return end
    local r = F.rates()
    if not r.recruit or not F.uses_stores(faction) or not (r.ai or faction:is_human()) then return end
    local fkey = faction:name()
    if F.recruit_skip(fkey, unit:unit_key()) then return end
    local bill = F.recruit_bill(faction, unit:unit_caste(), unit:get_unit_custom_battle_cost())
    if #bill == 0 then return end
    local stocks, got_n, short = F.stocks(faction), 0, {}
    for _, b in ipairs(bill) do
        local got = F.draw_realm(stocks, b.pick, b.n, KIND.spend, fkey)
        got_n = got_n + got
        if got < b.n then short[#short + 1] = { n = b.n - got, worth = b.worth } end
    end
    local paid, gold, line = F.recruit_short(faction, short)
    if F.is_human(fkey) then F.book_recruit(fkey, got_n, paid, gold, line) end
end

-- THE LEDGER: this turn's and last turn's, for the Spending tab. Clearing a field during pairs
-- is allowed in Lua 5.1 (adding one is not).
function F.book_recruit(fkey, goods, paid, gold, line)
    local b, turn = F.book(fkey), cm:model():turn_number()
    b.recruit = b.recruit or {}
    for t in pairs(b.recruit) do if t < turn - 1 then b.recruit[t] = nil end end
    local e = b.recruit[turn] or { goods = 0, paid = {}, gold = 0 }
    b.recruit[turn] = e
    e.goods, e.gold, e.line = e.goods + goods, e.gold + gold, e.line or line
    for w, n in pairs(paid) do e.paid[w] = (e.paid[w] or 0) + n end
end

function F.recruit_last(fkey)
    local b = F.state.factions[fkey]
    return b and b.recruit and b.recruit[cm:model():turn_number() - 1] or nil
end

-- The largest field army that still has room for a unit: never a garrison or a convoy.
F.ARMY_MAX = 20
function F.work_army(faction)
    local best, bn, bc = nil, nil, nil
    local list = faction:military_force_list()
    for i = 0, list:num_items() - 1 do
        local mf = list:item_at(i)
        if not mf:is_armed_citizenry() and mf:has_general() and mf:force_type():key() ~= "CONVOY" then
            local n, c = mf:unit_list():num_items(), mf:general_character():command_queue_index()
            if n < F.ARMY_MAX and (bn == nil or n > bn or (n == bn and c < bc)) then best, bn, bc = mf, n, c end
        end
    end
    return best
end

-- Where a computer builds an upgrade: its capital, else its settlement holding the most of the
-- bulk's use; never where it is built already. A tie goes by region key.
function F.work_ai_where(faction, w)
    local home = faction:has_home_region() and faction:home_region()
    local fkey = faction:name()
    if home and not home:is_null_interface() and not F.built_by(home:name(), w.key, fkey) then return home:name() end
    local best, bn = nil, -1
    for _, s in ipairs(F.stocks(faction)) do
        local rk = s.region:name()
        local n = F.work_have({ s }, bulk_pick(w.use))
        if not F.built_by(rk, w.key, fkey) and (n > bn or (n == bn and rk < best)) then best, bn = rk, n end
    end
    return best
end

-- army and character works are the player's alone (spec section 4): no order, never bought
F.WORK_AI_ORDER = { unit = 1, item = 2, upgrade = 3, lasting = 4, convert = 5, research = 6 }

-- A COMPUTER FACTION BUYS: one thing on a roll, the first it can afford with a reserve left over
-- (its stores of the bulk's use still hold the bulk's cost again), units straight into an army.
function F.work_ai(faction)
    if faction:is_human() or not F.rates().ai or not F.uses_stores(faction) then return end
    if cm:random_number(100, 1) > F.WORK_CFG.ai_pct then return end
    local rows = {}
    for _, w in ipairs(DERPY_MR_FLOWS_WORKS) do
        if F.WORK_AI_ORDER[w.kind] and F.work_open(faction, w) then rows[#rows + 1] = w end
    end
    table.sort(rows, function(a, b)
        local oa, ob = F.WORK_AI_ORDER[a.kind], F.WORK_AI_ORDER[b.kind]
        if oa ~= ob then return oa < ob end
        return a.key < b.key
    end)
    for _, w in ipairs(rows) do
        local region_key, army
        if w.kind == "upgrade" then
            region_key = F.work_ai_where(faction, w)
        elseif w.kind == "unit" then
            army = F.work_army(faction)
        end
        local st = (w.kind ~= "upgrade" or region_key) and (w.kind ~= "unit" or army)
                   and F.work_state(faction, w.key, region_key)
        if st and st.ok and F.work_reserve(st) then
            F.work_pay(faction, w, st)
            if w.kind == "unit" then
                -- no free recruit booked: the grant fires no UnitTrained (F.work_grant)
                cm:grant_unit_to_character("character_cqi:" .. army:general_character():command_queue_index(), w.grant)
            else
                F.work_grant(faction, w, region_key)
            end
            return
        end
    end
end

-- A SETTLEMENT CHANGES HANDS: an upgrade works for the faction that bought it and for nobody
-- else, and comes back when its buyer takes the settlement back.
function F.on_region_change(region)
    local rk = region:name()
    F.economy_clear(region)
    local ups = F.state.upgrades and F.state.upgrades[rk]
    if not ups then return end
    local owner = region:owning_faction()
    local who = (owner and not owner:is_null_interface()) and owner:name() or ""
    for key, buyer in pairs(ups) do
        local w = F.WORK[key]
        if w then
            if buyer == who then
                cm:apply_effect_bundle_to_region(w.grant, rk, 0)
            elseif region:has_effect_bundle(w.grant) then
                cm:remove_effect_bundle_from_region(w.grant, rk)
            end
        end
    end
end

-- SELL: the Zharr Exchange's price a unit when it is loaded and answers, the fixed rate of the
-- resource's use otherwise. The surplus is what the realm holds above half its space for it.
-- A UNIT's price, for the seller `fkey`. EX.sell_price is the price of a LOT (EX.lot units; the
-- Exchange's own note on EX.holdings_value) and was paid per unit, 10x. And it reads the houses'
-- stance toward EX.who(), the LOCAL player unless bound: EX.with_player binds it to the seller,
-- so every machine prices one sale alike (a UITrigger action runs on all of them).
function F.price(g, fkey)
    if type(EX) == "table" and type(EX.sell_price) == "function" and type(EX.lot) == "function"
       and type(EX.with_player) == "function" then
        local p
        local ok = EX.with_player(fkey, function() p = EX.sell_price(g.res) / EX.lot(g.res) end)
        if ok and type(p) == "number" and p > 0 then return p end
    end
    return DERPY_MR_FLOWS_SELL_RATE[g.use] or 0
end

-- The game's compiler miscompiles a literal left of an operator, so 100 is F.PCT and literals go right.
F.PCT, F.PRICE_SWING, F.SPREAD = 100, 75, 10

local function clamp_pct(n) return math.max(-F.PCT, math.min(F.PCT, n)) end

-- Returns the multiplier, then the cover in turns (consumed branch) or the fullness percent.
local function price_state(v, stem)
    local g, held, cap = F.GOOD[stem], v.held[stem] or 0, v.capacity[stem]
    if not g or not cap or cap <= 0 then return nil end
    local use = v.recurring[g.use] or 0
    local imbalance, turns, fullness
    if F.bulk(g.use)(g) and use > 0 then
        local cover = math.floor((v.totals[g.use] or 0) / use)
        turns = cover
        imbalance = clamp_pct(math.floor((F.SHIP.ai_on - cover) * F.PCT / F.SHIP.ai_on))
    else
        fullness = math.floor(held * F.PCT / cap)
        imbalance = clamp_pct(F.PCT - math.floor(held * 200 / cap))
    end
    return math.floor(F.PRICE_SWING * imbalance / F.PCT) + F.PCT, turns, fullness
end

function F.price_mult(v, stem) return (price_state(v, stem)) end

local function base_price(stem, fkey) return math.floor(F.price(F.GOOD[stem], fkey) * F.PCT) end

function F.local_price(v, stem, fkey)
    local mult = F.price_mult(v, stem)
    if not mult then return nil end
    return F.gold(base_price(stem, fkey), mult)
end

function F.buy_price(c) return math.floor(c * (F.SPREAD + F.PCT) / F.PCT) end
function F.sell_price(c) return math.floor(c * F.PCT / (F.SPREAD + F.PCT)) end
function F.gold(n, c) return math.floor(n * c / F.PCT) end

function F.quote(faction, region, stem)
    local v = F.stock_view(faction, region)
    local mult, cover, fullness = price_state(v, stem)
    if not mult then return nil end
    local base = base_price(stem, faction:name())
    local price = F.gold(base, mult)
    return { price = price, buy = F.buy_price(price), sell = F.sell_price(price), mult = mult,
             base = base, cover = cover, fullness = fullness }
end

-- A partner cart never costs less than its goods sell for where they land: otherwise buying from a full partner and selling the surplus at your own store makes gold.
function F.cart_price(seller, from, buyer, to, stem)
    local ps = F.local_price(F.stock_view(seller, from), stem, seller:name())
    if not ps then return nil end
    local pd = F.local_price(F.stock_view(buyer, to), stem, buyer:name())
    return math.max(F.buy_price(ps), pd and F.sell_price(pd) or 0)
end

-- Lots go most available first, then by region key; price is the lot-weighted average unit price (hundredths), gold the sum of floored lot golds.
function F.sale(faction, stem)
    if not F.GOOD[stem] then return nil end
    local fkey, views, avail, total, space = faction:name(), F.stock_views(faction), {}, 0, 0
    for _, v in ipairs(views) do
        total = total + (v.held[stem] or 0)
        space = space + (v.capacity[stem] or 0)
        avail[v] = F.available_stock(v, stem)
    end
    table.sort(views, function(a, b)
        if avail[a] ~= avail[b] then return avail[a] > avail[b] end
        return a.region:name() < b.region:name()
    end)
    local left, n, gold, weighted, lots = total - math.floor(space / 2), 0, 0, 0, {}
    for _, v in ipairs(views) do
        local k = math.min(left, avail[v])
        if k > 0 and F.price_mult(v, stem) then
            local price = F.sell_price(F.local_price(v, stem, fkey))
            local pay = F.gold(k, price)
            if pay > 0 then
                lots[#lots + 1] = { region = v.region:name(), from = v.region, n = k, price = price }
                n, left = n + k, left - k
                gold, weighted = gold + pay, weighted + k * price
            end
        end
    end
    if gold <= 0 then return nil end
    return { n = n, price = math.floor(weighted / n), gold = gold, lots = lots }
end

function F.sell(faction, stem)
    local s = F.sale(faction, stem)
    if not s then return end
    local fkey = faction:name()
    for _, lot in ipairs(s.lots) do F.move(lot.from, nil, stem, lot.n, KIND.sell, fkey, nil) end
    cm:treasury_mod(fkey, s.gold)
end

-- ---- carried army provisions ------------------------------------------------------------
F.PROVISION_BUNDLES = { "derpy_mr_army_hungry", "derpy_mr_army_starved" }

function F.provision_total(b)
    local n = 0
    for _, v in pairs(b and b.goods or {}) do n = n + v end
    return n
end

-- CARAVANS AND CONVOYS CARRY NO RATIONS (Workshop report, 2026-11-06): Cathay's caravans and the Chaos Dwarfs'
-- convoys spend their trips on foreign roads, where nothing can refill, so every trip ended hungry.
F.NO_RATIONS = { CARAVAN = true, CONVOY = true }

function F.provision_force(faction, force)
    if not force or force:is_null_interface() or not F.eats(faction)
        or not force:has_general() or force:is_armed_citizenry()
        or F.NO_RATIONS[force:force_type():key()]
        or force:faction():name() ~= faction:name() then return false end
    local fight = F.state.fight
    return not (fight and fight.escort == force:command_queue_index())
end

function F.provision_source(faction, force)
    local ch = force:general_character()
    if ch:is_at_sea() then return nil, "It cannot refill at sea." end
    if not ch:has_region() then return nil, "There is no settlement here to refill from." end
    local r = ch:region()
    if r:is_null_interface() or r:is_abandoned() or r:owning_faction():name() ~= faction:name() then
        return nil, "This settlement is not yours."
    end
    if r:garrison_residence():is_under_siege() then return nil, "This settlement is under siege." end
    return r, "It refills from this settlement."
end

function F.provision_need(faction, region)
    local rates, need, short = F.rates(), 0, 0
    if not rates.army_provisions or not F.uses_stores(faction)
        or not (rates.ai or faction:is_human()) then return need, short end
    local fs = faction:military_force_list()
    for i = 0, fs:num_items() - 1 do
        local force = fs:item_at(i)
        if F.provision_force(faction, force) then
            local b = F.state.armies and F.state.armies[tostring(force:command_queue_index())]
            if b and b.f ~= faction:name() then b = nil end
            local source = F.provision_source(faction, force)
            if source and source:name() == region:name() and (not b or b.auto ~= false) then
                need = need + math.max(1, math.ceil(force:unit_list():num_items() / 4))
                short = math.max(short, b and b.short or 0)
            end
        end
    end
    return need, short
end

function F.provision_stock(faction, region)
    local v = F.stock_view(faction, region, F.provinces(faction))
    -- Loading may spend the army reserve, but retains settlement/named demand and explicit Keep.
    v.auto_keep.provisions = math.max(0, (v.auto_keep.provisions or 0)
        - F.FED_TURNS * (v.recurring.army_need or 0))
    return v
end

F.FIELD_RATION_PRICE = 10

function F.provision_quote(faction, row, b)
    if not row.mobile or (b and b.field_turn == cm:model():turn_number()) then return 0 end
    return math.max(0, math.min(row.need * 2 - F.provision_total(b),
        math.floor(faction:treasury() / F.FIELD_RATION_PRICE)))
end

function F.provision_rows(faction)
    local rows = {}
    local rates = F.rates()
    if not rates.army_provisions or not F.uses_stores(faction) or not (rates.ai or faction:is_human()) then return rows end
    local fs = faction:military_force_list()
    for i = 0, fs:num_items() - 1 do
        local force = fs:item_at(i)
        if F.provision_force(faction, force) then
            local id = tostring(force:command_queue_index())
            local b = F.state.armies and F.state.armies[id]
            if b and b.f ~= faction:name() then b = nil end
            local need = math.max(1, math.ceil(force:unit_list():num_items() / 4))
            local source, reason = F.provision_source(faction, force)
            if source then
                local view, available = F.provision_stock(faction, source), 0
                for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
                    if F.bulk("provisions")(g) then
                        local n = F.available_stock(view, g.stem)
                        available = available + n
                        F.stock_adjust(view, g.stem, -n)
                    end
                end
                reason = available > 0 and ("This settlement has " .. tostring(available) .. " provisions to spare.")
                    or "This settlement has no provisions to spare."
            end
            local row = { id = id, force = force, need = need, cap = 10 * need,
                held = F.provision_total(b), short = b and b.short or 0, auto = not b or b.auto ~= false,
                source = source, reason = reason,
                mobile = not source and (force:general_character():is_at_sea() or faction:region_list():num_items() == 0) }
            row.buy = F.provision_quote(faction, row, b)
            row.price = row.buy * F.FIELD_RATION_PRICE
            if row.mobile then
                row.reason = row.buy > 0 and ("You can buy " .. row.buy .. " rations for " .. row.price .. " gold.")
                    or "The army cannot buy more rations this turn."
            end
            rows[#rows + 1] = row
        end
    end
    table.sort(rows, function(a, b) return tonumber(a.id) < tonumber(b.id) end)
    return rows
end

function F.provision_clear(id)
    if F.state.armies then F.state.armies[id] = nil end
    local force = cm:get_military_force_by_cqi(tonumber(id))
    if force and not force:is_null_interface() then
        for _, key in ipairs(F.PROVISION_BUNDLES) do cm:remove_effect_bundle_from_force(key, tonumber(id)) end
    end
end

function F.provision_buy(faction, row, b)
    local n = F.provision_quote(faction, row, b)
    if n <= 0 then return end
    local cost, before = n * F.FIELD_RATION_PRICE, faction:treasury()
    cm:treasury_mod(faction:name(), -cost)
    local paid = before - faction:treasury()
    if paid ~= cost then
        if paid > 0 then cm:treasury_mod(faction:name(), paid) end
        return
    end
    b.field_turn = cm:model():turn_number()
    local stem = row.force:general_character():is_at_sea() and "salted_fish" or "salted_meat"
    b.goods[stem] = (b.goods[stem] or 0) + n
    F.log(faction:name(), stem, KIND.move .. "_in", n)
end

-- full: the player's Load, which fills the army to what it can carry (Workshop report, 2026-11-05: Load stopped at
-- 5 turns while the panel showed room for 10). Auto keeps 5 turns after this turn's meal.
function F.provision_refill(faction, row, b, unload, full)
    local region = row.source
    if not region then
        if not unload then F.provision_buy(faction, row, b) end
        return
    end
    local view = F.provision_stock(faction, region)
    local target = full and row.cap or 5 * row.need
    if b.done ~= cm:model():turn_number() then target = target + row.need end
    local left = math.max(0, math.min(row.cap, target) - F.provision_total(b))
    for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
        if F.bulk("provisions")(g) then
            local n = unload and math.min(b.goods[g.stem] or 0, F.free(region, g.stem))
                or math.min(left, F.available_stock(view, g.stem))
            if n > 0 then
                local before = F.held(region, g.stem)
                F.pool_add(region, F.PREFIX .. g.stem .. "_" .. KIND.move, unload and n or -n)
                local actual = F.held(region, g.stem) - before
                -- Cargo changes only by the native pool's confirmed debit/credit.
                if unload then actual = math.max(0, math.min(n, actual))
                else actual = math.max(0, math.min(n, -actual)) end
                b.goods[g.stem] = (b.goods[g.stem] or 0) + (unload and -actual or actual)
                F.stock_adjust(view, g.stem, unload and actual or -actual)
                F.log(faction:name(), g.stem, KIND.move .. (unload and "_in" or "_out"), actual)
                left = left - actual
            end
        end
    end
end

function F.provision_record(faction, row)
    F.state.armies = F.state.armies or {}
    F.state.army_issued = F.state.army_issued or {}
    local b = F.state.armies[row.id]
    if not b then
        b = { f = faction:name(), goods = {}, auto = true, short = 0 }
        if not F.state.army_issued[row.id] then
            local race = F.race(faction)
            local biscuit = race == "emp" or race == "brt" or race == "dwf" or race == "hef"
                or race == "def" or race == "ksl" or race == "cth"
            b.goods[biscuit and "hardtack" or "salted_meat"] = row.need * 5
            b.done = cm:model():turn_number()
        end
        F.state.armies[row.id] = b
    end
    F.state.army_issued[row.id] = true
    return b
end

function F.provision_seed_force(force)
    if not force or force:is_null_interface() then return end
    local faction, rates = force:faction(), F.rates()
    if not rates.army_provisions or not (rates.ai or faction:is_human())
        or not F.provision_force(faction, force) then return end
    F.provision_record(faction, {id=tostring(force:command_queue_index()),
        need=math.max(1,math.ceil(force:unit_list():num_items()/4))})
end

function F.provision_seed_all()
    local factions = cm:model():world():faction_list()
    for i=0,factions:num_items()-1 do
        local forces = factions:item_at(i):military_force_list()
        for j=0,forces:num_items()-1 do F.provision_seed_force(forces:item_at(j)) end
    end
end

function F.provision_action(faction, id, op)
    if not F.rates().army_provisions or (op ~= "auto" and op ~= "load" and op ~= "unload") then return end
    local b = F.state.armies and F.state.armies[id]
    if b and b.f ~= faction:name() then return end
    for _, row in ipairs(F.provision_rows(faction)) do
        if row.id == id then
            if not b then b = F.provision_record(faction, row) end
            if op == "auto" then b.auto = not b.auto
            else
                F.provision_refill(faction, row, b, op == "unload", op == "load")
                if op == "unload" then b.auto = false end
            end
            return
        end
    end
end

function F.provisions_turn(faction)
    local fkey, turn = faction:name(), cm:model():turn_number()
    local rates = F.rates()
    local enabled = rates.army_provisions and F.uses_stores(faction) and (rates.ai or faction:is_human())
    local rows, live = enabled and F.provision_rows(faction) or {}, {}
    for _, row in ipairs(rows) do live[row.id] = true end
    local retire = {}
    for id, b in pairs(F.state.armies or {}) do
        local force = cm:get_military_force_by_cqi(tonumber(id))
        if not force or force:is_null_interface() or force:faction():name() ~= b.f
            or (b.f == fkey and not live[id]) then retire[#retire + 1] = id end
    end
    table.sort(retire)
    for _, id in ipairs(retire) do F.provision_clear(id) end
    if not enabled then return end
    F.state.armies = F.state.armies or {}
    local warn = false
    for _, row in ipairs(rows) do
        local b = F.state.armies[row.id]
        if not b then b = F.provision_record(faction, row) end
        if b.done ~= turn then
            if b.auto and (row.source or not faction:is_human()) then F.provision_refill(faction, row, b, false) end
            local left = row.need
            for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
                local n = math.min(left, b.goods[g.stem] or 0)
                if n > 0 then
                    b.goods[g.stem] = b.goods[g.stem] - n
                    left = left - n
                    F.log(fkey, g.stem, KIND.eat .. "_out", n)
                end
            end
            local previous = b.short
            b.short = left == 0 and 0 or b.short + 1
            b.done = turn
            warn = warn or (b.short > previous and b.short <= 3)
            for _, key in ipairs(F.PROVISION_BUNDLES) do cm:remove_effect_bundle_from_force(key, tonumber(row.id)) end
            local key = b.short >= 3 and F.PROVISION_BUNDLES[2] or b.short == 2 and F.PROVISION_BUNDLES[1]
            if key then cm:apply_effect_bundle_to_force(key, tonumber(row.id), 0) end
        end
    end
    if warn and faction:is_human() then
        cm:show_message_event(fkey, "event_feed_strings_text_derpy_mr_army_food_title",
            "event_feed_strings_text_derpy_mr_army_food_primary", "event_feed_strings_text_derpy_mr_army_food_secondary", false, 1014)
    end
end

function F.provision_supply(faction)
    local rates = F.rates()
    if faction:is_human() or not rates.ai or not rates.army_provisions or not F.uses_stores(faction) then return end
    if F.ship_count(faction:name()) >= F.ship_cap(faction) then return end
    local views = F.stock_views(faction)
    table.sort(views, function(a, b)
        local sa, sb = a.recurring.army_short or 0, b.recurring.army_short or 0
        if sa ~= sb then return sa > sb end
        return a.region:name() < b.region:name()
    end)
    for _, dest in ipairs(views) do
        if (dest.recurring.army_need or 0) > 0 and not F.route_covers(faction, dest.region:name(), "provisions") then
            local sources = {}
            for _, v in ipairs(views) do if v ~= dest then sources[#sources + 1] = v end end
            for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
                if F.bulk("provisions")(g) then
                    local source, removable = F.fullest(sources, g.stem)
                    local fit = F.fit_delivery(removable, F.import_need(dest, g.stem))
                    if source and fit then
                        local ship = F.ship(faction, source.region, dest.region, g.stem, fit.n)
                        if ship then
                            F.stock_adjust(source, g.stem, -ship.gross)
                            dest.incoming[g.stem] = (dest.incoming[g.stem] or 0) + ship.n
                            dest.incoming_use.provisions = (dest.incoming_use.provisions or 0) + ship.n
                        end
                        if F.ship_count(faction:name()) >= F.ship_cap(faction) then return end
                    end
                end
            end
        end
    end
end

-- ---- recurring routes and paid partner contracts ----------------------------------------
F.CART_MAX, F.ROUTE_MAX = 100, 50
F.SELL_RATE = DERPY_MR_FLOWS_SELL_RATE

-- A saved road is its hexes (F.road_steps) at F.ROAD_PER_TURN, as F.convoy_turns counts them, with a shipment's own ceiling of six turns.
-- The panel asks with no road (a search per refresh is too dear), so its figure is the straight-line lower bound and reads "at least".
function F.route_turns(from, to, road)
    if road and #road > 0 then
        return math.max(1, math.min(6, math.ceil(F.road_steps(road) / F.ROAD_PER_TURN)))
    end
    local a, b = from:settlement(), to:settlement()
    local dx, dy = a:logical_position_x() - b:logical_position_x(), a:logical_position_y() - b:logical_position_y()
    -- ponytail: no saved road means the longer span, a true lower bound (every step and bridge costs its own span), not the Euclidean distance.
    return math.max(1, math.min(6, math.ceil(math.max(math.abs(dx), math.abs(dy)) / F.ROAD_PER_TURN)))
end

function F.ship_due(s) return s.due or (s.at + F.SHIP.turns) end

function F.live(fkey)
    local f = cm:get_faction(fkey)
    if f and not f:is_null_interface() and not f:is_dead() then return f end
    return nil
end

function F.partners(a, b)
    if not a or not b or a:at_war_with(b) then return false end
    local ps = a:factions_trading_with()
    if type(ps) == "boolean" then return false end
    for i = 0, ps:num_items() - 1 do if ps:item_at(i):name() == b:name() then return true end end
    return false
end

function F.routes(faction)
    local out, b = {}, F.state.factions[faction:name()]
    for _, o in pairs(b and b.routes or {}) do out[#out + 1] = o end
    table.sort(out, function(a, b) return tonumber(a.id) < tonumber(b.id) end)
    return out
end

-- mode: as F.reach; the panel passes 'show', the model's own callers nothing.
function F.route_status(faction, o, mode)
    local seller = F.live(o.seller)
    if not seller or not F.live(faction:name()) then return nil, "The seller or buyer is gone" end
    local from, to = F.owned(seller, o.from), F.owned(faction, o.to)
    if not from or not to then return nil, "One of the two settlements has changed hands" end
    if o.seller ~= faction:name() and not F.partners(faction, seller) then return nil, "Needs a trade agreement" end
    if o.seller ~= faction:name() then
        local open, why = F.reach(from, to, mode)
        if open == false then return nil, F.REACH_WHY[why] end
    end
    if not F.uses_stores(faction) or not F.uses_stores(seller) then return nil, "One side keeps no stores" end
    if F.stopped(o.seller, "export", o.stem) or F.stopped(faction:name(), "import", o.stem) then
        return nil, "Trade in this resource is stopped"
    end
    if o.seller ~= faction:name() and not F.pool(from, o.stem) then return nil, "The seller cannot store it" end
    return { from = from, to = to, seller = seller }, "Ready"
end

function F.route_create(faction, from_key, to_key, stem, target, batch)
    target, batch = tonumber(target), tonumber(batch)
    if not F.is_human(faction:name()) or not F.rates().actions or not F.GOOD[stem]
        or not F.stock_number(target) or target < 1 or not F.stock_number(batch) or batch < 2 or batch > F.CART_MAX
        or #F.routes(faction) >= F.ROUTE_MAX or from_key == to_key then return nil end
    local from = cm:get_region(from_key)
    if not from or from:is_null_interface() or from:is_abandoned() then return nil end
    local seller = from:owning_faction():name()
    for _, o in ipairs(F.routes(faction)) do
        if o.from == from_key and o.to == to_key and o.stem == stem then return nil end
    end
    local o = { from = from_key, to = to_key, stem = stem, seller = seller, target = target, batch = batch, enabled = true }
    if not F.route_status(faction, o) then return nil end
    F.state.route_seq = (F.state.route_seq or 0) + 1
    o.id = tostring(F.state.route_seq)
    local b = F.book(faction:name()); b.routes = b.routes or {}; b.routes[o.id] = o
    return o
end

function F.route_control(faction, id, op)
    local b = F.state.factions[faction:name()]
    local o = b and b.routes and b.routes[id]
    if not o or not F.is_human(faction:name()) or not F.rates().actions then return false end
    if op == "toggle" then o.enabled = not o.enabled
    elseif op == "cancel" then
        b.routes[id] = nil
        local carts = {}
        for _, s in ipairs(F.ships()) do
            if s.f == faction:name() and s.route == id and s.sender then carts[#carts + 1] = s end
        end
        for _, s in ipairs(carts) do F.route_return(s) end
    else return false end
    return true
end

function F.route_edit(faction, id, field, value)
    local b = F.state.factions[faction:name()]
    local o = b and b.routes and b.routes[id]
    local n = tonumber(value)
    if not o or not F.is_human(faction:name()) or not F.rates().actions or not F.stock_number(n) then return false end
    if field == "target" and n >= 1 then o.target = n
    elseif field == "batch" and n >= 2 and n <= F.CART_MAX then o.batch = n
    else return false end
    return true
end

function F.route_covers(faction, rkey, use)
    for _, o in ipairs(F.routes(faction)) do
        if o.to == rkey and F.GOOD[o.stem].use == use then return true end
    end
    return false
end

-- Verify native debits before publishing cargo or escrow. Restore a partial write on failure. `kind` is the
-- factor the engine books it under (what the resource's breakdown calls it); nil is KIND.move.
function F.route_goods(region, stem, delta, kind)
    local before = F.held(region, stem)
    local key = F.PREFIX .. stem .. "_" .. (kind or KIND.move)
    local ok = pcall(function() F.pool_add(region, key, delta) end)
    if ok and F.held(region, stem) == before + delta then return true end
    local restore = before - F.held(region, stem)
    if restore ~= 0 then pcall(function() F.pool_add(region, key, restore) end) end
    if F.held(region, stem) ~= before then error("route stock rollback failed") end
    return false
end

function F.route_gold(faction, delta)
    if delta == 0 then return true end
    local before = faction:treasury()
    local ok = pcall(function() cm:treasury_mod(faction:name(), delta) end)
    if ok and faction:treasury() == before + delta then return true end
    local restore = before - faction:treasury()
    if restore ~= 0 then pcall(function() cm:treasury_mod(faction:name(), restore) end) end
    if faction:treasury() ~= before then error("route gold rollback failed") end
    return false
end

function F.route_settle(s, delivered)
    if not s.sender or s.settled then return end
    s.settled = true
    local pay = math.min(s.escrow, F.gold(delivered, s.price_c))
    local refund = s.escrow - pay
    F.state.contracts = F.state.contracts or { paid = 0, refunded = 0, lost = 0 }
    local book = F.state.contracts
    for _, v in ipairs({ { s.sender, pay, "paid" }, { s.recipient, refund, "refunded" } }) do
        local f = F.live(v[1])
        if v[2] > 0 then
            local field = f and F.route_gold(f, v[2]) and v[3] or "lost"
            book[field] = (book[field] or 0) + v[2]
        end
    end
end

function F.route_return(s)
    if F.ship_by_id(s.id) ~= s then return end
    F.drop(s)
    local seller = F.live(s.sender)
    if seller then
        local to = F.owned(seller, s.from) or F.nearest(seller, s.x, s.y)
        F.move(nil, to, s.stem, s.n, KIND.move, nil, s.sender)
    end
end

function F.routes_turn(faction)
    if not F.rates().actions or not F.uses_stores(faction) then return end
    local turn = cm:model():turn_number()
    for _, o in ipairs(F.routes(faction)) do
        if o.enabled and o.done ~= turn then
            o.done = turn
            local st, why = F.route_status(faction, o)
            o.status = why
            if st then
                local incoming = F.incoming(faction:name(), o.to, o.stem)
                local need = math.max(0, math.min(o.target - F.held(st.to, o.stem) - incoming, F.free(st.to, o.stem) - incoming))
                local fit = F.fit_delivery(o.batch, need)
                if fit then
                    local ship, why = F.ship(faction, st.from, st.to, o.stem, fit.n, o)
                    o.status = (ship and "Cart sent") or (why == "blockaded" and "Blockaded")
                        or "Waiting for goods or gold or road space"
                else o.status = "You have enough including what is on the way" end
            end
        end
    end
end

function F.sanitize_routes()
    local max_id = 0
    for _, b in pairs(F.state.factions) do
        local clean = {}
        for id, o in pairs(type(b.routes) == "table" and b.routes or {}) do
            local n = tonumber(id)
            if type(o) == "table" and n and F.stock_number(n) and n > 0 and o.id == id and F.GOOD[o.stem]
                and type(o.from) == "string" and type(o.to) == "string" and type(o.seller) == "string"
                and F.stock_number(o.target) and o.target > 0 and F.stock_number(o.batch) and o.batch >= 2 and o.batch <= F.CART_MAX then
                clean[id] = o; max_id = math.max(max_id, n)
                o.price = nil
                if not F.stock_number(o.last_price_c) then o.last_price_c = nil end
                if o.done ~= nil and not F.stock_number(o.done) then o.done = nil end
                o.enabled = o.enabled == true
            end
        end
        b.routes = next(clean) and clean or nil
    end
    F.state.route_seq = math.max(max_id, F.stock_number(F.state.route_seq) and F.state.route_seq or 0)
end

-- A save from before local prices holds the cart's price as whole gold; one with escrow and no
-- price at all is unreadable, so it settles at 0: the buyer gets the escrow back whole.
function F.sanitize_ships()
    for _, s in ipairs(F.ships()) do
        if type(s) == "table" then
            if s.escrow ~= nil and not F.stock_number(s.price_c) then
                s.price_c = F.stock_number(s.price) and s.price * F.PCT or 0
            end
            s.price = nil
            if not F.tolls_sound(s.tolls) then s.tolls = nil end
        end
    end
end

-- THE ONE DOOR. parts = {action, args...}: a trade switch (export|import, stem), or an action
-- with exactly its own count of parts. Humans only; the actions only with the MCT switch on.
F.ACTIONS = { send = 3, order = 2, sell = 2, supply = 3, work = 2, upgrade = 3, aim = 3, found = 2, economy = 3, provisions = 3, route_new = 6, route_ctl = 3, route_edit = 4, edict = 3, guards = 2 }
-- the switch an action needs: an edict is not a Vault action, and has its own; so have the guards
F.ACTION_SWITCH = { supply = "supply", edict = "edicts", guards = "bandits" }
function F.dispatch(fkey, parts)
    if not F.is_human(fkey) then return end
    -- the map's cart goods come from kept trade previews (terrain_routes.lua R.plans): an action shows on its
    -- next tick, not once that seller's renewal comes round (2026-10-30: a re-allowed export took 6.3 s)
    local R = DERPY_MR_TERRAIN_ROUTES
    if R then R.plans, R.dirty = {}, true end
    local a = parts[1]
    if F.DIRS[a] then
        if #parts == 2 then F.apply(fkey, a, parts[2]) end
        return
    end
    if a == "stock" then
        if #parts == 4 then F.set_stock_policy(fkey, parts[2], parts[3], parts[4]) end
        return
    end
    if F.ACTIONS[a] ~= #parts then return end
    if not F.rates()[F.ACTION_SWITCH[a] or "actions"] then return end
    local f = cm:get_faction(fkey)
    if a == "edict" then F.edict_set(f, parts[2], parts[3])
    elseif a == "guards" then F.set_guards(f, parts[2])
    elseif a == "route_new" then F.route_create(f, parts[2], parts[3], parts[4], parts[5], parts[6])
    elseif a == "route_ctl" then F.route_control(f, parts[2], parts[3])
    elseif a == "route_edit" then F.route_edit(f, parts[2], parts[3], parts[4])
    elseif a == "send" then F.send_here(f, parts[2], parts[3])
    elseif a == "provisions" then F.provision_action(f, parts[2], parts[3])
    elseif a == "economy" then F.economy_toggle(f, parts[2], parts[3])
    elseif a == "supply" then F.toggle_supply(f, parts[2], parts[3])
    elseif a == "order" then F.order(f, parts[2])
    elseif a == "work" then F.work(f, parts[2])
    elseif a == "upgrade" then F.work(f, parts[2], parts[3])
    elseif a == "aim" then
        local cqi = tonumber(parts[3])
        if cqi then F.work(f, parts[2], nil, cqi) end
    elseif a == "found" then F.found(f, parts[2])
    else F.sell(f, parts[2]) end
end

-- A CLICK NEVER WRITES THE MODEL ITSELF IN MULTIPLAYER: it goes out as a UITrigger, which CA
-- delivers to every machine in one order, and the listener runs it everywhere at once.
function F.request(fkey, ...)
    local parts = { ... }
    local mp = false
    pcall(function() mp = cm:is_multiplayer() end)
    if not mp then return F.dispatch(fkey, parts) end
    local f = cm:get_faction(fkey)
    if not f or f:is_null_interface() then return end
    CampaignUI.TriggerCampaignScriptEvent(f:command_queue_index(), F.TAG .. "|" .. table.concat(parts, "|"))
end

-- "dmr1|a|b|c" -> {a, b, c}; nil for another mod's id or a part that is not [%w_]+.
function F.parse(id)
    if type(id) ~= "string" or string.sub(id, 1, #F.TAG + 1) ~= F.TAG .. "|" then return nil end
    if string.find(id, "||") or string.sub(id, -1) == "|" then return nil end
    local parts = {}
    for p in string.gmatch(string.sub(id, #F.TAG + 2), "[^|]+") do
        if not string.match(p, "^[%w_]+$") then return nil end
        parts[#parts + 1] = p
    end
    return parts
end

-- ---- store events (spending spec section 4, phase 6) --------------------------------------
-- A full store offers a choice at its owner's turn start. A player gets the event's DB dilemma
-- (FIRST spends and rewards, SECOND declines) and the spend happens here when it is answered: a
-- dilemma payload cannot charge a REGION pool. A computer-run faction takes the same deal on a
-- roll. At most one event per faction every EVENT_GAP turns, counted from the offer.
F.EVENT_GAP, F.EVENT_AI_PCT = DERPY_MR_FLOWS_EVENT[1], DERPY_MR_FLOWS_EVENT[2]
-- a siege cannot wait; the rest take turns. Part E's six follow the tribute.
F.EVENT_ORDER = { "siege", "feast", "feast_chd", "arsenal", "tribute", "smugglers", "guild", "grain_rot", "caravan_master",
                  "toll_dispute", "blockade_runner" }
-- PART E's offers, one rule each, by key: function(faction, stocks) -> the offer or nil (filled below them)
F.EVENT_OFFERS = {}
F.DIPLO_BONUS = 3                                            -- CA's change type, -6..+6
F.EVENT_BY_DILEMMA = {}
for k, e in pairs(DERPY_MR_FLOWS_EVENTS) do F.EVENT_BY_DILEMMA[e.dilemma] = k end

-- The settlement holding the most of a use, at least `cost`; ties by key. `siege`: only a
-- settlement under siege counts.
function F.event_region(stocks, use, cost, siege)
    local best, bh = nil, nil
    for _, s in ipairs(stocks) do
        local h = F.use_total(s.held, use)
        if h >= cost and (not siege or s.region:garrison_residence():is_under_siege())
                and (bh == nil or h > bh or (h == bh and s.region:name() < best:name())) then
            best, bh = s.region, h
        end
    end
    return best
end

-- A neighbour at peace: the owner of a region next to one of ours, not us, not rebels, not at
-- war with us. The first by key, so every machine names the same one.
function F.event_neighbour(faction)
    local best = nil
    local rl = faction:region_list()
    for i = 0, rl:num_items() - 1 do
        local adj = rl:item_at(i):adjacent_region_list()
        for j = 0, adj:num_items() - 1 do
            local o = adj:item_at(j):owning_faction()
            if not o:is_null_interface() and o:name() ~= faction:name() and not o:is_rebel()
                    and not faction:at_war_with(o) and (best == nil or o:name() < best:name()) then
                best = o
            end
        end
    end
    return best
end

-- The largest army in the field: never a garrison or a convoy; ties by the general's cqi.
function F.event_army(faction)
    local best, bn, bc = nil, nil, nil
    local list = faction:military_force_list()
    for i = 0, list:num_items() - 1 do
        local mf = list:item_at(i)
        if not mf:is_armed_citizenry() and mf:has_general() and mf:force_type():key() ~= "CONVOY" then
            local n, c = mf:unit_list():num_items(), mf:general_character():command_queue_index()
            if bn == nil or n > bn or (n == bn and c < bc) then best, bn, bc = mf, n, c end
        end
    end
    return best
end

-- An event's gates (Part E): every switch it needs is on, and a players-only event goes to a player.
function F.event_gated(faction, e)
    local r = F.rates()
    for _, s in ipairs(e.needs or {}) do
        if not r[s] then return false end
    end
    return not e.human or faction:is_human()
end

-- What `key` would be offered now: {key, region, target, char, force}, or nil.
function F.event_offer(faction, key, stocks)
    local e = DERPY_MR_FLOWS_EVENTS[key]
    if not (F.work_open(faction, e) and F.event_gated(faction, e)) then return nil end
    local own = F.EVENT_OFFERS[key]
    if own then return own(faction, stocks) end
    -- the store rule below offers wherever `cost` is held: at 0 that is every store, so an event of 0 has its own
    if e.cost <= 0 then return nil end
    if e.where == "region" then
        local r = F.event_region(stocks, e.use, e.cost, key == "siege")
        return r and { key = key, region = r:name() } or nil
    end
    local have = 0
    for _, s in ipairs(stocks) do have = have + F.use_total(s.held, e.use) end
    if have < e.cost then return nil end
    if key == "tribute" then
        local n = F.event_neighbour(faction)
        return n and { key = key, target = n:name() } or nil
    elseif key == "arsenal" then
        local mf = F.event_army(faction)
        return mf and { key = key, char = mf:general_character():command_queue_index(),
                        force = mf:command_queue_index() } or nil
    end
    return { key = key }
end

function F.event_book(fkey)
    F.state.events = F.state.events or {}
    local b = F.state.events[fkey]
    if not b then b = { at = -1000000, seen = {} }; F.state.events[fkey] = b end
    return b
end

-- A siege first; otherwise the qualifying event offered longest ago, ties in EVENT_ORDER.
function F.event_pick(faction, b)
    local stocks, best, bt = F.stocks(faction), nil, nil
    for _, key in ipairs(F.EVENT_ORDER) do
        local o = F.event_offer(faction, key, stocks)
        if o and key == "siege" then return o end
        local t = b.seen[key] or -1000000
        if o and (bt == nil or t < bt) then best, bt = o, t end
    end
    return best
end

-- The spend and the reward for `choice`. Part E's events have their own (F.EVENT_APPLY); the rest act on FIRST
-- only. A store short of the cost when this runs pays nothing and gets nothing.
function F.event_apply(faction, p, choice)
    local own = F.EVENT_APPLY[p.key]
    if own then return own(faction, p, choice) end
    if choice ~= "FIRST" then return end
    local e, fkey = DERPY_MR_FLOWS_EVENTS[p.key], faction:name()
    local pick = F.bulk(e.use)
    if e.where == "region" then
        local r = F.owned(faction, p.region)
        if not r then return end
        local held = F.stock(r)
        if F.use_total(held, e.use) < e.cost then return end
        F.draw(r, held, e.use, e.cost, KIND.spend, fkey)
        cm:apply_effect_bundle_to_region(e.bundle, p.region, e.turns)
        if p.key == "restore" then F.repair(r) end
        return
    end
    local stocks, have = F.stocks(faction), 0
    for _, s in ipairs(stocks) do have = have + F.use_total(s.held, e.use) end
    if have < e.cost then return end
    F.draw_realm(stocks, pick, e.cost, KIND.spend, fkey)
    if p.key == "tribute" then
        cm:apply_dilemma_diplomatic_bonus(fkey, p.target, F.DIPLO_BONUS)   -- the giver acts, the neighbour's regard moves
    elseif p.key == "arsenal" then
        cm:add_experience_to_units_commanded_by_character("character_cqi:" .. p.char, 1)
    end
end

function F.events(faction)
    local r = F.rates()
    if not r.events or not F.uses_stores(faction) then return end
    local human = faction:is_human()
    if not (human or r.ai) then return end
    local fkey, turn = faction:name(), cm:model():turn_number()
    local b = F.event_book(fkey)
    if turn - b.at < F.EVENT_GAP then return end
    local o = F.event_pick(faction, b)
    if not o then return end
    if human then
        local e = DERPY_MR_FLOWS_EVENTS[o.key]
        local tf = o.target and cm:get_faction(o.target):command_queue_index() or 0
        if o.key == "guild" then tf = F.name_good(faction, o.stem) end
        local rg = o.region and cm:get_region(o.region):cqi() or 0
        F.set_pending(fkey, o)
        -- false: never issued (multiplayer, a target gone); no offer waits and no gap starts.
        -- Single player always answers true, as CA wraps it in an intervention.
        if not cm:trigger_dilemma_with_targets(faction:command_queue_index(), e.dilemma, tf, 0, o.char or 0,
                                               o.force or 0, rg, 0, function() end) then
            F.clear_pending(fkey, o.key)
            return
        end
    else
        if cm:random_number(100, 1) > F.EVENT_AI_PCT then return end   -- a failed roll starts no gap
        F.event_apply(faction, o, "FIRST")
    end
    b.at, b.seen[o.key] = turn, turn
end

-- THE GUILD'S GOOD: no dilemma target can be a good, so its name goes in a script value the dilemma's text reads,
-- keyed by the player's faction CQI, and the player rides as the target faction (as CA's sea encounters pass it).
-- The faction's CQI, for that target.
F.GUILD_GOOD = "derpy_mr_guild_good_"
function F.name_good(faction, stem)
    local cqi = faction:command_queue_index()
    local s = common.get_localised_string("pooled_resources_display_name_" .. F.PREFIX .. stem)
    common.set_context_value(F.GUILD_GOOD .. cqi, (s ~= nil and s ~= "") and s or stem)
    return cqi
end

-- Script values are not saved: a guild offer still waiting after a load names its good again.
function F.name_pending_goods()
    for fkey, p in pairs(F.state.pending or {}) do
        local o = type(p) == "table" and (p.guild or (p.key == "guild" and p))
        local f = o and F.GOOD[o.stem] and F.live(fkey)
        if f then F.name_good(f, o.stem) end
    end
end

function F.on_dilemma(context)
    local faction = context:faction()
    local fkey, key = faction:name(), F.EVENT_BY_DILEMMA[context:dilemma()]
    local p = key and F.pending(fkey, key)
    if not p then return end
    F.clear_pending(fkey, key)
    if key == "raid" then return F.raid_answer(faction, p, context:choice_key()) end
    if string.sub(key, 1, 5) == "road_" then return F.road_answer(faction, p, context:choice_key()) end
    F.event_apply(faction, p, context:choice_key())
end

-- AN UNANSWERED OFFER, one per faction and event: a Restore offered on capture must not wipe a
-- store event still waiting for its answer. A save from before kept one per faction, {key = ...}.
function F.pending(fkey, key)
    local p = F.state.pending and F.state.pending[fkey]
    if not p then return nil end
    if p.key then return p.key == key and p or nil end
    return p[key]
end

function F.set_pending(fkey, o)
    F.state.pending = F.state.pending or {}
    local p = F.state.pending[fkey]
    if not p or p.key then
        p = {}
        F.state.pending[fkey] = p
    end
    p[o.key] = o
end

function F.clear_pending(fkey, key)
    local p = F.state.pending and F.state.pending[fkey]
    if not p then return end
    if p.key then F.state.pending[fkey] = nil else p[key] = nil end
end

-- Every building in the settlement mended.
function F.repair(region)
    local sl = region:settlement():slot_list()
    for i = 0, sl:num_items() - 1 do
        local slot = sl:item_at(i)
        if slot:has_building() then cm:region_slot_instantly_repair_building(slot) end
    end
end

-- RESTORE ON CAPTURE (spending spec section 4, part 2): occupying a settlement whose captured
-- stores hold the cost in building materials offers Restore, a store event's dilemma; a
-- computer-run faction takes it on the events' roll. Under the store events switch.
F.RESTORE_ON = { occupation_decision_occupy = true, occupation_decision_loot = true }   -- loot: author, 2026-10-08
function F.on_restore(context)
    if not F.RESTORE_ON[context:occupation_decision_type()] then return end
    local r, faction = F.rates(), context:character():faction()
    if not r.events or not F.uses_stores(faction) then return end
    local human = faction:is_human()
    if not (human or r.ai) then return end
    local region = context:garrison_residence():region()
    local e = DERPY_MR_FLOWS_EVENTS.restore
    if F.use_total(F.stock(region), e.use) < e.cost then return end
    local turn = cm:model():turn_number()
    local o = { key = "restore", region = region:name(), turn = turn }
    if human then
        -- ONE RESTORE AT A TIME: the answer does not say which settlement it is for, so a second
        -- offer replaced the first and the first answer paid for and repaired the second. A
        -- pending one from an earlier turn is stale (a dilemma is answered before the turn ends).
        local p = F.pending(faction:name(), "restore")
        if p and p.turn == turn then return end
        F.set_pending(faction:name(), o)
        if not cm:trigger_dilemma_with_targets(faction:command_queue_index(), e.dilemma, 0, 0, 0, 0, region:cqi(), 0,
                                               function() end) then
            F.clear_pending(faction:name(), "restore")   -- never issued (multiplayer returns false)
        end
    elseif cm:random_number(100, 1) <= F.EVENT_AI_PCT then
        F.event_apply(faction, o, "FIRST")
    end
end

-- ---- Part E: store events that read the stores (design 2026-11-01, section 8) ----------------
-- Each is offered by its own rule (F.EVENT_OFFERS) and settled by its own apply (F.EVENT_APPLY), which is
-- handed the answered choice. Literals stay right of their operators (the game's compiler).
F.EVENT_APPLY = {}

-- The cheapest good of `use` a store can hold, ties by stem.
local function cheapest(fkey, v, use)
    local best, bp = nil, nil
    for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
        if F.bulk(use)(g) and (v.capacity[g.stem] or 0) > 0 then
            local p = F.price(g, fkey)
            if bp == nil or p < bp or (p == bp and g.stem < best) then best, bp = g.stem, p end
        end
    end
    return best
end

local function smuggle_gold(n, buy) return math.ceil(n * buy * 150 / (F.PCT * F.PCT)) end

-- SMUGGLERS: the first store by key under 2 turns of provisions, then the first under 2 turns of war
-- materials, is offered 5 turns of its use (at most 100) in its cheapest good, at half again the local
-- buying price, when the treasury holds that. It works out each store's turns of use and nothing else of
-- its view (a whole view per store was 190 ms a round), and quotes only a store that is short.
function F.smuggle_offer(faction, stocks)
    -- NOT IN THE FIRST EVENT_GAP TURNS (Workshop report, 2026-11-07): every store starts empty, so every faction was
    -- "short" on turn 1 and a yes put -3 control on its first settlement by key (Altdorf for the Empire) for turns 1-5
    if cm:model():turn_number() <= F.EVENT_GAP then return nil end
    local sorted, provinces, uses = {}, F.provinces(faction), {}
    for _, s in ipairs(stocks) do sorted[#sorted + 1] = s end
    table.sort(sorted, function(a, b) return a.region:name() < b.region:name() end)
    for _, use in ipairs({ "provisions", "war" }) do
        for _, s in ipairs(sorted) do
            local r = s.region
            uses[r:name()] = uses[r:name()] or F.recurring_use(faction, r, provinces)
            local per, held = uses[r:name()][use] or 0, F.use_total(s.held, use)
            if per > 0 and held < per * 2 then
                local stem = cheapest(faction:name(), s, use)
                local q = stem and F.quote(faction, r, stem)
                local n = math.min(100, per * 5 - held)
                if q and smuggle_gold(n, q.buy) <= faction:treasury() then
                    return { key = "smugglers", region = r:name(), use = use, stem = stem, n = n, gold = smuggle_gold(n, q.buy) }
                end
            end
        end
    end
    return nil
end

-- The price is the local one at the answer, for what fits; nothing happens when the treasury cannot pay it.
F.EVENT_APPLY.smugglers = function(faction, p, choice)
    if choice ~= "FIRST" or not F.GOOD[p.stem] then return end
    local r = F.owned(faction, p.region)
    local q = r and F.quote(faction, r, p.stem)
    if not q then return end
    local n = math.min(p.n, F.free(r, p.stem))
    local gold = smuggle_gold(n, q.buy)
    if n <= 0 or gold > faction:treasury() then return end
    cm:treasury_mod(faction:name(), -gold)
    F.move(nil, r, p.stem, n, KIND.trade, nil, faction:name())
    local e = DERPY_MR_FLOWS_EVENTS.smugglers
    cm:apply_effect_bundle_to_region(e.bundle, p.region, e.turns)
end

-- MERCHANT GUILD: the common good the realm holds the most of for its space, when that is above three
-- quarters of it; ties by stem.
function F.guild_offer(faction, stocks)
    local held, space = {}, {}
    for _, s in ipairs(stocks) do
        for stem, c in pairs(s.capacity) do
            held[stem], space[stem] = (held[stem] or 0) + (s.held[stem] or 0), (space[stem] or 0) + c
        end
    end
    local best, bh, bc = nil, nil, nil
    for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
        local h, c = held[g.stem] or 0, space[g.stem] or 0
        if not g.rare and c > 0 and h * 100 > c * 75
                and (best == nil or h * bc > bh * c or (h * bc == bh * c and g.stem < best)) then
            best, bh, bc = g.stem, h, c
        end
    end
    return best and { key = "guild", stem = best } or nil
end

F.EVENT_APPLY.guild = function(faction, p, choice)
    if choice ~= "FIRST" or not F.GOOD[p.stem] then return end
    F.state.sales = F.state.sales or {}
    F.state.sales[faction:name()] = { stem = p.stem, per = 20, left = 10 }
end

-- A STANDING SALE: up to `per` from the fullest stores each turn start, paid a fifth above the fullest
-- store's local selling price. It ends after its turns, or the first turn the realm cannot fill it.
function F.sales_turn(faction)
    local fkey = faction:name()
    local s = F.state.sales and F.state.sales[fkey]
    if not s then return end
    local stocks, top = F.stocks(faction), nil
    for _, x in ipairs(stocks) do
        local h, th = x.held[s.stem] or 0, top and (top.held[s.stem] or 0)
        if h > 0 and (top == nil or h > th or (h == th and x.region:name() < top.region:name())) then top = x end
    end
    local q = top and F.quote(faction, top.region, s.stem)
    local sold = q and F.draw_realm(stocks, function(g) return g.stem == s.stem end, s.per, KIND.sell, fkey) or 0
    if sold > 0 then cm:treasury_mod(fkey, F.gold(sold, math.floor(q.sell * 120 / 100))) end
    s.left = s.left - 1
    if s.left <= 0 or sold < s.per then F.state.sales[fkey] = nil end
end

-- On load: a sale of a good this build lacks, a rare one, or with no turns left is dropped.
function F.sanitize_sales()
    if type(F.state.sales) ~= "table" then
        F.state.sales = nil
        return
    end
    for fkey, s in pairs(F.state.sales) do
        local g = type(s) == "table" and F.GOOD[s.stem]
        if not (g and not g.rare and type(s.per) == "number" and s.per > 0 and type(s.left) == "number" and s.left > 0) then
            F.state.sales[fkey] = nil
        end
    end
end

-- GRAIN ROT: the first store by key holding 100 grain or more above its safe share, while grain spoils.
function F.rot_offer(faction, stocks)
    if not F.spoils(faction) then return nil end
    local safe, best = F.spoil_safe(faction:name(), "grain"), nil
    for _, s in ipairs(stocks) do
        local _h, _c, capacity = F.stock(s.region)
        local over = (s.held.grain or 0) - math.floor((capacity.grain or 0) * safe / 100)
        if over >= 100 and (best == nil or s.region:name() < best) then best = s.region:name() end
    end
    return best and { key = "grain_rot", region = best } or nil
end

-- Either choice loses its share of what the store holds now; the 50 gold is paid only when it is there.
F.EVENT_APPLY.grain_rot = function(faction, p, choice)
    local r = F.owned(faction, p.region)
    if not r then return end
    local fkey, pct = faction:name(), 30
    if choice == "FIRST" then
        pct = 5
        if faction:treasury() >= 50 then cm:treasury_mod(fkey, -50) end
    end
    F.move(r, nil, "grain", math.floor(F.held(r, "grain") * pct / 100), KIND.spoil, fkey, nil)
end

-- The faction's convoys and shipments on the road.
local function own_cargo(fkey)
    local out = {}
    for _, c in ipairs(F.convoys()) do
        if c.f == fkey then out[#out + 1] = c end
    end
    for _, s in ipairs(F.ships()) do
        if s.f == fkey then out[#out + 1] = s end
    end
    return out
end

-- CARAVAN MASTER: some of the faction's cargo is on a road where an ambush can come (its threat as Part D
-- last read it).
function F.caravan_offer(faction)
    for _, rec in ipairs(own_cargo(faction:name())) do
        if (tonumber(rec.threat) or 0) >= F.ROAD.ambush_min then return { key = "caravan_master" } end
    end
    return nil
end

-- A twentieth of the value of all its cargo on the road, then 10 turns of safe roads (F.road_event); nothing
-- happens when the treasury cannot pay it.
F.EVENT_APPLY.caravan_master = function(faction, p, choice)
    if choice ~= "FIRST" then return end
    local fkey, value = faction:name(), 0
    for _, rec in ipairs(own_cargo(fkey)) do value = value + F.cargo_value_base(rec) end
    local fee = math.floor(value * 5 / 100)
    if fee > faction:treasury() then return end
    if fee > 0 then cm:treasury_mod(fkey, -fee) end
    F.state.road_safe = F.state.road_safe or {}
    F.state.road_safe[fkey] = cm:model():turn_number() + 10
end

-- TOLL DISPUTE: the first faction by key that paid this one 50 or more in tolls last turn.
function F.toll_offer(faction)
    -- only a realm that still charges: roads set Open (or Closed) since last turn's tolls leave nothing to dispute
    if F.edict(faction:name(), "roads") ~= "tolled" then return nil end
    local d = F.tolls_last(faction:name())
    if not d then return nil end
    local keys = {}
    for k in pairs(d.by) do keys[#keys + 1] = k end
    table.sort(keys)
    for _, k in ipairs(keys) do
        if d.by[k].got >= 50 and F.live(k) then return { key = "toll_dispute", target = k } end
    end
    return nil
end

-- FIRST opens the roads past any wait, which starts a new one; either choice moves that faction's regard.
F.EVENT_APPLY.toll_dispute = function(faction, p, choice)
    if not F.live(p.target) then return end
    local bonus = F.DIPLO_BONUS
    if choice == "FIRST" then F.edict_set(faction, "roads", "open", true) else bonus = -F.DIPLO_BONUS end
    cm:apply_dilemma_diplomatic_bonus(faction:name(), p.target, bonus)
end

local function trades_with(faction, key)
    local partners = faction:factions_trading_with()
    if type(partners) == "boolean" then return false end   -- the rebels' answer
    for i = 0, partners:num_items() - 1 do
        if partners:item_at(i):name() == key then return true end
    end
    return false
end

-- A convoy this faction sent that partner this turn: the saved record, so a reload still knows.
local function sent_this_turn(fkey, partner, turn)
    for _, c in ipairs(F.convoys()) do
        if c.f == fkey and c.buyer == partner and c.at == turn then return c end
    end
    return nil
end

-- BLOCKADE RUNNER: the first partner by key whose road a blockade stopped this turn, and whose goods have not gone
-- yet (seen 2026-11-03: a blockade seen after the turn's convoy brought a runner whose answer sent nothing).
function F.runner_offer(faction)
    local fkey, turn, keys = faction:name(), cm:model():turn_number(), {}
    local partners = faction:factions_trading_with()
    if type(partners) == "boolean" then return nil end
    for i = 0, partners:num_items() - 1 do keys[#keys + 1] = partners:item_at(i):name() end
    table.sort(keys)
    for _, k in ipairs(keys) do
        local hit = F.blockade_known[pair_key(fkey, k)]
        local partner = hit and hit.turn == turn and not sent_this_turn(fkey, k, turn) and F.live(k)
        -- only where this turn's trade would send something past the army: a runner with nothing to run is no offer
        if partner and F.trade_pair(faction, partner, nil, true, { blockade_ok = true }) then
            return { key = "blockade_runner", target = k }
        end
    end
    return nil
end


-- This turn's trade with that partner goes past the blockade, once a turn, whether or not the army is still
-- there, while the two still trade; a tenth of what leaves is paid when the treasury holds it. Goods that got
-- through clear the pair's blockade for the turn, and the next turn's trade looks again.
F.EVENT_APPLY.blockade_runner = function(faction, p, choice)
    local partner, fkey, turn = F.live(p.target), faction:name(), cm:model():turn_number()
    if choice ~= "FIRST" or not partner or not trades_with(faction, p.target) or sent_this_turn(fkey, p.target, turn) then
        return
    end
    F.trade_pair(faction, partner, nil, false, { blockade_ok = true })
    local c = sent_this_turn(fkey, p.target, turn)
    if not c then return end
    F.record_blockade(fkey, p.target, nil)
    local fee = math.floor(F.cargo_value_base(c) * 10 / 100)
    if fee > 0 and fee <= faction:treasury() then cm:treasury_mod(fkey, -fee) end
end

F.EVENT_OFFERS.smugglers, F.EVENT_OFFERS.guild, F.EVENT_OFFERS.grain_rot = F.smuggle_offer, F.guild_offer, F.rot_offer
F.EVENT_OFFERS.caravan_master, F.EVENT_OFFERS.toll_dispute, F.EVENT_OFFERS.blockade_runner =
    F.caravan_offer, F.toll_offer, F.runner_offer

-- ---- province supplies and shipments (spending spec section 3, phase 5) -------------------
-- Three switches per province, paid each turn from the province capital's store, each put a
-- region bundle on every settlement the faction holds in the province. Goods reach a store by
-- shipment: saved travel time, drawn as a map marker, seized by an army of a faction at war
-- with the owner that walks in (AreaEntered) or stands within SHIP.near of it at the owner's
-- turn start. CA's own caravans cannot be sent anywhere by script (docs/TRADE_RESOURCES.md 24).
F.SHIP = DERPY_MR_FLOWS_SHIP
F.SHIP_PREFIX = "derpy_mr_ship_"
F.SUPPLY_KEYS = { standing = true }       -- the three supplies, and Supply the capital
for k in pairs(DERPY_MR_FLOWS_SUPPLY) do F.SUPPLY_KEYS[k] = true end

-- The settlements a faction holds, by province: {pk = {regions, capital}}, capital nil unless the
-- faction holds it; and the province keys in order, so every machine walks them alike.
function F.provinces(faction)
    local out, keys = {}, {}
    local rl = faction:region_list()
    for i = 0, rl:num_items() - 1 do
        local r = rl:item_at(i)
        if not r:is_null_interface() then
            local pk = r:province_name()
            if not out[pk] then
                out[pk] = { regions = {} }
                keys[#keys + 1] = pk
            end
            out[pk].regions[#out[pk].regions + 1] = r
        end
    end
    for _, pk in ipairs(keys) do
        local p = out[pk]
        local cap = p.regions[1]:province():capital_region()
        if cap and not cap:is_null_interface() then
            local o = cap:owning_faction()
            if not o:is_null_interface() and o:name() == faction:name() then p.capital = cap end
        end
    end
    table.sort(keys)
    return out, keys
end

-- One province's switches, kept in the save: {materials, stable, arms, standing = true, short =
-- {key = the turn it ran short}}. Made only when asked to.
function F.supply_book(fkey, pk, make)
    if not F.state.supply then
        if not make then return nil end
        F.state.supply = {}
    end
    local f = F.state.supply[fkey]
    if not f and make then f = {}; F.state.supply[fkey] = f end
    local b = f and f[pk]
    if not b and make then b = { short = {} }; f[pk] = b end
    return b
end

-- WHAT A PROVINCE CAPITAL'S DRILL-DOWN SHOWS: nil unless rkey is the faction's own capital of a
-- province. {cost a turn of each supply, on = {key = true}, short = {key = turn}, have = {use = n}}
function F.supply_state(faction, rkey)
    if not F.uses_stores(faction) then return nil end   -- F.supply would never pay: offer nothing
    local r = F.owned(faction, rkey)
    if not r then return nil end
    local p = (F.provinces(faction))[r:province_name()]
    if not (p and p.capital and p.capital:name() == rkey) then return nil end
    local b = F.supply_book(faction:name(), r:province_name(), false) or {}
    local st = { cost = F.SHIP.per * #p.regions, on = {}, short = {}, have = {} }
    for k in pairs(F.SUPPLY_KEYS) do
        if b[k] then st.on[k] = true end
        if b.short and b.short[k] then st.short[k] = b.short[k] end
    end
    local held = F.stock(p.capital)
    st.pay = {}
    for _, s in pairs(DERPY_MR_FLOWS_SUPPLY) do
        st.have[s.use] = F.use_total(held, s.use)
        -- what the payment takes first: the fullest, a tie by stem (F.draw_realm's order, one region)
        local best
        for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
            if F.bulk(s.use)(g) then
                local n = held[g.stem] or 0
                if not best or n > best.n or (n == best.n and g.stem < best.stem) then
                    best = { stem = g.stem, n = n }
                end
            end
        end
        if best then st.pay[s.use] = { stem = best.stem, n = best.n } end
    end
    return st
end

-- The capitals of the provinces a faction can supply, by province key: the Spending tab's rows.
function F.capitals(faction)
    local out = {}
    if not F.uses_stores(faction) then return out end
    local provs, keys = F.provinces(faction)
    for _, pk in ipairs(keys) do
        if provs[pk].capital then out[#out + 1] = provs[pk].capital:name() end
    end
    return out
end

function F.toggle_supply(faction, rkey, k)
    if not F.SUPPLY_KEYS[k] or not F.supply_state(faction, rkey) then return end
    local b = F.supply_book(faction:name(), F.owned(faction, rkey):province_name(), true)
    if b[k] then
        b[k] = nil
    else
        b[k], b.short[k] = true, nil
    end
end

-- ---- shipments ----
function F.ships()
    return F.state.ships or {}
end

function F.ship_count(fkey)
    local n = 0
    for _, s in ipairs(F.ships()) do
        if s.f == fkey then n = n + 1 end
    end
    return n
end

function F.ship_cap(faction)
    if faction:is_human() then return F.rates().ships end
    return F.SHIP.ai_cap
end

-- What is on the road to a store: the shipments in the order they left, then each agreement convoy's goods (one entry
-- a good, in goods order, carrying the convoy's arrival turn); every good when stem is nil.
function F.ships_to(fkey, rkey, stem)
    local out = {}
    for _, s in ipairs(F.ships()) do
        if (s.recipient or s.f) == fkey and s.to == rkey and (stem == nil or s.stem == stem) then out[#out + 1] = s end
    end
    for _, c in ipairs(F.convoys()) do
        if c.buyer == fkey and c.to == rkey then
            local due   -- looked up only for a convoy that lists something: F.incoming filters by good on the hot path
            for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
                local n = c.basket[g.stem]
                if n and n > 0 and (stem == nil or g.stem == stem) then
                    due = due or F.convoy_due(c)
                    out[#out + 1] = { stem = g.stem, n = n, due = due, convoy = c.id }
                end
            end
        end
    end
    return out
end

function F.incoming(fkey, rkey, stem)
    local n = 0
    for _, s in ipairs(F.ships_to(fkey, rkey, stem)) do n = n + s.n end
    return n
end

-- CA'S OWN SPOT BESIDE A SETTLEMENT, passable land, the way its marker manager places markers; the
-- settlement itself when it finds none (-1, -1). Whole numbers: a fraction does not cross the save.
function F.spot(fkey, region)
    local x, y = cm:find_valid_spawn_location_for_character_from_settlement(fkey, region:name(), false, true,
                                                                            F.SHIP.spot)
    if not x or x < 0 then
        local st = region:settlement()
        x, y = st:logical_position_x(), st:logical_position_y()
    end
    return math.floor(x + 0.5), math.floor(y + 0.5)
end

-- NO FACTION FILTER: any army may walk in; F.on_area decides who seizes. The marker draws nothing
-- (its prefab is the wagon circle's, which a marker cannot show; seen 2026-10-11), so CA's cth_caravan
-- scene is drawn on the same spot, facing the destination. The engine keeps both in the save.
function F.mark(s)
    cm:add_interactable_campaign_marker(s.id, F.SHIP.info, s.x, s.y, F.SHIP.radius, "", "")
    local fx, fy = s.x, s.y + 1
    pcall(function()
        local st = cm:get_region(s.to):settlement()
        if st:logical_position_x() ~= s.x or st:logical_position_y() ~= s.y then
            fx, fy = st:logical_position_x(), st:logical_position_y()
        end
    end)
    cm:add_scripted_composite_scene_to_logical_position(s.id, F.SHIP.scene, s.x, s.y, fx, fy, false, true, false)
end

function F.unmark(s)
    cm:remove_interactable_campaign_marker(s.id)
    cm:remove_scripted_composite_scene(s.id)
end

-- ---- escort battles (spec 2026-10-09) ------------------------------------------------------
-- A cart's escort is rolled when it leaves and saved on it as CA's unit list, so the cards the
-- Spending tab shows are the army a raider fights. CA's random-army templates by subculture
-- (DERPY_MR_FLOWS_ESCORT_SC); "" is no escort, and such a cart is taken without a fight.
F.ESCORT = DERPY_MR_FLOWS_ESCORT

function F.escort_template(faction) return DERPY_MR_FLOWS_ESCORT_SC[faction:subculture()] end

-- units by the cargo's value at the fixed Sell rates, never the Exchange's market: a shipment's units, or a
-- convoy's whole basket (a bandit fight's guard army)
function F.escort_size(s)
    local worth = 0
    for stem, n in pairs(s.basket or { [s.stem] = s.n }) do
        local g = F.GOOD[stem]
        worth = worth + n * ((g and DERPY_MR_FLOWS_SELL_RATE[g.use]) or 1)
    end
    local n = F.ESCORT.min + math.floor(worth / F.ESCORT.per)
    return math.max(F.ESCORT.min, math.min(F.ESCORT.max, n))
end

-- CA's rule in episode_nagash_sandbox.lua: turn / 10, rounded, 1 to 10
function F.escort_power(turn)
    return math.max(1, math.min(10, math.floor(turn / F.ESCORT.turns + 0.5)))
end

-- OUR OWN TEMPLATE (Cathay), weighted as CA's generate_random_army weights its tiers: low 1, mid
-- the power, high twice the power, with its thresholds.
function F.escort_own(key, power)
    local m = { low = 1, mid = power, high = power * 2 }
    if power <= 2 then m.mid = 0 end
    if power <= 6 then m.high = 0 end
    if power >= 7 then m.low = 0 end
    if power >= 10 then m.mid = 0 end
    random_army_manager:new_force(key)
    for _, u in ipairs(DERPY_MR_FLOWS_ESCORT_OWN) do
        if m[u[3]] > 0 then random_army_manager:add_unit(key, u[1], u[2] * m[u[3]]) end
    end
end

-- STALE KEYS IN CA'S TEMPLATES (wh_main_emp_veh_steam_tank, not _driver) have no variant and no
-- card: taken out of our copy of the force once, when it is made.
function F.escort_prune(key)
    local f = random_army_manager:get_force_by_key(key)
    if not f then return end
    for i = #f.units, 1, -1 do
        if DERPY_MR_FLOWS_ESCORT_DROP[f.units[i]] then table.remove(f.units, i) end
    end
end

-- CA's generate_random_army ADDS to a force it already holds on every call, so it runs once per key
-- per session and later rolls draw from the force it made (its own opt_use_pre_generated_template).
-- The key carries the power: one key for every power would roll every escort at the first one's.
-- `n` units off template `tpl` at `power`, as CA's unit list, or nil. The bandits and the guard army roll here too.
function F.roll_units(tpl, power, n)
    if not tpl or type(random_army_manager) ~= "table" then return nil end
    local key = "derpy_mr_esc_" .. tpl .. "_" .. power
    if tpl == F.ESCORT.own then key = tpl .. "_" .. power end
    if not random_army_manager:get_force_by_key(key) then
        if tpl == F.ESCORT.own then
            F.escort_own(key, power)
        elseif type(WH_Random_Army_Generator) == "table" then
            WH_Random_Army_Generator:generate_random_army(key, tpl, 1, power, true, false)
            F.escort_prune(key)
        else
            return nil
        end
    end
    local units = random_army_manager:generate_force(key, n, false)
    return type(units) == "string" and units or nil
end

function F.escort_roll(faction, s)
    s.escort = F.roll_units(F.escort_template(faction), F.escort_power(cm:model():turn_number()), F.escort_size(s)) or ""
end

function F.ship_by_id(id)
    for _, s in ipairs(F.ships()) do
        if s.id == id then return s end
    end
    return nil
end

F.FIGHT_PREFIX = "derpy_mr_escort_"

function F.escorts_on() return F.rates().escort == true end

-- CA's manager (wh2_campaign_forced_battle_manager.lua) holds one battle at a time, shared with
-- its own episodes; a campaign root that does not load it has no escort or bandit battles at all.
function F.fight_free()
    return F.state.fight == nil and type(Forced_Battle_Manager) == "table" and (Forced_Battle_Manager.active_battle or "") == ""
end

function F.fight_ready() return F.escorts_on() and F.fight_free() end

-- CA's manager: "attacking forces must be able to attack (not garrisoned or in a stance)". It locks
-- the retreat itself for march and double time, so those are allowed; raiding, ambush, encamped and
-- the rest would leave a battle that never starts.
F.CAN_ATTACK = { MILITARY_FORCE_ACTIVE_STANCE_TYPE_DEFAULT = true, MILITARY_FORCE_ACTIVE_STANCE_TYPE_MARCH = true,
                 MILITARY_FORCE_ACTIVE_STANCE_TYPE_DOUBLE_TIME = true }

-- The escort spawns at the cart for its owner and `mf` attacks it: a raid, the player's army; a
-- defence, the enemy's. `taker`: the faction the cargo goes to if the attacker wins.
function F.fight(s, side, mf, taker)
    if not F.fight_ready() or (s.escort or "") == "" then return false end
    if mf:has_garrison_residence() or not F.CAN_ATTACK[mf:active_stance()] then return false end
    local key, fbm = F.FIGHT_PREFIX .. s.id, Forced_Battle_Manager
    fbm.forced_battles_list[key] = nil            -- one left behind by a battle that never started
    local fb = fbm:setup_new_battle(key)
    if not fb then return false end
    fb:add_new_force(key, s.escort, s.f, true)
    F.state.fight = { id = s.id, side = side, key = key, taker = taker, force = mf:command_queue_index(),
                      owner = s.f, turn = cm:model():turn_number() }
    if side == "defend" then
        -- the escort is the player's own new army: no messages for its general
        cm:disable_event_feed_events(true, "wh_event_category_character", "", "")
        -- A RETREAT IS NEVER FOUGHT and would read as the escort's win: locked, as CA locks it for
        -- its caravan battles; the manager's own listener unlocks it. CA's override() is in its lib
        -- (lib_campaign_ui_overrides.lua), not its docs: if it ever answers nil, the battle still starts.
        pcall(function() cm:get_campaign_ui_manager():override("retreat"):lock() end)
    end
    fb:trigger_battle(mf:command_queue_index(), key, s.x, s.y, false)
    return true
end

-- THE ESCORT'S CQI, kept when the battle is about to be fought: CA's manager gives its spawned force
-- one and wipes it again in its own clean-up, which after a reload runs before ours.
function F.on_pending_battle()
    local f = F.state.fight
    if not f or f.escort or type(Forced_Battle_Manager) ~= "table" then return end
    local fb = Forced_Battle_Manager.forced_battles_list[f.key]
    if fb and fb.target and fb.target.cqi then f.escort = fb.target.cqi end
end

-- WHO WON, from CA's cache of the battle just fought: ours only when the attacker AND the escort were
-- in it. CA's entry is left alone - its own handler (often after this one) needs it to remove the
-- escort and free its slot; F.fight_stale prunes it later. An attacker that retreats has not fought,
-- and has not won.
function F.on_battle_done()
    local f = F.state.fight
    if not f then return end
    if not (f.escort and cm:pending_battle_cache_mf_is_involved(f.force)
            and cm:pending_battle_cache_mf_is_involved(f.escort)) then
        -- not ours; and if CA's manager no longer holds ours, that battle will never be fought
        if type(Forced_Battle_Manager) ~= "table" or Forced_Battle_Manager.active_battle ~= f.key then F.fight_clear() end
        return
    end
    F.state.fight = nil
    if f.side == "defend" or f.side == "bandit" then
        cm:callback(function() cm:disable_event_feed_events(false, "wh_event_category_character", "", "") end, 0.2)
    end
    if f.side == "bandit" then return F.bandit_done(f) end
    local s = F.ship_by_id(f.id)
    if not s then return end
    local won = cm:model():pending_battle():has_been_fought() and cm:pending_battle_cache_attacker_victory()
    if won then
        local taker = cm:get_faction(f.taker)
        if taker and not taker:is_null_interface() then F.seize(s, taker) end
    elseif f.side == "defend" then
        local owner = cm:get_faction(s.f)
        if owner and not owner:is_null_interface() then F.ship_step(owner, s, cm:model():turn_number()) end
    end
end

-- A FIGHT THAT WILL NEVER BE FOUGHT: the record goes, and what F.fight set up is undone - the escort,
-- if it spawned, the retreat lock, the muted messages and CA's slot if it is still ours.
function F.fight_clear()
    local f = F.state.fight
    if not f then return end
    F.state.fight = nil
    if type(invasion_manager) == "table" then
        pcall(function() invasion_manager:kill_invasion_by_key(f.key); invasion_manager:remove_invasion(f.key) end)
    end
    pcall(function() cm:get_campaign_ui_manager():override("retreat"):unlock() end)
    if f.side == "defend" or f.side == "bandit" then cm:disable_event_feed_events(false, "wh_event_category_character", "", "") end
    if f.side == "bandit" then F.bandit_kill(f.force) end
    if type(Forced_Battle_Manager) == "table" and Forced_Battle_Manager.active_battle == f.key then
        Forced_Battle_Manager.active_battle = ""
    end
end

-- At a human turn start: a record whose battle never started is cleared, and our finished battles
-- leave CA's saved list (it keeps every battle it was given, and refuses a key it holds).
function F.fight_stale(turn)
    local f = F.state.fight
    if f and f.turn < turn then F.fight_clear() end
    -- A ROAD ENCOUNTER LEFT FROM AN EARLIER TURN (a lost dilemma): cleared, and its bandits removed
    local fkeys = {}
    for fkey in pairs(F.state.pending or {}) do fkeys[#fkeys + 1] = fkey end
    table.sort(fkeys)
    for _, fkey in ipairs(fkeys) do
        for _, e in ipairs(F.ROAD.encounters) do
            local p = F.pending(fkey, "road_" .. e)
            if p and (tonumber(p.turn) or 0) < turn then
                F.clear_pending(fkey, "road_" .. e)
                F.bandit_kill(p.bandit)
            end
        end
    end
    if type(Forced_Battle_Manager) ~= "table" then return end
    local list, active = Forced_Battle_Manager.forced_battles_list, Forced_Battle_Manager.active_battle
    for k in pairs(list) do
        if string.sub(k, 1, #F.FIGHT_PREFIX) == F.FIGHT_PREFIX and k ~= active then list[k] = nil end
    end
end

-- SPAWNING AN ESCORT IS NOT A RECRUIT: its owner's UnitTrained is skipped while a fight is pending
function F.recruit_paused(fkey) return F.state.fight ~= nil and F.state.fight.owner == fkey end

-- ONE RAID OFFER AT A TIME: the answer does not say which cart it is for.
function F.raid_offer(s, ch, captor, owner)
    local fkey, turn = captor:name(), cm:model():turn_number()
    local p = F.pending(fkey, "raid")
    if p and p.turn == turn then return end
    F.set_pending(fkey, { key = "raid", id = s.id, force = ch:military_force():command_queue_index(), turn = turn })
    if not cm:trigger_dilemma_with_targets(captor:command_queue_index(), DERPY_MR_FLOWS_EVENTS.raid.dilemma,
                                           owner:command_queue_index(), 0, 0, 0, 0, 0, function() end) then
        F.clear_pending(fkey, "raid")   -- never issued (multiplayer returns false)
    end
end

-- FIRST: the battle, if the cart and the army are still there and CA's manager is free. Anything
-- else, nothing: a raid the player chose is never a free seizure.
function F.raid_answer(faction, p, choice)
    if choice ~= "FIRST" then return end
    local s = F.ship_by_id(p.id)
    local mf = cm:model():military_force_for_command_queue_index(p.force)
    if not s or mf:is_null_interface() then return end
    F.fight(s, "raid", mf, faction:name())
end

-- ---- bandit battles (design 2026-11-01, Part D 7.3) -------------------------------------------
-- A player's road encounter as CA's caravans run theirs (caravans:attach_battle_to_dilemma): the bandits spawn before
-- the dilemma, the dilemma names them and the region, and the answer either fights through CA's manager, as the escort
-- battles do, or takes the other choice and removes them.
F.ROAD_FIGHT = { ambush = "FIRST", highwaymen = "SECOND" }   -- the choice that fights; the washout never does

-- CA's rule (caravans:event_handler): one of the stretch's regions at random, or the last one owned by a faction at war
-- with the cargo's owner.
function F.road_region(faction, keys)
    local pick = keys[cm:random_number(#keys, 1)]
    for _, k in ipairs(keys) do
        local o = cm:get_region(k):owning_faction()
        if not o:is_null_interface() and o:at_war_with(faction) then pick = k end
    end
    return pick
end

-- The bandits' units: the subculture's escort template at CA's sizes by threat (caravans:generate_attackers).
function F.bandit_units(sc, threat)
    local n
    for _, s in ipairs(F.ROAD.sizes) do
        if s[1] == nil or threat < s[1] then
            n = s[2]
            break
        end
    end
    return F.roll_units(DERPY_MR_FLOWS_ESCORT_SC[sc], F.escort_power(cm:model():turn_number()), n)
end

-- THE BANDITS (caravans:spawn_caravan_battle_force): a quest-battle faction of the land owner's subculture, CA's ogres
-- where there is none, at a valid spot by the cargo; at war with the owner, unable to move and counted as having
-- retreated this turn, with the messages of their war and death muted. The force's cqi, or nil.
function F.bandit_spawn(region_key, x, y, threat, owner)
    local o = cm:get_region(region_key):owning_faction()
    local sc = not o:is_null_interface() and o:subculture() or nil
    if not DERPY_MR_FLOWS_BANDIT_QB[sc] then sc = F.ROAD.qb_sc end
    -- the owner's key, read now: the callback runs when CA has made the force, and keeps no interface
    local owner_key = owner:name()
    -- A RACE'S BANDITS THAT NEVER APPEAR: CA logs the Chaos Dwarf qb1's create_force and makes no army (seen 2026-11-03,
    -- no fight could start on Chaos Dwarf land), so CA's Ogre bandits, the caravans' own, are asked next. A force that
    -- is made calls back at once (measured), so no force by the return is none at all.
    for _, s in ipairs(sc == F.ROAD.qb_sc and { sc } or { sc, F.ROAD.qb_sc }) do
        local qb, units = DERPY_MR_FLOWS_BANDIT_QB[s], F.bandit_units(s, threat)
        local sx, sy
        if units then sx, sy = cm:find_valid_spawn_location_for_character_from_position(qb, x, y, false) end
        if sx and sx >= 0 then
            local force = nil
            cm:create_force(qb, units, region_key, sx, sy, true, function(char_cqi, force_cqi)
                force = force_cqi
                cm:disable_event_feed_events(true, "", "", "diplomacy_faction_destroyed")
                cm:disable_event_feed_events(true, "", "", "character_dies_battle")
                cm:disable_event_feed_events(true, "", "", "diplomacy_war_declared")
                cm:force_declare_war(qb, owner_key, false, false)
                cm:callback(function() cm:disable_event_feed_events(false, "", "", "diplomacy_war_declared") end, 0.2)
                cm:disable_movement_for_character(cm:char_lookup_str(char_cqi))
                cm:set_force_has_retreated_this_turn(cm:get_military_force_by_cqi(force_cqi))
            end)
            if force then return force end
        end
    end
    return nil
end

-- Removed with their force and their messages back on, as caravans:cleanup_post_battle does. The messages come back
-- even when the battle already destroyed them.
function F.bandit_kill(force_cqi)
    if not force_cqi then return end
    local mf = cm:get_military_force_by_cqi(force_cqi)
    if mf and not mf:is_null_interface() and mf:has_general() then
        cm:kill_character(cm:char_lookup_str(mf:general_character():cqi()), true)
    end
    cm:callback(function()
        cm:disable_event_feed_events(false, "", "", "diplomacy_faction_destroyed")
        cm:disable_event_feed_events(false, "", "", "character_dies_battle")
    end, 0.2)
end

function F.convoy_by_id(id)
    for _, c in ipairs(F.convoys()) do
        if c.id == id then return c end
    end
    return nil
end

-- A PLAYER'S ENCOUNTER: the bandits first for one that can come to a fight, then the dilemma naming them and the
-- region. One road encounter waits per faction; while it does, the next is settled at once. False when nothing was
-- offered, and the caller settles it.
function F.road_offer(faction, kind, rec, key, region_key)
    local fkey, pkey = faction:name(), "road_" .. key
    for _, e in ipairs(F.ROAD.encounters) do
        if F.pending(fkey, "road_" .. e) then return false end
    end
    local bandit = nil
    if F.ROAD_FIGHT[key] then
        bandit = F.bandit_spawn(region_key, rec.x, rec.y, rec.threat, faction)
        if not bandit then return false end
    end
    F.set_pending(fkey, { key = pkey, kind = kind, id = rec.id, enc = key, bandit = bandit, region = region_key,
                          turn = cm:model():turn_number() })
    if not cm:trigger_dilemma_with_targets(faction:command_queue_index(), DERPY_MR_FLOWS_EVENTS[pkey].dilemma, 0, 0, 0,
                                           bandit or 0, cm:get_region(region_key):cqi(), 0, function() end) then
        F.clear_pending(fkey, pkey)
        F.bandit_kill(bandit)
        return false
    end
    return true
end

-- THE ANSWER: the fighting choice fights; anything else, or a fight that cannot start, is settled and the bandits
-- go. Push on is the one choice no computer takes: it loses a tenth. The cargo gone, only the bandits go.
function F.road_answer(faction, p, choice)
    local rec = p.kind == "convoy" and F.convoy_by_id(p.id) or F.ship_by_id(p.id)
    if rec and F.ROAD_FIGHT[p.enc] == choice and F.road_fight(faction, p, rec) then return end
    F.bandit_kill(p.bandit)
    if not rec then return end
    if p.enc == "washout" and choice == "SECOND" then return F.cargo_lose(p.kind, rec, F.ROAD.wash_pct) end
    F.road_settle(faction, p.kind, rec, p.enc)
end

-- THE FIGHT, through CA's manager as the escort battles: the cargo's guard army, sized as an escort, spawns for its
-- owner at the cargo and the bandits attack it. False when the manager is busy, the bandits are gone or the owner has
-- no escort template.
function F.road_fight(faction, p, rec)
    local mf = p.bandit and cm:get_military_force_by_cqi(p.bandit)
    if not (F.fight_free() and mf and not mf:is_null_interface()) then return false end
    local units = F.roll_units(F.escort_template(faction), F.escort_power(cm:model():turn_number()), F.escort_size(rec))
    if not units then return false end
    local key, fbm = F.FIGHT_PREFIX .. "road_" .. rec.id, Forced_Battle_Manager
    fbm.forced_battles_list[key] = nil
    local fb = fbm:setup_new_battle(key)
    if not fb then return false end
    fb:add_new_force(key, units, faction:name(), true)
    F.state.fight = { id = rec.id, cargo = p.kind, side = "bandit", key = key, force = p.bandit, owner = faction:name(),
                      turn = cm:model():turn_number() }
    -- the guard army is the player's own new army: no messages for its general; a retreat is never fought
    cm:disable_event_feed_events(true, "wh_event_category_character", "", "")
    pcall(function() cm:get_campaign_ui_manager():override("retreat"):lock() end)
    fb:trigger_battle(p.bandit, key, rec.x, rec.y, false)
    return true
end

-- A BANDIT FIGHT FOUGHT: the bandits won, the whole cargo is lost; either way they are removed and the retreat unlocked.
function F.bandit_done(f)
    local rec = f.cargo == "convoy" and F.convoy_by_id(f.id) or F.ship_by_id(f.id)
    if rec and cm:model():pending_battle():has_been_fought() and cm:pending_battle_cache_attacker_victory() then
        F.cargo_lose(f.cargo, rec, 100)
    end
    F.bandit_kill(f.force)
    pcall(function() cm:get_campaign_ui_manager():override("retreat"):unlock() end)
end

-- The buyer owns the cart and its escort; a contract records the separate exporting faction.
function F.ship(faction, from, to, stem, n, order)
    local fkey = faction:name()
    if not F.GOOD[stem] or not F.stock_number(n) or n <= 0 or not from or not to
        or from:is_null_interface() or to:is_null_interface() or from:name() == to:name() then return nil end
    local seller, terms = faction, nil
    if order then
        local b = F.state.factions[fkey]
        if not (b and b.routes and b.routes[order.id] == order and order.enabled)
            or order.from ~= from:name() or order.to ~= to:name() or order.stem ~= stem then return nil end
        terms = F.route_status(faction, order)
        if not terms then return nil end
        seller = terms.seller
    end
    local partner = order and seller:name() ~= fkey
    if not F.owned(seller, from:name()) or not F.owned(faction, to:name()) then return nil end
    if F.stopped(seller:name(), "export", stem) or F.stopped(fkey, "import", stem) then return nil end
    if F.ship_count(fkey) >= F.ship_cap(faction) then return nil end
    local source = F.stock_view(seller, from)
    if partner and not F.price_mult(source, stem) then return nil end   -- a store of no capacity quotes nothing
    local free = F.free(to, stem) - F.incoming(fkey, to:name(), stem)
    if order then free = math.min(free, order.target - F.held(to, stem) - F.incoming(fkey, to:name(), stem)) end
    local fit = F.fit_delivery(math.min(n, F.CART_MAX, order and order.batch or F.CART_MAX, F.available_stock(source, stem)), free)
    if not fit then return nil end
    n = fit.n
    local got = fit.got
    local R = DERPY_MR_TERRAIN_ROUTES
    local road = R and R.journey and R.journey(from, to) or nil
    -- A BLOCKADE (Part C 6.2): a partner cart does not leave while an enemy army stands on its road
    if partner and F.blockade(seller, faction, road) then return nil, "blockaded" end
    local escrow, price_c = 0, nil
    if partner then
        local c = F.cart_price(seller, from, faction, to, stem)
        escrow, price_c = F.gold(got, c), c
    end
    if partner and escrow <= 0 then return nil end   -- a cart worth under one gold would deliver for nothing
    -- TOLLS (Part C): a partner cart pays the land its road crosses, the buyer on top of the price, on the
    -- delivered units at the seller's local price; a cart between your own settlements pays none
    local due, toll = {}, 0
    if partner then
        local ps = F.local_price(source, stem, seller:name())
        due, toll = F.tolls(F.gold(got, F.sell_price(ps or 0)), F.toll_takers(seller, faction, road))
    end
    -- nothing to pay is never refused: a faction in debt still moves its own goods
    if escrow + toll > 0 and escrow + toll > faction:treasury() then return nil end
    if escrow > 0 and not F.route_gold(faction, -escrow) then return nil end
    if not F.route_goods(from, stem, -n) then
        if escrow > 0 and not F.route_gold(faction, escrow) then error("route escrow rollback failed") end
        return nil
    end
    F.log(seller:name(), stem, KIND.move .. "_out", n)
    F.state.ship_seq = (F.state.ship_seq or 0) + 1
    local s = { id = F.SHIP_PREFIX .. F.state.ship_seq, f = fkey, stem = stem, n = got, from = from:name(),
                to = to:name(), at = cm:model():turn_number(), leg = 1, gross = n, road = road }
    s.duration = F.route_turns(from, to, road)
    s.due = s.at + s.duration
    if order then s.route = order.id end
    if partner then
        s.sender, s.recipient, s.price_c, s.escrow = seller:name(), fkey, price_c, escrow
        order.last_price_c = price_c
    end
    if toll > 0 and F.pay_tolls(fkey, due) then s.tolls = due end
    F.guard_fee(faction, s)
    if road and #road > 0 then s.x, s.y = road[1][1], road[1][2]
    else s.x, s.y = F.spot(fkey, from) end
    F.escort_roll(faction, s)
    F.state.ships = F.state.ships or {}
    local list = F.state.ships
    list[#list + 1] = s
    F.mark(s)
    return s
end

function F.drop(s)
    if F.ship_by_id(s.id) ~= s then return end
    F.route_settle(s, 0)
    local list = F.ships()
    for i, x in ipairs(list) do
        if x == s then table.remove(list, i) break end
    end
    F.unmark(s)
end

-- SEIZED: the cargo goes to the captor's settlement nearest the shipment, as far as it has room;
-- a captor with no settlement destroys it.
function F.seize(s, captor)
    if F.ship_by_id(s.id) ~= s then return end
    F.drop(s)
    F.move(nil, F.nearest(captor, s.x, s.y), s.stem, s.n, KIND.raid, nil, captor:name())
end

-- Every army in the field (no garrison) of a faction at war with `owner`: { fkey, cqi = force, x, y },
-- worked out ONCE PER OWNER PER TURN START (each faction's turn start empties it). F.captor reads it for shipments
-- and convoys alike, so a few hundred convoys do not each rescan every enemy army. Not saved.
-- KEYS AND NUMBERS ONLY (the 1.0 live pass, 2026-11-02): the list outlives the script entry that made it, and an
-- interface kept past its entry is freed memory. Calling is_null_interface() on one crashed the game.
F.enemy_cache = F.enemy_cache or {}
function F.enemy_armies(owner)
    local key, turn = owner:name(), cm:model():turn_number()
    local hit = F.enemy_cache[key]
    if hit and hit.turn == turn then return hit.list end
    local list, wars = {}, owner:factions_at_war_with()
    if type(wars) == "table" or type(wars) == "userdata" then
        for i = 0, wars:num_items() - 1 do
            local o = wars:item_at(i)
            local mfl = o:military_force_list()
            for j = 0, mfl:num_items() - 1 do
                local mf = mfl:item_at(j)
                if not mf:is_armed_citizenry() and mf:has_general() then
                    local ch = mf:general_character()
                    list[#list + 1] = { fkey = o:name(), cqi = mf:command_queue_index(),
                                        x = ch:logical_position_x(), y = ch:logical_position_y() }
                end
            end
        end
    end
    F.enemy_cache[key] = { turn = turn, list = list }
    return list
end

-- An army in the field (no garrison) of a faction at war with the owner, within SHIP.near: the
-- faction and the force. A PLAYER TAKES A COMPUTER'S ESCORTED CART ONLY BY WALKING IN, where the
-- raid is asked first, so a human army standing by one at the computer's turn start is passed over.
function F.captor(owner, s)
    local skip_human = F.escorts_on() and not owner:is_human() and (s.escort or "") ~= ""
    local r2 = F.SHIP.near * F.SHIP.near
    for _, e in ipairs(F.enemy_armies(owner)) do
        local dx, dy = e.x - s.x, e.y - s.y
        if dx * dx + dy * dy <= r2 and not (skip_human and F.is_human(e.fkey)) then
            -- looked up now: a force an escort battle earlier in this turn destroyed is gone
            local mf, f = cm:get_military_force_by_cqi(e.cqi), cm:get_faction(e.fkey)
            if mf and not mf:is_null_interface() and f and not f:is_null_interface() then return f, mf end
        end
    end
    return nil
end

-- ARRIVED: into the destination as far as it has room; a destination lost meanwhile sends it to
-- the owner's settlement nearest it, and an owner with none loses it.
function F.arrive(owner, s)
    if F.ship_by_id(s.id) ~= s then return end
    if s.sender then
        local seller, buyer = F.live(s.sender), F.live(s.recipient)
        local to = buyer and F.owned(buyer, s.to)
        if not to or not F.partners(buyer, seller) then return F.route_return(s) end
        local got = math.min(s.n, F.free(to, s.stem))
        if got > 0 and not F.route_goods(to, s.stem, got) then return F.route_return(s) end
        F.log(s.recipient, s.stem, KIND.move .. "_in", got)
        F.route_settle(s, got)
        F.drop(s)
        return
    end
    F.drop(s)
    local to = F.owned(owner, s.to)
    if not to then
        local r = cm:get_region(s.to)
        local st = r and r:settlement()
        if st and not st:is_null_interface() then
            to = F.nearest(owner, st:logical_position_x(), st:logical_position_y())
        end
    end
    F.move(nil, to, s.stem, s.n, KIND.move, nil, owner:name())
end

-- Arrives, or moves to its second spot; nothing yet on the turn it left.
function F.ship_step(faction, s, turn)
    if F.ship_by_id(s.id) ~= s then return end
    if turn >= F.ship_due(s) then
        F.arrive(faction, s)
    elseif s.road and #s.road > 0 then
        local elapsed, duration = math.max(0, turn - s.at), math.max(1, F.ship_due(s) - s.at)
        local i = math.min(#s.road, 1 + math.floor((#s.road - 1) * elapsed / duration))
        local p = s.road[i]
        if s.x ~= p[1] or s.y ~= p[2] then
            F.unmark(s)
            s.x, s.y = p[1], p[2]
            F.mark(s)
        end
        if elapsed >= math.max(1, math.floor(duration / 2)) then s.leg = 2 end
    elseif turn - s.at >= math.max(1, math.floor((F.ship_due(s) - s.at) / 2)) and s.leg == 1 then
        F.unmark(s)
        local to = F.owned(faction, s.to) or cm:get_region(s.to)
        if to then s.x, s.y = F.spot(faction:name(), to) end
        s.leg = 2
        F.mark(s)
    end
end

-- At its owner's turn start each shipment is fought for, seized, arrives, or moves to its second
-- spot. ONE BATTLE A TURN START: F.fight_ready is false once one starts, so a second cart
-- threatened in the same turn start is seized as before.
function F.ships_turn(faction)
    local fkey, turn = faction:name(), cm:model():turn_number()
    local mine = {}
    for _, s in ipairs(F.ships()) do
        if s.f == fkey then mine[#mine + 1] = s end
    end
    for _, s in ipairs(mine) do
        local seller = s.sender and F.live(s.sender)
        if s.sender and (not F.partners(faction, seller) or not F.owned(faction, s.to)) then
            F.route_return(s)
        else
        if s.escort == nil then F.escort_roll(faction, s) end   -- a save from before escorts
        local captor, force = F.captor(faction, s)
        -- a computer's cart is defended by nobody: computer against computer is a free seizure
        if captor and faction:is_human() and F.fight(s, "defend", force, captor:name()) then
            -- the battle decides: F.on_battle_done moves the cart on or seizes it
        elseif captor then
            F.seize(s, captor)
        else
            local from = s.x and { s.x, s.y }
            F.ship_step(faction, s, turn)
            -- still on the road: one that arrived this turn is off the list
            if F.ship_by_id(s.id) == s then F.road_event(faction, "ship", s, from) end
        end
        end
    end
end

-- ---- agreement convoys (spec 2026-10-23, section 5.1) ---------------------------------------
-- What an agreement carries leaves the exporter as one convoy per partner per turn and rides the road
-- F.reach found for the pair. The record is small: its road is one packed string, "x:y;x:y".
F.CONVOY_PREFIX = "derpy_mr_cv_"

-- A new list, never the one given: F.reach keeps its path in F.reach_known, and the partner's trade in
-- the same turn reads that same table.
function F.reverse(list)
    local out = {}
    for i = #list, 1, -1 do out[#out + 1] = list[i] end
    return out
end

function F.pack_road(path)
    if not path or #path == 0 then return nil end
    local parts = {}
    for i, p in ipairs(path) do parts[i] = p[1] .. ":" .. p[2] end
    return table.concat(parts, ";")
end

function F.unpack_road(s)
    if type(s) ~= "string" then return nil end
    local path = {}
    for x, y in string.gmatch(s, "(%d+):(%d+)") do path[#path + 1] = { tonumber(x), tonumber(y) } end
    if #path == 0 then return nil end
    return path
end

-- A read, like F.ships: only F.convoy_new makes the list.
function F.convoys()
    return F.state.convoys or {}
end

-- A convoy lands at its exporter's turn start; a human buyer, who plays first in the round, has it a turn later.
function F.convoy_due(c)
    local ex, buyer = F.live(c.f), F.live(c.buyer)
    if buyer and buyer:is_human() and not (ex and ex:is_human()) then return c.due + 1 end
    return c.due
end

-- WHAT THE VAULT AND THE MAPS READ (spec 2026-10-23, section 6): one entry for each convoy whose exporter is still alive,
-- in the order the convoys left, each naming the good it carries most of (equal amounts: the lower stem). A dead
-- exporter's convoys stay in the list until a player's turn start sweeps them (F.sweep) and are not on the road in
-- between. A convoy with no position (x, y nil) is still on the road and still listed: the Vault counts it, and only
-- what places a marker (R.links, S.map_model) leaves it out. Every faction's: the consumers pick the viewer's.
-- `due` is the turn the buyer first has the goods (F.convoy_due), which a human buyer finds a turn after the landing.
function F.convoy_cargo()
    local out = {}
    for _, c in ipairs(F.convoys()) do
        if F.live(c.f) then
            local stem, n
            for k, v in pairs(c.basket) do
                if not n or v > n or (v == n and k < stem) then stem, n = k, v end
            end
            out[#out + 1] = { id = c.id, f = c.f, buyer = c.buyer, from = c.from, to = c.to, at = c.at, due = F.convoy_due(c),
                              x = c.x, y = c.y, road = c.road, stem = stem, n = n, basket = c.basket, convoy = true }
        end
    end
    return out
end

-- Hexes on a road. A bridge is one point but as many hexes as the reach search charged it (R.advance: max(1, |dx|, |dy|)).
function F.road_steps(path)
    local steps = 0
    for i = 2, #path do
        steps = steps + math.max(1, math.abs(path[i][1] - path[i - 1][1]), math.abs(path[i][2] - path[i - 1][2]))
    end
    return steps
end

-- Turns on the road: its hexes at F.ROAD_PER_TURN, never under one and never past the trade reach (the
-- reach limit is in hexes too); no road, one turn.
function F.convoy_turns(path)
    if not path then return 1 end
    return math.max(1, math.min(F.rates().reach, math.ceil(F.road_steps(path) / F.ROAD_PER_TURN)))
end

-- The record, filed in F.state.convoys. `path` is as F.reach returned it, which F.reach sorted by region name:
-- turned into a new table when it starts at the buyer, so the road always leaves the exporter's capital.
function F.convoy_new(exporter, buyer, basket, path)
    local from, to = F.capital(exporter), F.capital(buyer)
    -- no settlement on the capital: no position, never a throw, since this runs after a good was debited
    local home, hx, hy = from:settlement(), nil, nil
    if not home:is_null_interface() then hx, hy = home:logical_position_x(), home:logical_position_y() end
    local turn = cm:model():turn_number()
    local c = { f = exporter:name(), buyer = buyer:name(), from = from:name(), to = to:name(),
                basket = basket, at = turn, x = hx, y = hy }
    if path and #path > 0 then
        -- without a position the road cannot be oriented and is kept as F.reach gave it
        if hx then
            if path[1][1] ~= hx or path[1][2] ~= hy then path = F.reverse(path) end
        end
        c.road, c.x, c.y = F.pack_road(path), path[1][1], path[1][2]
    end
    c.due = turn + F.convoy_turns(path)
    F.state.convoy_seq = (F.state.convoy_seq or 0) + 1
    c.id = F.CONVOY_PREFIX .. F.state.convoy_seq
    F.state.convoys = F.state.convoys or {}
    F.state.convoys[#F.state.convoys + 1] = c
    return c
end

-- A saved record the convoy code can read: the number in its id when it can, nil when it cannot. Each rule is a
-- type or a range the code downstream assumes: a basket entry that is not a good, a due that is not a number or an
-- amount that is not whole would throw in F.ships_to, F.stock_view or the turn's step, long after the load.
function F.convoy_sound(c)
    if type(c) ~= "table" or type(c.id) ~= "string" then return nil end
    local n = tonumber(string.match(c.id, "^" .. F.CONVOY_PREFIX .. "(%d+)$"))
    if not (n and F.stock_number(n)) then return nil end
    if not (type(c.f) == "string" and type(c.buyer) == "string" and type(c.from) == "string" and type(c.to) == "string") then return nil end
    if type(c.basket) ~= "table" or next(c.basket) == nil then return nil end
    for stem, k in pairs(c.basket) do
        if not (F.GOOD[stem] and F.stock_number(k) and k > 0) then return nil end
    end
    if not (F.stock_number(c.at) and F.stock_number(c.due) and c.due >= c.at) then return nil end
    -- a position is the pair or nothing: no settlement on the capital and no road writes neither
    if (c.x ~= nil or c.y ~= nil) and not (F.stock_number(c.x) and F.stock_number(c.y)) then return nil end
    if c.road ~= nil and not F.unpack_road(c.road) then return nil end
    if not F.tolls_sound(c.tolls) then return nil end
    return n
end

-- Run from the load callback. A save with no list stays without one (only F.convoy_new makes it); the sequence
-- is the larger of the kept ids and the saved one, as F.sanitize_routes keeps its own, so a delivered
-- convoy's number is not handed out twice.
function F.sanitize_convoys()
    local list, clean, max_id = F.state.convoys, {}, 0
    for _, c in ipairs(type(list) == "table" and list or {}) do
        local n = F.convoy_sound(c)
        if n then clean[#clean + 1] = c; max_id = math.max(max_id, n) end
    end
    F.state.convoys = type(list) == "table" and clean or nil
    F.state.convoy_seq = math.max(max_id, F.stock_number(F.state.convoy_seq) and F.state.convoy_seq or 0)
end

-- ---- stepping, arrival, seizure, return (spec 2026-10-23, section 5.2) -----------------------
-- A convoy comes off the list FIRST in the three that move its goods, as F.arrive and F.seize do: a throw part-way
-- through the moves leaves the goods already moved, never a convoy that moves them again next turn. True only when
-- this call took it off, so a record already gone (delivered, seized, returned) moves nothing a second time.
function F.convoy_drop(c)
    local list = F.convoys()
    for i, x in ipairs(list) do
        if x == c then table.remove(list, i) return true end
    end
    return false
end

-- ARRIVED: into the buyer's capital AS IT STANDS NOW, as far as it has room; what does not fit is lost by the rule
-- F.move keeps. F.convoys_turn has just seen that the buyer lives and has a capital.
function F.convoy_arrive(c)
    if not F.convoy_drop(c) then return end
    local buyer = F.live(c.buyer)
    local to = F.capital(buyer)
    for stem, n in pairs(c.basket) do F.move(nil, to, stem, n, KIND.trade, nil, c.buyer) end
end

-- SEIZED: the basket goes to the captor's settlement nearest the convoy; a captor with none destroys it. The exporter
-- gets no line of its own, as for a seized shipment: its loss was booked as traded out at dispatch.
function F.convoy_seize(c, captor)
    if not F.convoy_drop(c) then return end
    for stem, n in pairs(c.basket) do F.move(nil, F.nearest(captor, c.x, c.y), stem, n, KIND.raid, nil, captor:name()) end
end

-- RETURNED: back to the exporter's settlement nearest the convoy, or its capital when the convoy has no position;
-- an exporter with no settlement loses it.
function F.convoy_return(c)
    if not F.convoy_drop(c) then return end
    local exporter, to = F.live(c.f), nil
    if exporter and c.x then to = F.nearest(exporter, c.x, c.y) elseif exporter then to = F.capital(exporter) end
    for stem, n in pairs(c.basket) do F.move(nil, to, stem, n, KIND.move, nil, c.f) end
end

-- ON THE ROAD: the point a share of the way along it, as F.ship_step reads a shipment's. No road, no move.
function F.convoy_step(c, turn)
    local road = F.unpack_road(c.road)
    if not road then return end
    local elapsed, duration = math.max(0, turn - c.at), math.max(1, c.due - c.at)
    local i = math.min(#road, math.floor((#road - 1) * elapsed / duration) + 1)
    c.x, c.y = road[i][1], road[i][2]
end

-- ONTO TODAY'S ROAD: where convoy c stands on `path`, its pair's road as F.reach gives it now, at the same share of
-- the way it had come on its own road, and the path, turned to leave the exporter (a new table then). Nil with no
-- path, no saved road or place, or a path that does not leave where the convoy left. Live check 2026-10-24: a convoy
-- that left on a 171-hex road sat 17 hexes off the 142-hex one the map drew next turn.
function F.convoy_on(c, path)
    local road = path and F.unpack_road(c.road)
    if not (road and #path > 0) then return nil end
    local s = road[1]
    if path[1][1] ~= s[1] or path[1][2] ~= s[2] then path = F.reverse(path) end
    if path[1][1] ~= s[1] or path[1][2] ~= s[2] then return nil end
    for i, p in ipairs(road) do
        if p[1] == c.x and p[2] == c.y then
            local j = math.floor((#path - 1) * (i - 1) / math.max(1, #road - 1)) + 1
            return path[j][1], path[j][2], path
        end
    end
    return nil
end

-- At its exporter's turn start, before its shipments: each convoy is returned, seized, arrives or moves on. A COPY of
-- the list is walked, since every one of them takes the convoy off it; the list is in id order.
function F.convoys_turn(faction)
    local fkey, turn, mine = faction:name(), cm:model():turn_number(), {}
    for _, c in ipairs(F.convoys()) do
        if c.f == fkey then mine[#mine + 1] = c end
    end
    for _, c in ipairs(mine) do
        local buyer = F.live(c.buyer)
        -- the treaty gone (war included), the buyer dead, or the buyer with no settlement left to receive it
        if not buyer or not F.capital(buyer) or not F.partners(faction, buyer) then F.convoy_return(c)
        else
            -- onto the pair's road of the day first, where the map has drawn it since (R.links), so the army check
            -- and the step read the road the player sees; this turn's answer, which the trade below reads too
            local open, _, path = F.trade_reach(faction, buyer)
            local x, y, road = F.convoy_on(c, open and path)
            if x then c.road, c.x, c.y = F.pack_road(road), x, y end
            -- a convoy with no position has no army near it
            local captor = c.x and c.y and F.captor(faction, c)
            if captor then F.convoy_seize(c, captor)
            elseif turn >= c.due then F.convoy_arrive(c)
            -- still on the road: it follows the buyer's capital, which F.ships_to counts the cargo at
            else
                c.to = F.capital(buyer):name()
                local from = c.x and { c.x, c.y }
                F.convoy_step(c, turn)
                F.road_event(faction, "convoy", c, from)
            end
        end
    end
end

-- A dead faction's turn never starts: its shipments are cleared at a player's.
function F.sweep()
    local list = F.ships()
    for i = #list, 1, -1 do
        local f = cm:get_faction(list[i].f)
        if not f or f:is_null_interface() or f:is_dead() then
            if list[i].sender then F.route_return(list[i]) else F.drop(list[i]) end
        elseif list[i].sender and not F.live(list[i].sender) then
            F.route_return(list[i])
        end
    end
    -- a convoy whose exporter is gone has nobody to return to: it goes, basket and all
    local convoys = F.convoys()
    for i = #convoys, 1, -1 do
        if not F.live(convoys[i].f) then table.remove(convoys, i) end
    end
    -- the Workshop: a dead buyer's upgrades go with it
    for _, ups in pairs(F.state.upgrades or {}) do
        for key, buyer in pairs(ups) do
            local f = cm:get_faction(buyer)
            if not f or f:is_null_interface() or f:is_dead() then ups[key] = nil end
        end
    end
    -- a dead faction's event record and supply switches, kept in the save for nothing
    for _, book in ipairs({ F.state.events or {}, F.state.supply or {} }) do
        for fkey in pairs(book) do
            local f = cm:get_faction(fkey)
            if not f or f:is_null_interface() or f:is_dead() then book[fkey] = nil end
        end
    end
end

-- ---- FOUNDING A RARE BUILDING where no slot offers it (spec 2026-10-09) ---------------------
-- A lore region on a slot template other regions share is offered nothing by a slot; the Vault's
-- settlement view founds the building by script, for CA's gold price, charged only once it stands.
-- The region's slot holding a level of any race's chain of `good`: slot, level, chain; nil, 0, nil.
function F.found_slot(region, good)
    local sl = region:settlement():slot_list()
    for i = 0, sl:num_items() - 1 do
        local s = sl:item_at(i)
        if s:has_building() then
            local b = s:building():name()
            for _, ch in pairs(DERPY_MR_FLOWS_FOUND_CHAIN[good]) do
                local n = string.sub(b, 1, #ch + 1) == ch .. "_" and tonumber(string.sub(b, #ch + 2))
                if n then return s, n, ch end
            end
        end
    end
    return nil, 0, nil
end

-- An empty secondary slot, or nil. Level 1 goes into it with instantly_upgrade_building_in_region,
-- which ignores the slot template; add_building_to_settlement honours it and places nothing here
-- (measured 2026-10-10, TRADE_RESOURCES.md 35a).
function F.found_free(region)
    local sl = region:settlement():slot_list()
    for i = 0, sl:num_items() - 1 do
        local s = sl:item_at(i)
        if s:active() and not s:has_building() and not s:is_working() and s:type() == "secondary" then
            return s
        end
    end
    return nil
end

-- What the drill-down's row shows; nil when there is no row.
function F.found_state(faction, rkey)
    local good = DERPY_MR_FLOWS_FOUND[rkey]
    local chain = good and DERPY_MR_FLOWS_FOUND_CHAIN[good][faction:culture()]
    local region = chain and F.owned(faction, rkey)
    if not region then return nil end
    local slot, level, there = F.found_slot(region, good)
    if there and there ~= chain then return nil end      -- another race's: CA's own rules
    if level >= 3 then return nil end      -- CA's browser will not upgrade it here either (35a, M2)
    local nxt = level + 1
    local st = { good = good, chain = chain, level = level, next = nxt, slot = slot or F.found_free(region),
                 cost = DERPY_MR_FLOWS_FOUND_LEVELS.cost[nxt], tier_need = DERPY_MR_FLOWS_FOUND_LEVELS.req[nxt] }
    local tier = 0
    pcall(function() tier = region:settlement():primary_slot():building():building_level() end)
    if faction:treasury() < st.cost then st.why = "gold"
    elseif tier < st.tier_need then st.why = "tier"
    elseif not st.slot then st.why = "slot" end
    return st
end

-- The request: built, then looked for, and only then charged.
function F.found(faction, rkey)
    local st = F.found_state(faction, rkey)
    if not st or st.why then return end
    local want = st.chain .. "_" .. st.next
    cm:instantly_upgrade_building_in_region(st.slot, want)
    local _s, got = F.found_slot(F.owned(faction, rkey), st.good)
    if got == st.next then
        cm:treasury_mod(faction:name(), -st.cost)
    else
        F.say(faction:name() .. " could not build " .. want .. " in " .. rkey)
    end
end

-- WALKED IN: only an army, and only of a faction at war with the owner. Its own armies and its
-- friends pass by, as does a hero alone.
function F.on_area(context)
    local id, s = context:area_key(), nil
    for _, x in ipairs(F.ships()) do
        if x.id == id then s = x end
    end
    if not s then return end
    local ch = context:family_member():character()
    if ch:is_null_interface() or not ch:has_military_force() then return end
    local owner, captor = cm:get_faction(s.f), ch:faction()
    if not owner or owner:is_null_interface() or not captor:at_war_with(owner) then return end
    if s.escort == nil then F.escort_roll(owner, s) end
    -- A PLAYER IS ASKED before fighting an escort; a computer army, or any army when escorts are
    -- off or the cart has none, takes it as before
    if F.escorts_on() and captor:is_human() and s.escort ~= "" then return F.raid_offer(s, ch, captor, owner) end
    -- A COMPUTER ARMY ON A PLAYER'S ESCORTED CART waits for the player's turn start, where F.ships_turn
    -- finds it within SHIP.near and the escort fights it
    if F.escorts_on() and owner:is_human() and s.escort ~= "" then return end
    F.seize(s, captor)
end

-- SUPPLY THE CAPITAL: a switched-on use the capital holds under SHIP.stand turns of gets one
-- shipment, enough for SHIP.ai_on turns, of the fullest good of that use in the province's other
-- settlements; none while one is already on the road for that use.
function F.standing(faction, p, b, cost)
    local cap, sources = p.capital, {}
    local provinces = F.provinces(faction)
    for _, r in ipairs(p.regions) do
        if r:name() ~= cap:name() then sources[#sources + 1] = F.stock_view(faction, r, provinces) end
    end
    local dest = F.stock_view(faction, cap, provinces)
    for _, k in ipairs(DERPY_MR_FLOWS_SUPPLY_ORDER) do
        local use = DERPY_MR_FLOWS_SUPPLY[k].use
        local have = (dest.totals[use] or 0) + (dest.incoming_use[use] or 0)
        if b[k] and not F.route_covers(faction, cap:name(), use) and have < F.SHIP.stand * cost then
            local from, stem, fh = nil, nil, 0
            for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
                if F.bulk(use)(g) then
                    local source, n = F.fullest(sources, g.stem)
                    if source and (n > fh or (n == fh and (source.region:name() < from.region:name()
                        or (source.region:name() == from.region:name() and g.stem < stem)))) then
                        from, stem, fh = source, g.stem, n
                    end
                end
            end
            if from then
                local free = (dest.capacity[stem] or 0) - (dest.held[stem] or 0) - (dest.incoming[stem] or 0)
                local fit = F.fit_delivery(fh, math.min(free, F.SHIP.ai_on * cost - have))
                if fit then
                    local ship = F.ship(faction, from.region, cap, stem, fit.n)
                    if ship then
                        F.stock_adjust(from, stem, -ship.gross)
                        dest.incoming[stem] = (dest.incoming[stem] or 0) + ship.n
                        dest.incoming_use[use] = (dest.incoming_use[use] or 0) + ship.n
                    end
                end
            end
        end
    end
end

-- A computer-run faction switches a supply on at SHIP.ai_on turns of it, and always supplies its
-- capitals; it is switched off again by running short, as a player's is.
function F.ai_supply(b, capital, cost)
    b.standing = true
    local held = F.stock(capital)
    for _, k in ipairs(DERPY_MR_FLOWS_SUPPLY_ORDER) do
        if not b[k] and F.use_total(held, DERPY_MR_FLOWS_SUPPLY[k].use) >= F.SHIP.ai_on * cost then
            b[k] = true
        end
    end
end

-- PAID FROM THE CAPITAL, OR OFF: a capital short of a whole turn's cost pays nothing, and the
-- switch turns itself off and keeps the turn for its tooltip. Every settlement held in the
-- province gets the bundles paid for, and loses the others at once.
function F.supply(faction)
    local r = F.rates()
    if not r.supply or not F.uses_stores(faction) then return end
    local human = faction:is_human()
    if not (human or r.ai) then return end
    local fkey, turn = faction:name(), cm:model():turn_number()
    local provs, keys = F.provinces(faction)
    for _, pk in ipairs(keys) do
        local p, paid = provs[pk], {}
        local b = F.supply_book(fkey, pk, not human and p.capital ~= nil)
        if b and p.capital then
            local cost = F.SHIP.per * #p.regions
            if not human then F.ai_supply(b, p.capital, cost) end
            if b.standing then F.standing(faction, p, b, cost) end
            for _, k in ipairs(DERPY_MR_FLOWS_SUPPLY_ORDER) do
                if b[k] then
                    local use, held = DERPY_MR_FLOWS_SUPPLY[k].use, F.stock(p.capital)
                    if F.use_total(held, use) < cost then
                        b[k], b.short[k] = nil, turn
                    else
                        F.draw(p.capital, held, use, cost, KIND.spend, fkey)
                        paid[k] = true
                    end
                end
            end
        end
        for _, region in ipairs(p.regions) do
            for _, k in ipairs(DERPY_MR_FLOWS_SUPPLY_ORDER) do
                local bk, rk = DERPY_MR_FLOWS_SUPPLY[k].bundle, region:name()
                if paid[k] then
                    cm:apply_effect_bundle_to_region(bk, rk, F.BUNDLE_TURNS)
                elseif region:has_effect_bundle(bk) then
                    cm:remove_effect_bundle_from_region(bk, rk)
                end
            end
        end
    end
end

-- ---- history ------------------------------------------------------------------------------
-- WHOLE NUMBERS ONLY: a fraction crosses CA's table save as "1,1" under a decimal-comma locale.
function F.push(b, turn, totals, made)
    b.turns[#b.turns + 1] = turn
    for _, g in ipairs(DERPY_MR_FLOWS_GOODS) do
        local t = b.total[g.stem] or {}
        b.total[g.stem] = t
        while #t < #b.turns - 1 do t[#t + 1] = 0 end      -- a good added by an update lines up
        t[#t + 1] = math.floor((totals[g.stem] or 0) + 0.5)
    end
    while #b.turns > F.HISTORY do
        table.remove(b.turns, 1)
        for _, t in pairs(b.total) do table.remove(t, 1) end
    end
    b.last = b.now
    for stem, m in pairs(made) do
        b.last[stem] = b.last[stem] or {}
        b.last[stem].made = math.floor(m + 0.5)
    end
    b.now = {}
end

-- At a human faction's turn start, after the engine has filled the stores.
function F.snapshot(faction)
    local S = DERPY_MR_STORES
    if not (S and S.read_realm) then return end
    local totals, made = {}, {}
    for _, s in ipairs(S.read_realm(faction, true)) do   -- bare: no loc from a turn handler
        for stem, v in pairs(s.held) do totals[stem] = (totals[stem] or 0) + v end
        for stem, v in pairs(s.made) do made[stem] = (made[stem] or 0) + v end
    end
    F.push(F.book(faction:name()), cm:model():turn_number(), totals, made)
end

function F.series(fkey, stem)
    local b = F.state.factions and F.state.factions[fkey]
    if not b then return {}, {} end
    return b.turns, b.total[stem] or {}
end

function F.last(fkey, stem)
    local b = F.state.factions and F.state.factions[fkey]
    return (b and b.last[stem]) or {}
end

-- the turn start keeps what it reads of the stores (F.stock), and drops it when it ends, thrown or not
function F.on_faction_turn_start(faction)
    F.stock_cache = {}
    local ok, e = pcall(F.turn_start, faction)
    F.stock_cache = nil
    if not ok then error(e, 0) end
end

function F.turn_start(faction)
    F.freeze_rates()                              -- frozen at the first turn start
    -- the armies where they stand now: a list made earlier in the round has them where they stood then
    F.enemy_cache = {}
    if faction:is_human() then
        -- ITS OWN GUARD: the snapshot reads through the UI-side CCO and loc, and a throw there must
        -- not skip the trade below, which is model state every machine has to run alike
        F.guard(F.snapshot, faction)
        F.round_cost, F.cost = F.cost, { raid = 0, turn = 0 }
        F.guard(F.sweep)
        F.guard(F.hold_exports, faction:name())   -- a save from before the bundle existed catches up
        F.guard(F.fight_stale, cm:model():turn_number())
    end
    -- This turn's meals eat this turn's rations, so the edicts come first.
    F.guard(F.edict_turn, faction)
    -- Arrivals fund this turn; essentials and elective local orders precede exports.
    F.guard(F.convoys_turn, faction)
    F.guard(F.ships_turn, faction)
    F.guard(F.upkeep, faction)
    F.guard(F.provisions_turn, faction)
    F.guard(F.spoil, faction)                     -- after the meals, before processing and trade
    F.guard(F.provision_supply, faction)
    F.guard(F.supply, faction)
    F.guard(F.economy_turn, faction)
    F.guard(F.economy_supply, faction)
    F.guard(F.routes_turn, faction)
    -- guarded: the trade debits through F.route_goods, which can throw, and the duty after it must still run
    F.guard(F.trade, faction)
    F.guard(F.duty, faction)
    F.guard(F.sales_turn, faction)                -- Part E: the Merchant guild's sale, after the trade
    -- last, on what eating and trading left; its own guard, as an offer is model state too
    F.guard(F.events, faction)
    -- the Workshop's computer purchases, after everything else has used the stores
    F.guard(F.work_ai, faction)
end

function F.guard(fn, a, slot)
    local t0 = os.clock()
    local ok, e = pcall(fn, a)
    if slot then F.cost[slot] = (F.cost[slot] or 0) + os.clock() - t0 end
    if not ok then F.say(e) end
end

function F.init()
    if F.started then return end
    F.started = true
    -- FROZEN AT FIRST TICK: a new campaign fires no FactionTurnStart until turn 1 ends, and MCT
    -- has read the player's settings by now (its LoadingGame callback). A loaded save is frozen.
    F.guard(F.freeze_rates)
    F.guard(F.quiet_dilemmas)
    F.guard(F.name_pending_goods)
    for _,event in ipairs({'FactionLeaderDeclaresWar','PositiveDiplomaticEvent','NegativeDiplomaticEvent','RegionFactionChangeEvent'}) do
        core:add_listener('derpy_mr_reach_'..event,event,true,function() F.invalidate_reach() end,true)
    end
    core:add_listener("derpy_mr_flows_raid", "CharacterTurnStart", true,
        function(context) F.guard(F.on_character_turn_start, context:character(), "raid") end, true)
    core:add_listener("derpy_mr_flows_occupation", "CharacterPerformsSettlementOccupationDecision", true,
        function(context) F.guard(F.on_occupation, context); F.guard(F.on_restore, context) end, true)
    core:add_listener("derpy_mr_flows_battle", "CharacterCompletedBattle", true,
        function(context) F.guard(F.on_battle, context) end, true)
    core:add_listener("derpy_mr_flows_ui", "UITrigger", true,
        function(context) F.guard(F.on_ui_trigger, context) end, true)
    -- a DB dilemma, not a scripted one: matching a scripted dilemma here crashes the game
    core:add_listener("derpy_mr_flows_dilemma", "DilemmaChoiceMadeEvent",
        function(context) return F.EVENT_BY_DILEMMA[context:dilemma()] ~= nil end,
        function(context) F.guard(F.on_dilemma, context) end, true)
    core:add_listener("derpy_mr_flows_ship", "AreaEntered",
        function(context) return string.sub(context:area_key(), 1, #F.SHIP_PREFIX) == F.SHIP_PREFIX end,
        function(context) F.guard(F.on_area, context) end, true)
    core:add_listener("derpy_mr_flows_escort", "BattleCompleted", true,
        function() F.guard(F.on_battle_done) end, true)
    core:add_listener("derpy_mr_flows_escort_pending", "PendingBattle", true,
        function() F.guard(F.on_pending_battle) end, true)
    core:add_listener("derpy_mr_flows_region", "RegionFactionChangeEvent", true,
        function(context) F.guard(F.on_region_change, context:region()) end, true)
    core:add_listener("derpy_mr_flows_force_created", "MilitaryForceCreated", true,
        function(context)
            local id=context:military_force_created():command_queue_index()
            cm:callback(function() F.guard(F.provision_seed_force,cm:get_military_force_by_cqi(id)) end,0.1)
        end,true)
    core:add_listener("derpy_mr_flows_force_destroyed", "MilitaryForceDestroyed", true,
        function(context) F.guard(function() F.provision_clear(tostring(context:military_force():command_queue_index())) end) end, true)
    core:add_listener("derpy_mr_flows_recruit", "UnitTrained", true,
        function(context) F.guard(F.on_unit_trained, context, "recruit") end, true)
    core:add_listener("derpy_mr_flows_turn", "FactionTurnStart", true,
        function(context) F.guard(F.on_faction_turn_start, context:faction(), "turn") end, true)
    F.guard(F.provision_seed_all)
end

cm:add_first_tick_callback(function() F.init() end)

-- FIRST IN CA'S LISTS, NOT APPENDED: cm:saving_game and cm:loading_game call every mod's
-- callback in one unprotected loop, so a mod that throws ahead of this one would stop it and the
-- save would go out without the history (the Zharr Exchange's 2026-10-02 lesson).
local function first(kind, fn)
    local list = cm[kind .. "_game_callbacks"]
    if type(list) == "table" then
        table.insert(list, 1, fn)
    elseif kind == "saving" then
        cm:add_saving_game_callback(fn)
    else
        cm:add_loading_game_callback(fn)
    end
end

first("loading", function(context)
    local ok, t = pcall(function() return cm:load_named_value(F.SAVE, {}, context) end)
    if ok and type(t) == "table" then
        F.state = t
    else
        F.state = {}
        F.say("could not load the stores history: " .. tostring(t))
    end
    F.state.factions = F.state.factions or {}
    F.state.army_issued = F.state.army_issued or {}
    for id in pairs(F.state.armies or {}) do F.state.army_issued[id]=true end
    F.sanitize_stock()
    F.sanitize_routes()
    F.sanitize_ships()
    F.sanitize_convoys()
    F.sanitize_edicts()
    F.sanitize_road()
    F.sanitize_sales()
    F.sanitize_blockades()
end)

first("saving", function(context)
    local ok, e = pcall(function()
        F.state.blockades = F.blockades_kept()
        cm:save_named_value(F.SAVE, F.state, context)
    end)
    if not ok then F.say("could not save the stores history: " .. tostring(e)) end
end)
